# By errno, not type: the Hub client raises OSError subclasses for retryable network errors.
_UNRECOVERABLE_LOCAL_ERRNOS = frozenset(
    {
        errno.EACCES,
        errno.EPERM,
        errno.ENOSPC,
        errno.EROFS,
    }
)

_SPEC_KIND_CAPABILITY: dict[str, str] = {
    "dspark": "supports_dspark",
    "dflash": "supports_dflash",
    "mtp": "supports_mtp",
}


# llama.h: #define LLAMA_DEFAULT_SEED 0xFFFFFFFF
_LLAMA_RANDOM_SEED = 0xFFFFFFFF


def _apply_seeded_llama_request(payload: dict, seed: Optional[int]) -> None:
    """Disable prompt caching for fixed seeds so repeated requests stay reproducible."""
    if seed is None:
        return
    payload["seed"] = seed
    # Compared as uint32: the schemas also accept 4294967295, the same "pick at random".
    if (seed & 0xFFFFFFFF) != _LLAMA_RANDOM_SEED:
        payload["cache_prompt"] = False


_PARAVIRTUAL_DIFFUSION_NO_NGL_ERROR = (
    "This Mac's Metal device is virtualised, where offloaded layers can return "
    "corrupt output, and the installed unsloth_zoo diffusion shim has no --ngl, "
    "so the zero-layer CPU pin cannot be applied and the runner would use Metal "
    "anyway. Run 'unsloth studio update' to get a shim with --ngl, or set "
    "UNSLOTH_ALLOW_PARAVIRTUAL_METAL=1 to keep the GPU on a VM you have verified."
)

_VULKAN_DIFFUSION_GPU_IDS_ERROR = (
    "GPU selection (gpu_ids) is not supported for a DiffusionGemma "
    "GGUF on a Vulkan llama.cpp build: the diffusion runner selects "
    "its device by CUDA physical index, which has no defined mapping "
    "to ggml Vulkan device ordinals. Omit gpu_ids to use the default "
    "device."
)


# llama-server may serve HTTP 200 on CPU when a GPU backend fails to init; classify the log.
# Priority: offload counts, then GPU model buffer lines, then device table (disconfirm only).
_GPU_OFFLOAD_MARKERS = (
    "CUDA",
    "ROCm",
    "ROCM",
    "HIP",
    "Metal",
    "Vulkan",
    "OpenCL",
    "SYCL",
    "MUSA",
    "CANN",
)
_OFFLOADED_LAYERS_RE = re.compile(
    r"offloaded\s+(\d+)\s*/\s*(\d+)\s+layers?\s+to\s+gpu", re.IGNORECASE
)
# llama.cpp #23021 moved libllama INFO (offload counts, device table, buffer sizes) to trace (4).
_LLAMA_TRACE_VERBOSITY = 4
_TRACE_VERBOSITY_HELP_RE = re.compile(r"\b4:\s*trace\b", re.IGNORECASE)
_LOG_VERBOSITY_FLAGS = frozenset(
    {"-lv", "--verbosity", "--log-verbosity", "-v", "--verbose", "--log-verbose", "--log-disable"}
)
_LLAMA_LOG_FULL_BYTES = 64 * 1024 * 1024
# llama.cpp's prefix (stamp optional, colours allowed); a mid-line "x W " is record text.
_ANSI = r"(?:\x1b\[[0-9;]*m)*"
_LOG_LEVEL_TOKEN_RE = re.compile(rf"^{_ANSI}(?:\d+\.\d+\.\d+\.\d+{_ANSI} )?{_ANSI}([A-Z]) ")
# The startup head is never trimmed: its load lines are read for the server's whole life.
_STDOUT_TRIM_AT = 20000
_STDOUT_TAIL_KEEP = 5000
_STDOUT_HEAD_MAX = 5000


def _llama_line_is_warning_or_error(line: str, line_lower: str) -> bool:
    level = _LOG_LEVEL_TOKEN_RE.match(line)
    if level is not None:
        return level.group(1) in "WE"
    return "error" in line_lower or "fail" in line_lower or "warn" in line_lower


def _trace_verbosity_args(caps: dict, extra_args: Optional[Iterable[str]], environ) -> list[str]:
    """``--verbosity 4`` when the build hides load lines at its default and the user chose none."""
    if not caps.get("supports_trace_verbosity"):
        return []
    if _extra_args_set_any_flag(extra_args, _LOG_VERBOSITY_FLAGS):
        return []
    if "LLAMA_ARG_LOG_VERBOSITY" in environ:
        return []
    return ["--verbosity", str(_LLAMA_TRACE_VERBOSITY)]


_GPU_MODEL_BUFFER_RE = re.compile(
    r"\b(?:CUDA|ROCm|ROCM|HIP|SYCL)(\d+)\s+model buffer size\s*=\s*"
    r"([0-9]+(?:\.[0-9]+)?)\s+MiB\b",
    re.IGNORECASE,
)
_DEVICE_ROW_RE = re.compile(
    # MTL: ggml-metal names its devices MTL0, MTL1 (GGML_METAL_NAME), never "Metal".
    r"-\s*(CUDA|ROCm|ROCM|HIP|Metal|MTL|Vulkan|SYCL|OpenCL|MUSA|CANN|CPU)\w*\s*:",
    re.IGNORECASE,
)
_GPU_DEVICE_PREFIXES = (
    "cuda",
    "rocm",
    "hip",
    "metal",
    "mtl",
    "vulkan",
    "sycl",
    "opencl",
    "musa",
    "cann",
)


def parse_gpu_offload_counts(lines: "list[str]") -> "Optional[tuple[int, int]]":
    """``(offloaded, total)`` for the largest-M line, or None; ties keep the first
    line since llama.cpp logs the main model before its drafter."""
    max_total = -1
    offloaded_at_max = 0
    for line in lines:
        match = _OFFLOADED_LAYERS_RE.search(line)
        if not match:
            continue
        offloaded, total = int(match.group(1)), int(match.group(2))
        if total > max_total:
            max_total, offloaded_at_max = total, offloaded
    if max_total <= 0:
        return None
    return offloaded_at_max, max_total


def llama_saw_gpu_device(lines: "list[str]") -> Optional[bool]:
    """Whether llama.cpp's device table (rows after the header) lists a GPU, or None
    with no table. All-CPU means the GPU backend failed to load."""
    after_header = False
    saw_device_row = False
    saw_gpu_device = False
    for line in lines:
        if "device_info:" in line:
            after_header = True
            continue
        if not after_header:
            continue
        match = _DEVICE_ROW_RE.search(line)
        if not match:
            continue
        saw_device_row = True
        if match.group(1).lower().startswith(_GPU_DEVICE_PREFIXES):
            saw_gpu_device = True
    if not saw_device_row:
        return None
    return saw_gpu_device


def classify_gpu_offload_lines(lines: "list[str]") -> Optional[bool]:
    """True if the model landed on a GPU, False if it stayed on CPU despite GPU
    intent, None when the log has no usable signal."""
    # Decide on the largest-M offload line: a drafter on GPU must not mask a CPU main model.
    max_total = -1
    offloaded_at_max = 0
    for line in lines:
        match = _OFFLOADED_LAYERS_RE.search(line)
        if not match:
            continue
        offloaded, total = int(match.group(1)), int(match.group(2))
        if total > max_total or (total == max_total and offloaded > offloaded_at_max):
            max_total, offloaded_at_max = total, offloaded
    if max_total >= 0:
        return offloaded_at_max > 0

    # _Host buffers are CPU-pinned; buffer lines are authoritative over the device table.
    saw_model_buffer = False
    for line in lines:
        if "model buffer size" not in line:
            continue
        saw_model_buffer = True
        if "_Host" not in line and any(m in line for m in _GPU_OFFLOAD_MARKERS):
            return True
    if saw_model_buffer:
        return False

    # device_info lists available devices, not where the model loaded: disconfirm only.
    if llama_saw_gpu_device(lines) is False:
        return False
    return None


def _wsl_system_rocm_lib_dirs() -> "list[str]":
    """System ROCm lib dir(s) to load before a prebuilt's bundled HIP, on WSL.

    The bundled bare-metal HIP can't drive WSL's /dev/dxg and segfaults on the
    first GPU call; the system ROCm libs (libamdhip64 + librocdxg) can, while
    the bundle still supplies libggml-hip / librocblas (gfx1151 kernels).
    Mirrors install_llama_prebuilt._wsl_system_rocm_lib_dirs so a prebuilt that
    passed install validation runs the same at serve time. No-op off a ROCDXG
    WSL host (needs /dev/dxg, "microsoft" /proc/version, librocdxg in /opt/rocm).
    """
    try:
        if not os.path.exists("/dev/dxg"):
            return []
        with open("/proc/version", encoding = "utf-8", errors = "replace") as fh:
            if "microsoft" not in fh.read().lower():
                return []
    except (OSError, UnicodeDecodeError):
        return []
    out: "list[str]" = []
    for d in ("/opt/rocm/lib", "/opt/rocm/lib64"):
        if os.path.exists(os.path.join(d, "librocdxg.so")) or os.path.exists(
            os.path.join(d, "librocdxg.so.1")
        ):
            out.append(d)
    return out


def _bundled_hip_present(binary_dir: str) -> bool:
    """True when a prebuilt bundle ships its own HIP backend library."""
    if not binary_dir:
        return False
    try:
        return any(Path(str(binary_dir)).glob("libggml-hip.so*"))
    except OSError:
        return False


def _native_linux_system_rocm_lib_dirs(binary_dir: str = "") -> "list[str]":
    """System ROCm lib dir(s) to prepend before a prebuilt's bundled HIP, on native Linux.

    The bundled bare-metal HIP runtime can mismatch the host amdkfd driver and crash
    in hsa_init(); prepending the whole system ROCm lib dir loads a driver-matched,
    version-consistent stack (libhsa-runtime64 / libamdhip64 / librocblas) ahead of it.
    The whole dir is deliberate: mixing the bundle's rocBLAS with a different-version
    system HIP/ROCR risks missing symbols, and when it does load_model retries once
    with the bundle only. UNSLOTH_LLAMA_NO_SYSTEM_ROCM=1 skips the prepend up front,
    for a host whose system ROCm lacks this arch. No-op on WSL / non-Linux.
    """
    if os.environ.get("UNSLOTH_LLAMA_NO_SYSTEM_ROCM") == "1":
        return []
    if sys.platform != "linux" or os.path.exists("/dev/dxg"):
        return []
    if not os.path.exists("/dev/kfd"):
        return []
    if not _bundled_hip_present(binary_dir):
        return []
    # Env ROCm roots first so a stale /opt/rocm does not shadow them.
    candidates = []
    for var in ("HIP_PATH", "HIP_PATH_57", "ROCM_PATH"):
        val = os.environ.get(var)
        if val:
            candidates.append(val)
    candidates.append("/opt/rocm")
    out: "list[str]" = []
    seen: "set[str]" = set()
    for base in candidates:
        for lib_sub in ("lib", "lib64"):
            d = os.path.join(base, lib_sub)
            if d in seen:
                continue
            seen.add(d)
            if os.path.exists(os.path.join(d, "libhsa-runtime64.so")) or os.path.exists(
                os.path.join(d, "libhsa-runtime64.so.1")
            ):
                out.append(d)
                # Probe lib too and keep ahead of the bundle, else libamd_comgr binds the bundle's libLLVM.
                for _sub in (lib_sub, "lib"):
                    llvm_lib = os.path.join(base, _sub, "llvm", "lib")
                    if llvm_lib not in seen and os.path.isdir(llvm_lib):
                        seen.add(llvm_lib)
                        out.append(llvm_lib)
    return out


# Artifact = content that cannot be a plan, else a plan with a code block passes and gets wiped.
# Numbered lists are deliberately excluded; keep [\s\S]{...}? bounded to avoid backtracking.
_CLOSED_CODE_FENCE = re.compile(
    r"(?<!`)(?P<bf>`{3,})(?!`)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=bf)`*[ \t]*(?:\r?\n|\Z)"
    r"|(?<!~)(?P<tf>~{3,})(?!~)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=tf)~*[ \t]*(?:\r?\n|\Z)",
    re.IGNORECASE,
)
_CLOSED_MARKUP_ARTIFACT = re.compile(
    r"(?:<!doctype\b[\s\S]{0,200}?)?<html\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</html\s*>"
    r"|<svg\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</svg\s*>",
    re.IGNORECASE,
)
_HAS_ANSWER_ARTIFACT = re.compile(
    # CommonMark: 3+ backticks or tildes to open, at least as many to close on a clean line.
    r"(?<!`)(?P<bf>`{3,})(?!`)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=bf)`*[ \t]*(?:\r?\n|\Z)"
    r"|(?<!~)(?P<tf>~{3,})(?!~)[^\r\n]{0,600}\r?\n[\s\S]{1,4000}?\r?\n[ \t>]*(?P=tf)~*[ \t]*(?:\r?\n|\Z)"
    r"|(?:<!doctype\b[\s\S]{0,200}?)?<html\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</html\s*>"
    r"|<svg\b[^>]{0,600}>[^<]{0,400}<[a-zA-Z!/][\s\S]{0,4000}?</svg\s*>",
    re.IGNORECASE,
)

_FENCE_RUN_RE = re.compile(r"(?<!`)(?P<backticks>`{3,})(?!`)|(?<!~)(?P<tildes>~{3,})(?!~)")
# One list marker may precede the quote: "- > ```py" is a quote in a list item.
_BLOCKQUOTE_PREFIX = re.compile(r"^[ \t]*(?:[-*+]|\d{1,9}[.)])?[ \t]*(?:>[ \t]?)+")
# Language token that makes an inline run an opener; never ends in a dot so "here." is prose.
_FENCE_INFO_STRING_RE = re.compile(r"[A-Za-z][\w+#-]*(?:\.[\w+#-]+)*")
_LIST_MARKER_ONLY = re.compile(r"^[ \t]*(?:[-*+]|\d{1,9}[.)])[ \t]+$")
_ONE_QUOTE_MARKER = re.compile(r"[ \t]*>[ \t]?")


def _has_unclosed_code_fence(text: str) -> bool:
    """True if ``text`` contains a code fence whose closer is missing.

    Models do open a fence mid-line (``First. \\`\\`\\`python``), so an inline
    run counts, but only when it cannot be read as prose instead. A column-0
    fence always counts, blockquoted or not.

    This helper, not `_HAS_ANSWER_ARTIFACT`, is what pairs a quoted closer with
    a quoted opener: the pattern accepts `>` on any closer so a quoted block is
    found at all, and the depth check below rejects the ones that do not match.
    """
    active_char: Optional[str] = None
    active_len = 0
    active_quote = 0
    active_base = 0
    closed_any = False
    for raw_line in text.splitlines():
        # A quote marker four columns in is indented code, not a container.
        lead = raw_line[: len(raw_line) - len(raw_line.lstrip(" \t"))]
        quote = _BLOCKQUOTE_PREFIX.match(raw_line)
        indented_quote = quote is not None and len(lead.expandtabs(4)) > 3
        if indented_quote:
            quote = None
        quote_depth = quote.group(0).count(">") if quote else 0
        line = raw_line[quote.end() :] if quote else raw_line
        runs = list(_FENCE_RUN_RE.finditer(line))
        for index, m in enumerate(runs):
            fence = m.group("backticks") or m.group("tildes")
            trailing = line[m.end() :].strip()
            ch = fence[0]
            prefix = line[: m.start()]
            indent = len(prefix.expandtabs(4))
            blank_prefix = not prefix.strip()
            if active_char is not None:
                # A closer is alone on its line, within 3 columns of the container.
                if (
                    blank_prefix
                    and active_base <= indent <= active_base + 3
                    and ch == active_char
                    and len(fence) >= active_len
                    and quote_depth == active_quote
                    and not trailing
                ):
                    active_char, active_len, active_quote, active_base = None, 0, 0, 0
                    closed_any = True
                continue
            # A later backtick run closes an inline span; other delimiters are info-string text.
            if ch == "`" and any(
                (later.group("backticks") or later.group("tildes"))[0] == ch
                for later in runs[index + 1 :]
            ):
                continue
            if blank_prefix:
                if indent <= 3:
                    active_char, active_len = ch, len(fence)
                    active_quote, active_base = quote_depth, 0
                continue
            # Models open mid-prose fences; only a bare info string marks one, and only before any close.
            in_list = _LIST_MARKER_ONLY.match(prefix) is not None
            if not in_list:
                if indented_quote:
                    continue
                if trailing and not _FENCE_INFO_STRING_RE.fullmatch(trailing):
                    continue
                if closed_any:
                    continue
            active_char, active_len, active_quote = ch, len(fence), quote_depth
            active_base = indent if in_list else 0
    return active_char is not None


def _has_unclosed_markup_block(text: str) -> bool:
    """True if ``text`` opens an <html>/<svg> block without closing it.

    Counted rather than matched, so a closed block followed by a still-open one
    also qualifies.
    """
    opens_html = len(re.findall(r"<html\b", text, re.IGNORECASE))
    closes_html = len(re.findall(r"</html\s*>", text, re.IGNORECASE))
    if opens_html > closes_html:
        return True
    opens_svg = len(re.findall(r"<svg\b", text, re.IGNORECASE))
    closes_svg = len(re.findall(r"</svg\s*>", text, re.IGNORECASE))
    return opens_svg > closes_svg


# "First, I'll create an <html></html> skeleton" is a plan, not a page.
_EMPTY_MARKUP_SKELETON = re.compile(
    r"<(html|svg)\b[^>]*>\s*</\1\s*>",
    re.IGNORECASE,
)
_DOCTYPE_PREFIX = re.compile(
    r"^<!doctype\b[\s\S]{0,200}?>",
    re.IGNORECASE,
)


def _is_empty_markup_skeleton(matched: str) -> bool:
    """True if ``matched`` is an empty <html></html> / <svg></svg>, doctype
    prefix and surrounding whitespace allowed."""
    candidate = _DOCTYPE_PREFIX.sub("", matched.strip(), count = 1).strip()
    return _EMPTY_MARKUP_SKELETON.fullmatch(candidate) is not None


def _is_blank_fence(matched: str, depth: int = 0) -> bool:
    """True if ``matched`` is a fence whose body is only whitespace.

    The delimiters are on the first and last lines, so what sits between them is
    the answer, and a block holding a single space is no more one than an empty
    `<html></html>` is a page."""
    if matched[:1] not in ("`", "~"):
        return False
    lines = matched.splitlines()
    # A deeper last line means the match stopped on a nested delimiter in the body.
    closing = _BLOCKQUOTE_PREFIX.match(lines[-1]) if lines else None
    if (closing.group(0).count(">") if closing else 0) != depth:
        return False
    for line in lines[1:-1]:
        for _ in range(depth):
            marker = _ONE_QUOTE_MARKER.match(line)
            if marker is None:
                break
            line = line[marker.end() :]
        if line.strip():
            return False
    return True


def _first_real_artifact(text: str):
    """First _HAS_ANSWER_ARTIFACT match with something in it.

    Every match is inspected, so a skeleton followed by a real page counts."""
    for m in _HAS_ANSWER_ARTIFACT.finditer(text):
        if _is_empty_markup_skeleton(m.group(0)):
            continue
        line_start = text.rfind("\n", 0, m.start()) + 1
        quote = _BLOCKQUOTE_PREFIX.match(text[line_start : m.start()])
        depth = quote.group(0).count(">") if quote else 0
        if _is_blank_fence(m.group(0), depth):
            continue
        return m
    return None


def _strip_markup_outside_fences(text: str) -> str:
    """Drop complete <html>/<svg> blocks, except ones that BEGIN inside a fence.

    An opening tag inside a code example is that example's content, and pairing it
    with a closing tag in the prose after the fence swallowed the fence's own closer:
    ``` ```html\\n<html>\\n``` \\nClose it with </html>.``` then read as unfinished. A
    block that merely encloses a fence is still a real block and goes whole, so a page
    holding a Markdown example is not left in pieces.
    """
    fences = [m.span() for m in _CLOSED_CODE_FENCE.finditer(text)]

    def _keep_examples(m):
        # Either endpoint inside a fence makes the match that example's content.
        return m.group(0) if any(s <= m.start() < e or s < m.end() <= e for s, e in fences) else ""

    return _CLOSED_MARKUP_ARTIFACT.sub(_keep_examples, text)


# A reasoning opener ends at a tag boundary: "<think-card>" is an element of the
# answer, not a thought.
_THINK_OPEN_RE = re.compile(r"<think[\s>]")
_THINKING_OPEN_RE = re.compile(r"<thinking[\s>]")
_BRACKET_THINK_OPEN_RE = re.compile(r"\[THINK\]")


def _artifact_spans(text: str) -> "list[tuple[int, int]]":
    """Spans of the complete fences and complete markup in ``text``."""
    return [m.span() for m in _CLOSED_CODE_FENCE.finditer(text)] + [
        m.span() for m in _CLOSED_MARKUP_ARTIFACT.finditer(text)
    ]


def _find_outside_artifacts(
    text: str,
    needle: str,
    spans = None,
) -> int:
    """First index of ``needle`` that is not inside a complete artifact, or -1.

    A reasoning marker shown in a code example is the example, not reasoning.

    The scan comes first: most answers carry no reasoning marker at all, and
    mapping the artifacts is two regex passes over the whole response.
    """
    at = text.find(needle)
    if at < 0:
        return -1
    if spans is None:
        spans = _artifact_spans(text)
    while at >= 0:
        if not any(start <= at < end for start, end in spans):
            return at
        at = text.find(needle, at + 1)
    return -1


def _text_outside_think(text: str) -> str:
    """``text`` with a LEADING reasoning block dropped, leaving what the user was told.

    Only a leading block is reasoning. The loop folds `reasoning_content` in as one
    prefix per turn, so that is the only provenance genuine reasoning has, and a
    `<think>` further in is the model quoting the tag in an example; the Anthropic
    path reads it the same way (`routes/inference.py` `_split_think_segments`). A
    prefilled template sends the opener itself, so the block may arrive carrying
    only its closer.
    """
    stripped = text.lstrip()
    pairs = (
        (_THINKING_OPEN_RE, "<thinking", "</thinking>"),
        (_THINK_OPEN_RE, "<think", "</think>"),
        (_BRACKET_THINK_OPEN_RE, "[THINK]", "[/THINK]"),
    )
    # Settle the leading opener first: its block may name another marker.
    for lead, _opener, closer in pairs:
        if lead.match(stripped):
            # First closer, plainly, matching _split_think_segments in routes/inference.py.
            close = text.find(closer)
            return text[close + len(closer) :] if close >= 0 else ""
    # No leading opener: a bare closer comes from a template that prefilled the opener.
    spans = None
    for lead, _opener, closer in pairs:
        if closer in text and spans is None:
            spans = _artifact_spans(text)
        close = _find_outside_artifacts(text, closer, spans)
        if close >= 0 and not lead.search(text[:close]):
            return text[close + len(closer) :]
    return text


def _has_answer_artifact(text: str) -> bool:
    """True if ``text`` looks like a completed answer artifact.

    A closed code fence, a complete HTML page, or a complete SVG, and none of them
    left unfinished. Empty skeletons do not count.
    """
    # Strip closed artifacts first: tags or backticks inside finished code are content.
    if _has_unclosed_code_fence(_strip_markup_outside_fences(text)):
        return False
    # Nested pages are deliberately not inspected; that needs an HTML parser.
    return _first_real_artifact(text) is not None


# High floor for reasoning-heavy GGUFs and clients that omit max_tokens.
_DEFAULT_MAX_TOKENS_FLOOR = 32768
_DEFAULT_FIRST_TOKEN_TIMEOUT_S = 1200.0


def _conversation_recall_reserve(thread_id: Optional[str]) -> int:
    """Room to hold back during a fit for the turns recalled straight after it."""
    if not thread_id:
        return 0
    try:
        from core.rag import config as rag_config
        from core.rag import conversation_archive

        # Temporary chats are never archived, so do not reserve room for recall.
        if not conversation_archive.can_archive(thread_id):
            return 0
        # sqlite-vec may exist while the embedder fails; reserving then only loses history.
        if conversation_archive.degraded():
            return 0
        return max(0, int(rag_config.CONVERSATION_RECALL_RESERVE_TOKENS))
    except Exception:
        return 0


def _keeps_compaction_boundary(thread_id: Optional[str]) -> bool:
    """Whether this request's boundary will be there to restore next time.

    The boundary rides on the assistant turn's saved metadata, so a thread with no saved
    messages (incognito, or an API caller that persists nothing) never gets one back. The
    fit uses this to decide whether cutting deeper than needed buys anything.
    """
    if not thread_id:
        return False
    try:
        from storage import studio_db
        return bool(studio_db.chat_thread_has_messages(str(thread_id)))
    except Exception:
        return False


def _archive_branch_transcript(
    branch_messages: Optional[list[dict]], roles: Optional[tuple[str, ...]] = None
) -> Optional[list[str]]:
    """The active branch, one normalised string per message, or None if there is nothing."""
    if not branch_messages:
        return None
    try:
        from core.rag import conversation_archive
        return conversation_archive.branch_message_texts(branch_messages, roles)
    except Exception:
        return None


def _branch_boundary(conversation: list[dict], branch: Optional[list[dict]]) -> int:
    """How many of the REQUEST's own leading messages a fit has evicted.

    The boundary is persisted and re-applied to the NEXT request's saved transcript, so it
    must be counted in those terms. ``dropped_messages`` is not: the tool loop refits each
    iteration and the client sums the counts, so a long agent run also counts the tool
    exchanges it created, which the next request's transcript does not contain.

    Counted by identity. Instruction messages are skipped rather than treated as the front
    of the branch, or an Unsloth request (always system-prefixed) would report zero on every
    compaction and the boundary would slide every turn again. Everything from the newest
    USER turn on is excluded: it is never evicted, and an inline recall rewrites that turn
    into a new dict, which an identity scan reads as an eviction. Excluding just the last
    message is not the same thing, since a continued assistant message follows it.

    Every evicted message is counted, not just the leading run, because that is what the
    replay consumes: ``truncate_oldest_messages``'s ``min_dropped`` counts dropped messages
    and SKIPS protected groups. Stopping at the first survivor matched that only while
    eviction was a clean prefix, which a protected group (an instruction pin, an anchored
    recall) breaks, leaving live turns on both sides. Under a checkpoint reset that
    understated the boundary enough to un-compact the epoch: the removed turns returned on
    the next request, one turn after the user was told they were compacted away. Where
    eviction IS a prefix, which is every pin-free rolling case, the count is unchanged.
    """
    messages = list(branch or ())
    cutoff = max(
        (index for index, message in enumerate(messages) if message.get("role") == "user"),
        default = max(0, len(messages) - 1),
    )
    messages = messages[:cutoff]
    live = {id(message) for message in conversation}
    count = 0
    for message in messages:
        if message.get("role") in ("system", "developer"):
            continue
        if id(message) not in live:
            count += 1
    return count


def _records_boundary(truncation: dict) -> bool:
    """Whether a fit removed turns from the prompt it sent, so its depth is worth saving.

    Not ``fits``: a rescue reports false yet really did evict, and the client reads this
    depth to place the compaction notice, so recording nothing compacts silently. Saving
    is not replaying -- `_sticky_compaction_boundary` still declines any `fits` false
    record, which is where a missed reserve belongs.
    """
    return bool(truncation.get("fits")) or bool(truncation.get("dropped_messages"))


def _effective_headroom_ratio(compaction_headroom_ratio: Optional[float] = None) -> float:
    """The extra-trim share this request's rolling fit actually used."""
    ratio = clamp_compaction_headroom_ratio(compaction_headroom_ratio)
    return _COMPACTION_HEADROOM_RATIO if ratio is None else ratio


def _boundary_metadata(
    fitted: list[dict],
    before: Optional[list[dict]],
    compaction_headroom_ratio: Optional[float] = None,
) -> dict:
    """Where this fit put the boundary, and under how much extra trim.

    The ratio rides with the depth because the depth cannot be read without it: phase one
    of `fit_rolling_context` re-applies the saved count before anything else and stops once
    the result fits, so a chat whose setting has moved either way would replay the old cut
    and never reach the phase that consults the new one.
    """
    return {
        "boundary_messages": _branch_boundary(fitted, before),
        "boundary_anchor": _branch_boundary_anchor(fitted, before),
        "boundary_headroom_ratio": _effective_headroom_ratio(compaction_headroom_ratio),
    }


def _branch_non_system(branch: Optional[list[dict]]) -> list[dict]:
    """The branch as ``_branch_boundary`` counts it: system and developer turns removed."""
    return [
        message for message in (branch or ()) if message.get("role") not in ("system", "developer")
    ]


def _branch_boundary_anchor(conversation: list[dict], branch: Optional[list[dict]]) -> str:
    """The text of the first message a fit kept AFTER everything it dropped, or "".

    ``boundary_messages`` is a count against one particular transcript, and the next
    request's transcript is not guaranteed to be that one plus new turns: deleting an
    already-evicted prompt shortens the front, so replaying the count unchanged lands the
    boundary two messages too deep and evicts history that is still live. The anchor names
    the message the boundary was meant to land ON, which survives a deletion in front of it.

    After the LAST eviction, not simply the first survivor. Eviction is a clean prefix only
    while nothing is protected mid-list; an instruction pin or an anchored recall leaves
    live turns on both sides, and the first survivor is then the pin itself, sitting near
    the front. `_sticky_compaction_boundary` clamps the count down to the anchor's index,
    so anchoring on the pin cut the replayed boundary back to the pin and handed back every
    turn compacted after it -- one turn after the user was told they were compacted away,
    which is the same un-compaction `_branch_boundary`'s own count was fixed to prevent.

    Text, not an id or an index: ids are per-request objects and an index is the very thing
    that goes stale. Read back by ``_sticky_compaction_boundary``, which only ever lets the
    anchor make the boundary SHALLOWER, so a stale or ambiguous anchor costs one extra
    compaction and can never evict a live turn.
    """
    messages = _branch_non_system(branch)
    live = {id(message) for message in conversation}
    last_dropped = max(
        (index for index, message in enumerate(messages) if id(message) not in live),
        default = -1,
    )
    for message in messages[last_dropped + 1 :]:
        if id(message) in live:
            return _anchor_text(message)
    return ""


_ANCHOR_ARGS_CHARS = 200
# Anchor rides in every event and persisted turn, so keep only a head.
_ANCHOR_TEXT_CHARS = 200


def _anchor_text(message: dict) -> str:
    """A message as the anchor spells it: its text, or its tool calls when it has none.

    A normal OpenAI assistant tool-call message carries empty ``content`` and puts its
    substance in ``tool_calls``. Reading only ``content`` recorded an empty anchor there,
    which silently disables the rebase: the next request cannot re-derive the boundary
    against a shortened transcript and replays the stale count, evicting one more live
    message per deleted one. Both sides of the comparison use this, so what is written is
    what is looked for.
    """
    text = _archive_message_text(message.get("content"))
    if text:
        return text[:_ANCHOR_TEXT_CHARS]
    parts = []
    for call in message.get("tool_calls") or ():
        function = (call or {}).get("function") or {}
        name = str(function.get("name") or "tool")
        arguments = str(function.get("arguments") or "").strip()[:_ANCHOR_ARGS_CHARS]
        parts.append(f"{name}: {arguments}" if arguments else name)
    return "\n".join(parts)[:_ANCHOR_TEXT_CHARS]


def _archive_message_text(content) -> str:
    """One stored message flattened the way the branch check flattens it, or ""."""
    try:
        from core.rag import conversation_archive
        return conversation_archive.message_text(content)
    except Exception:
        return ""


def _archive_content_on_branch(content, transcript: Optional[list[str]]) -> bool:
    if transcript is None:
        return True
    try:
        from core.rag import conversation_archive
        return conversation_archive.content_on_branch(content, transcript)
    except Exception:
        return True


def _row_replayed(message: dict) -> bool:
    """Whether the client re-sends this reply, by `isAbandonedAssistantTurn`.

    Status is not the test: a Stop that reached text is kept, and only a reply carrying
    nothing is dropped -- along with the tool results its wire projection would expand to.
    A turn that FINISHED on reasoning alone is a reply too, replayed as `reasoning_content`,
    even though `_as_wire` strips reasoning and leaves it nothing to be matched on.
    """
    if message.get("role") != "assistant":
        return True
    content = message.get("content")
    if isinstance(content, str):
        return bool(content.strip())
    reasoning = False
    for part in content or ():
        if not isinstance(part, dict):
            continue
        if part.get("type") == "text" and str(part.get("text") or "").strip():
            return True
        if part.get("type") in ("image", "image-url", "file"):
            return True
        reasoning = reasoning or part.get("type") == "reasoning"
    if reasoning and not _row_ended_early(message):
        return True
    return bool(message.get("attachments"))


def _row_ended_early(message: dict) -> bool:
    """`assistantTurnEndedEarly`: the persisted marker, since status is session state."""
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    return bool(metadata.get("incomplete") or custom.get("incomplete"))


def _archive_branch_chain(
    messages: list[dict], branch_messages: Optional[list[dict]]
) -> Optional[list[dict]]:
    """The stored parent chain selected by this wire branch, when ancestry can prove one."""
    if not branch_messages:
        return None
    try:
        from core.rag import conversation_archive

        def _chain(probe):
            return conversation_archive._active_chain(
                messages,
                probe,
                fallback = False,
                require_unique = True,
            )

        chain = _chain(branch_messages)
        if not chain:
            return None
        # The unstored newest turn only matches on a SIBLING, so settled turns pick the branch.
        settled = list(branch_messages)
        while settled and settled[-1].get("role") == "user":
            settled.pop()
        if settled:
            proof = _chain(settled)
            if not proof:
                return None
            tip = proof[-1].get("id")
            if not any(row.get("id") == tip for row in chain):
                return None

            # Rows past the tip may only match the unstored turns' text, keyed by role.
            def _keys(rows):
                return [
                    (wire.get("role"), _archive_message_text(wire.get("content")))
                    for wire in conversation_archive._as_wire(list(rows))
                ]

            carried = set(_keys(branch_messages[len(settled) :]))
            past_tip = False
            for row in chain:
                if past_tip:
                    checked = False
                    for key in _keys([row]):
                        if not key[1]:
                            continue
                        if key not in carried:
                            return None
                        checked = True
                    # Only a reply the client drops whole may ride unchecked; refuse re-sent ones.
                    if not checked and _row_replayed(row):
                        return None
                past_tip = past_tip or row.get("id") == tip
        return chain
    except Exception:
        return None


def _archive_as_wire(messages: Optional[list[dict]]) -> list[dict]:
    """Project persisted rows and wire messages into boundary-counting wire units.

    Unsanitised: `_branch_boundary_anchor` writes the anchor off the request itself, so a
    projection that rewrote assistant text here would look for something nobody wrote. A
    client sending the tokens raw, which the Studio one never does, then found no anchor
    and replayed the stale count instead of rebasing it.
    """
    try:
        from core.rag import conversation_archive
        return conversation_archive._as_wire(list(messages or ()), sanitise_assistant = False)
    except Exception:
        return list(messages or ())


class _CompactionBranchState(NamedTuple):
    message: dict
    truncation: Optional[dict]
    recorded: int


def _reply_text(content) -> str:
    """A stored reply's visible text, which a Max Tokens continuation re-sends verbatim."""
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    return "".join(
        str(part.get("text") or "")
        for part in content
        if isinstance(part, dict) and part.get("type") == "text"
    )


def _row_truncation(message: dict) -> Optional[dict]:
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    truncation = metadata.get("contextTruncation") or custom.get("contextTruncation")
    return truncation if isinstance(truncation, dict) else None


# The auto-continue limit is 3 rounds; a manual Continue chain longer than this keeps its refusal.
_RESUME_HOPS = 8
_RESUME_SIBLINGS = 16


def _max_tokens_cut(message: dict) -> bool:
    metadata = message.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    custom = metadata.get("custom")
    custom = custom if isinstance(custom, dict) else {}
    incomplete = metadata.get("incomplete") or custom.get("incomplete")
    reason = incomplete.get("reason") if isinstance(incomplete, dict) else incomplete
    return reason == "length"


def _row_key(row: dict):
    return row.get("id") or id(row)


def _resumable_cuts(stored: list[dict]) -> dict:
    """Max Tokens cuts per parent: ([positions], [rows]) in creation order."""
    cuts: dict = {}
    for position, row in enumerate(stored):
        if row.get("role") == "assistant" and _max_tokens_cut(row):
            at, rows = cuts.setdefault(row.get("parentId", row.get("parent_id")), ([], []))
            at.append(position)
            rows.append(row)
    return cuts


def _resumed_reply(message: dict, cuts: dict, positions: dict) -> dict:
    """The reply an unfitted Max Tokens continuation resumed: its refusal records no epoch,
    but the epoch in force is still the resumed reply's."""
    for _ in range(_RESUME_HOPS):
        truncation = _row_truncation(message)
        if (
            truncation is None
            or truncation.get("fits")
            or truncation.get("latest_turn_role") != "assistant"
        ):
            return message
        position = positions.get(_row_key(message))
        if position is None:
            return message
        text = _reply_text(message.get("content"))
        at, rows = cuts.get(message.get("parentId", message.get("parent_id")), ((), ()))
        end = bisect.bisect_left(at, position)
        earlier = rows[max(0, end - _RESUME_SIBLINGS) : end]
        source = next(
            (
                row
                for row in reversed(earlier)
                if (resumed := _reply_text(row.get("content")).rstrip())
                and text.startswith(resumed)
            ),
            None,
        )
        if source is None:
            return message
        message = source
    return message


def _compaction_branch_states(
    stored: list[dict], branch_messages: Optional[list[dict]] = None
) -> list[_CompactionBranchState]:
    """Newest authoritative compaction state(s) on one request branch.

    Multiple rows are returned only when Retry siblings are textually indistinguishable;
    consumers must then choose the conservative result across all of them.
    """
    # Assistant rows only: an abandoned "Done" rides in on a live "not done yet".
    branch = _archive_branch_transcript(branch_messages, ("assistant",))
    if branch_messages and not branch:
        return []

    chain = _archive_branch_chain(stored, branch_messages)
    candidates = [
        message
        for message in reversed(chain if chain is not None else stored)
        if message.get("role") == "assistant"
        and (chain is not None or _archive_content_on_branch(message.get("content"), branch))
    ]
    if not candidates:
        return []

    # Exact first: the branch check is a substring test, so "Done" matches "Not done yet".
    if chain is None:
        live = set(branch or ())
        exact = [
            message
            for message in candidates
            if _archive_message_text(message.get("content")) in live
        ]
        if exact:
            candidates = exact

    # A COMPLETED row with no truncation ends the epoch; only active/aborted are placeholders.
    cuts = _resumable_cuts(stored)
    positions = {_row_key(row): position for position, row in enumerate(stored)}
    states = []
    for message in candidates:
        metadata = _resumed_reply(message, cuts, positions).get("metadata")
        metadata = metadata if isinstance(metadata, dict) else {}
        custom = metadata.get("custom")
        custom = custom if isinstance(custom, dict) else {}
        truncation = metadata.get("contextTruncation") or custom.get("contextTruncation")

        recorded = None
        if isinstance(truncation, dict):
            raw_recorded = truncation.get("boundary_messages")
            if raw_recorded is None:
                raw_recorded = truncation.get("dropped_messages")
            if raw_recorded is not None:
                try:
                    recorded = max(0, int(raw_recorded or 0))
                except (TypeError, ValueError):
                    pass
        if recorded is None and chain is not None:
            # Skipping defers to the previous epoch, so it needs a proved branch.
            research_row = (
                (metadata.get("serverManaged") or custom.get("serverManaged"))
                and (metadata.get("researchRunId") or custom.get("researchRunId"))
                and (metadata.get("researchStatus") or custom.get("researchStatus"))
            )
            if research_row:
                continue
            status = metadata.get("generationStatus") or custom.get("generationStatus")
            incomplete = metadata.get("incomplete") or custom.get("incomplete")
            reason = incomplete.get("reason") if isinstance(incomplete, dict) else incomplete
            active = status in {"queued", "running", "cancelling"}
            aborted = status in {"cancelled", "failed"} or reason in {"cancelled", "interrupted"}
            if active or (status != "completed" and aborted):
                continue
        if recorded is None:
            states.append(_CompactionBranchState(message, None, 0))
            continue
        states.append(_CompactionBranchState(message, truncation, recorded))

    if not states:
        return []
    if chain is not None:
        return states[:1]
    newest = _archive_message_text(states[0].message.get("content"))
    return [
        state for state in states if _archive_message_text(state.message.get("content")) == newest
    ]


def _sticky_compaction_state(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> tuple[int, bool]:
    """How many leading messages this thread last compacted away, and who compacted them.

    The provenance decides which fitter may consume the count. A rolling boundary handed
    to `fit_checkpoint_context` reads as an epoch already in force, so the fit returns
    `checkpoint_started` false and `_archive_and_recall` skips the recall the rolling
    fallback would have run. Mixed provenance across surviving rows counts as rolling:
    `min(boundaries)` below may pick either row, so the safe reading is the one that still
    recalls.

    The fit is otherwise stateless: the client re-sends the whole transcript each request,
    so "keep the newest N tokens" slides forward every turn, which tells the user nothing
    useful and throws away llama-server's prefix cache each time the head moves. Reading
    the boundary back makes compaction an occasional event.

    Read from the thread's newest assistant turn, which already persists this number for
    the UI, so nothing new is stored and it survives a restart. Never raises: no history,
    a non-persisting API client, or a storage error all mean "no boundary".
    """
    if not thread_id:
        return 0, False
    requested_ratio = _effective_headroom_ratio(compaction_headroom_ratio)
    try:
        from storage import studio_db

        stored = list(studio_db.list_chat_messages(thread_id) or [])
        states = _compaction_branch_states(stored, branch_messages)
        if not states:
            return 0, False

        boundaries = []
        origins = []
        branch_wire = _archive_as_wire(branch_messages)
        for state in states:
            truncation = state.truncation
            recorded = state.recorded
            if truncation is None:
                return 0, False
            if not truncation.get("fits"):
                return 0, False
            # A provider-generated summary boundary is display metadata, not a local-fit epoch. On a provider/model
            # switch the opaque summary is deliberately withheld, so replaying its boundary here would discard the
            # original turns without retaining their summary.
            if truncation.get("summarized") is True:
                return 0, False
            # A boundary is valid only under the fit that will consume it, and the two
            # directions fail differently.
            #
            # A checkpoint boundary is the depth of a RESET, affordable only because the
            # block is rebuilt on every replay. Under rolling nothing rebuilds it, so the
            # depth replays with nothing handed back (18 evicted where rolling picks 6).
            # Refused HERE, not at the fit: `boundary_messages` is re-recorded every turn,
            # so a rolling turn that inherited 18 would persist it with no `checkpoint` key
            # and make the reset-sized window permanent.
            #
            # The other way, a rolling boundary reaching `fit_checkpoint_context` reads as
            # an epoch already in force, so the reset returns `checkpoint_started` false
            # and the automatic recall never runs. That only happens where the request may
            # actually reset; `_can_reset_epoch` false means the fit stays rolling whatever
            # the process policy says, and there the rolling boundary is the right one to
            # replay. Rejecting it there instead let the boundary slide every turn for any
            # model whose template cannot render tools.
            recorded_checkpoint = bool(truncation.get("checkpoint"))
            effective_checkpoint = _request_uses_checkpoint(context_policy)
            if recorded_checkpoint and not effective_checkpoint:
                return 0, False
            if not recorded_checkpoint and effective_checkpoint and can_reset:
                return 0, False
            # Phase one replays the stored count, so a boundary cut under a different ratio must recompute.
            if not recorded_checkpoint:
                recorded_ratio = truncation.get("boundary_headroom_ratio")
                try:
                    if (
                        recorded_ratio is not None
                        and abs(float(recorded_ratio) - requested_ratio) > 1e-9
                    ):
                        return 0, False
                except (TypeError, ValueError):
                    return 0, False
            # Re-derive the count from the anchor on this branch; only ever downward.
            anchor = truncation.get("boundary_anchor")
            if isinstance(anchor, str) and anchor:
                for index, branch_message in enumerate(_branch_non_system(branch_wire)):
                    if _anchor_text(branch_message) == anchor[:_ANCHOR_TEXT_CHARS]:
                        recorded = min(recorded, index)
                        break
            boundaries.append(recorded)
            origins.append(recorded_checkpoint)
        if not boundaries:
            return 0, False
        return min(boundaries), all(origins)
    except Exception:
        return 0, False


def _sticky_compaction_boundary(
    thread_id: Optional[str],
    branch_messages: Optional[list[dict]] = None,
    context_policy: Optional[str] = None,
    can_reset: bool = True,
    compaction_headroom_ratio: Optional[float] = None,
) -> int:
    """`_sticky_compaction_state` without the provenance, for callers that only fit."""
    return _sticky_compaction_state(
        thread_id,
        branch_messages,
        context_policy = context_policy,
        can_reset = can_reset,
        compaction_headroom_ratio = compaction_headroom_ratio,
    )[0]


def _prefix_user_text(message: dict, prefix: str) -> dict:
    """Copy of ``message`` with ``prefix`` in front of its text. Never mutates."""
    content = message.get("content")
    if isinstance(content, str) or content is None:
        return {**message, "content": prefix + (content or "")}
    if isinstance(content, list):
        parts = list(content)
        for index, part in enumerate(parts):
            if isinstance(part, dict) and part.get("type") in ("text", "input_text"):
                parts[index] = {**part, "text": prefix + str(part.get("text") or "")}
                return {**message, "content": parts}
        return {**message, "content": [{"type": "text", "text": prefix}] + parts}
    return message


_retrieval_budget = retrieval_budget


def _recall_top_k(budget_tokens: int) -> int:
    """How many archived chunks actually fit in the room a fit obtained.

    The reserve is what the fit AIMS to hold back, not what it gets: protected messages
    (system, latest turn, anchored recalls) can stop the trim reaching its target while
    still passing the prompt budget. Injecting a full reserve on top then overflows the
    window -- reproduced at ctx 8000: fit accepted at 6900, recall took it to 8948. So
    size the recall from the room actually left.
    """
    try:
        from core.rag import config as rag_config
        chunk = max(1, int(rag_config.CHUNK_TOKENS))
        cap = max(0, int(rag_config.CONVERSATION_ARCHIVE_TOP_K))
    except Exception:
        return 0
    fits = int(budget_tokens) // chunk
    if fits <= 0 and int(budget_tokens) > 0:
        # CHUNK_TOKENS is a ceiling; the exact recount below decides.
        fits = 1
    return max(0, min(cap, fits))


def _archive_and_recall(
    conversation: list[dict],
    before: list[dict],
    *,
    thread_id: Optional[str],
    style: str,
    recall_done: bool,
    force_recall: bool = True,
    recall_budget_tokens: int = 0,
    count_tokens: Optional[Callable[[list[dict]], int]] = None,
    branch_messages: Optional[list[dict]] = None,
) -> dict:
    """Keep the turns this fit evicted, then pull the relevant ones back.

    Returns ``{"conversation", "events", "counts", "recalled"}``. Never raises: every
    failure degrades to the plain fitted messages. Recall fires at most once per request,
    or the tool loop's per-iteration refit would stack a recall block onto each pass.
    """
    result = {
        "conversation": conversation,
        "events": [],
        "counts": {},
        "recalled": False,
        "anchored": [],
    }
    if not thread_id:
        return result
    try:
        from core.inference.tools import build_conversation_recall
        from core.rag import conversation_archive

        if not conversation_archive.enabled():
            return result

        gone = evicted_messages(before, conversation)
        # Pass the fitted prompt so turns still visible are not archived twice.
        archived = (
            conversation_archive.archive_turns(
                thread_id, gone, live = conversation, branch = branch_messages or conversation
            )
            if gone
            else 0
        )
        counts = {"archived_messages": archived}

        if recall_done:
            result["counts"] = counts
            return result
        if not force_recall:
            # Checkpoint mode past the first turn: auto lookup only on the reset turn.
            result["counts"] = counts
            return result

        top_k = _recall_top_k(recall_budget_tokens)
        if top_k <= 0:
            result["counts"] = counts
            return result

        # Exact recount decides; on overflow halve the turn count (4 -> 2 -> 1) instead of giving up.
        attempts = []
        attempt_k = top_k
        while True:
            attempts.append(attempt_k)
            if attempt_k <= 1:
                break
            attempt_k = max(1, attempt_k // 2)

        for index, k in enumerate(attempts):
            recall = build_conversation_recall(
                conversation,
                thread_id,
                style = style,
                top_k = k,
                branch_messages = branch_messages,
            )
            if not recall:
                result["counts"] = counts
                return result

            candidate = _inject_recall(conversation, recall, style)
            if candidate is None:
                result["counts"] = counts
                return result

            grew = None
            if count_tokens is not None and recall_budget_tokens > 0:
                try:
                    grew = count_tokens(candidate["conversation"]) - count_tokens(conversation)
                except Exception:
                    grew = None
            if grew is not None and grew > recall_budget_tokens:
                logger.info(
                    "conversation_recall.over_budget grew=%s budget=%s top_k=%s",
                    grew,
                    recall_budget_tokens,
                    k,
                )
                if index + 1 < len(attempts):
                    continue
                logger.info(
                    "conversation_recall.dropped_over_budget budget=%s", recall_budget_tokens
                )
                result["counts"] = counts
                return result

            result["conversation"] = candidate["conversation"]
            result["events"] = candidate["events"]
            result["anchored"] = candidate["anchored"]
            break

        counts["recalled_chunks"] = int(recall.get("sources") or 0)
        result["counts"] = counts
        result["recalled"] = True
    except Exception as exc:
        logger.warning("Could not archive or recall compacted turns: %s", exc)
    return result


def _inject_recall(conversation: list[dict], recall: dict, style: str) -> Optional[dict]:
    """The conversation with ``recall`` added, or None if there was nowhere to put it.

    ``anchored`` is only what this injection added: the two synthetic tool messages, or
    the rewritten user message inline. The caller protects those from a later refit, and
    anything else would pin a real turn the fit is entitled to evict.
    """
    if style == "inline":
        prefix = recall.get("prefix") or ""
        updated = list(conversation)
        for index in range(len(updated) - 1, -1, -1):
            if updated[index].get("role") == "user":
                updated[index] = _prefix_user_text(updated[index], prefix)
                break
        else:
            return None
        return {"conversation": updated, "events": [], "anchored": [updated[index]]}
    added = list(recall["messages"])
    return {
        "conversation": list(conversation) + added,
        "events": list(recall["events"]),
        "anchored": added,
    }


_RESPAWN_REAP_GRACE_S = 1.0


def _finalize_reasoning_only_cumulative(
    cumulative: str,
    reasoning_text: str,
    finish_reason: Optional[str],
    promote_reasoning_only: bool,
    resumed_reasoning: str = "",
) -> str:
    """Close a live thinking block and promote it only after a clean stop.

    Local inference streams cumulative snapshots. Replacing ``<think>...`` with
    bare reasoning at EOF makes the final snapshot shorter, so suffix-based
    route consumers drop the intended fallback. Keep the snapshot append-only.
    A length-truncated thought is not a final answer, so close it without
    promotion and let the client surface the ``length`` terminal state. Raw
    consumers that do not split reasoning from visible content can disable the
    fallback to avoid returning the same reasoning twice.

    Include ``resumed_reasoning`` in the promoted reply; the stream contains only the new tail.
    """
    visible_fallback = (
        resumed_reasoning + reasoning_text
        if promote_reasoning_only and finish_reason != "length"
        else ""
    )
    return cumulative + "</think>" + visible_fallback


def _ends_inside_quote(text: str) -> bool:
    """Heuristic: text ends on a quote opener left unmatched on its line, or a lone quote."""
    stripped = (text or "").rstrip()
    if not stripped or stripped[-1] not in "`\"'":
        return False
    if len(stripped) > 1 and not (stripped[-2].isspace() or stripped[-2] in "*_([{"):
        return False
    last = stripped[-1]
    line = stripped.rsplit("\n", 1)[-1]
    marks = sum(
        1
        for i, ch in enumerate(line)
        if ch == last
        and not (
            ch == "'" and 0 < i < len(line) - 1 and line[i - 1].isalnum() and line[i + 1].isalnum()
        )
    )
    return marks % 2 == 1


def _quote_cut_event(
    reasoning_text: str,
    answer_text: str,
    finish_reason: Optional[str],
    promote_reasoning_only: bool,
) -> Optional[dict]:
    """Flag a mid-quote `stop` in the shown answer; off for Anthropic, which cannot relay it."""
    if not promote_reasoning_only or finish_reason != "stop":
        return None
    shown = answer_text if answer_text.strip() else reasoning_text
    return {"type": "quote_cut"} if _ends_inside_quote(shown) else None


# Only large streamed tool args get an early provisional card; render_html is exempt.
_PROVISIONAL_ARGS_MIN_CHARS = 256
_DEFAULT_STREAM_STALL_TIMEOUT_S = 120.0
# Textual-fallback tool calls are not grammar-bounded, so cap them per turn.
_MAX_TOOL_CALLS_PER_TURN = 8
# The first retry already runs with thinking off; more attempts rarely help.
_MAX_LENGTH_CONTINUATIONS = 2
_CONTINUE_AFTER_LENGTH_STATUS = "Continuing after a long thought..."
_CONTINUE_TRUNCATED_ANSWER_STATUS = "Continuing the answer..."
_MIN_USEFUL_RESULT_TOKENS = 64
# Keyed on identical RESULTS, not arguments (as OpenClaw's loop detection).
_MAX_IDENTICAL_TOOL_RESULTS = 3

_UNSET = object()


# A result with this tail is the window's answer, not the tool's.
_WINDOW_NOTICE_MARKER = "chars for the model;"
# Zero-budget results get _zero_room_stub, which lacks the marker above; catch it too.
_ZERO_ROOM_MARKER = "no context room left"


def _is_window_notice(result: str) -> bool:
    return _WINDOW_NOTICE_MARKER in result or _ZERO_ROOM_MARKER in result


# llama.cpp prints its arg error last; bounded so a huge unterminated line stays cheap.
_FAILURE_SCAN_TAIL_CHARS = 64 * 1024
_FAILURE_QUOTE_CHARS = 200
# Sentence-anchored: mid-sentence the same words are prose naming a tool.
_FORCED_PLAN_INTENT = re.compile(
    r"(?:^|[.!?]\s+)\s*"
    r"(?:i\s+(?:(?:need|have|ought)\s+to|should|must)|need\s+to|going\s+to|must|should)"
    r"\s+(?:\w+\s+){0,2}?(?:call|use|run|search|fetch|render)\b",
    re.I | re.M,
)
# Negated forms announce a missing answer, so they are excluded.
_FINAL_ANSWER_SIGNAL = re.compile(
    r"\b(?:final\s+answer|answer\s*:|here\s+is|here's|in\s+summary|result\s*:"
    r"|(?:the\s+)?answer\s+is(?!\s+(?:not|unavailable|unknown|unclear|missing)\b))\b",
    re.I,
)
# A plan that pivots to an answer must survive; the pivot needs text of its own.
_ANSWER_PIVOT = re.compile(
    r"\b(?:but|however|although|though|that\s+said|in\s+the\s+meantime|meanwhile)\b"
    r"[\W_]*(?:\w+[\W_]+){1,}\w",
    re.I,
)


def _gguf_active_tool_names(active_tools: list[dict]) -> list[str]:
    names = [
        (tool.get("function") or {}).get("name")
        for tool in (active_tools or [])
        if isinstance(tool, dict) and isinstance(tool.get("function"), dict)
    ]
    return [name for name in names if name]


# Lookbehind excludes the Mistral [CALL_ID]...[ARGS] shape.
_GGUF_REHEARSAL_ARGS_RE = re.compile(r"(?<!\[CALL_ID\])\b([\w-]+)\[ARGS\]")


def _gguf_rehearsal_signal_pos(text: str, active_tools: list[dict]) -> int:
    """Index of the first ``NAME[ARGS]`` whose NAME is markerless-promotable, else -1. An
    inactive-name ``foo[ARGS]`` in prose is not a call, nor is a bare execution-class
    ``terminal[ARGS]``; mirrors the safetensors ``_earliest_tool_signal`` gating."""
    active = set(_gguf_active_tool_names(active_tools))
    if not active:
        return -1
    for m in _GGUF_REHEARSAL_ARGS_RE.finditer(text):
        if _markerless_promotable(m.group(1), active):
            return m.start()
    return -1


def _gguf_has_genuine_tool_signal(text: str, signals, active_tools: list[dict]) -> bool:
    """True when ``text`` holds a genuine tool-call boundary for one of ``signals``.

    Unambiguous markers (``<tool_call>``, ``[TOOL_CALLS]``, ``<function=``) count on a
    plain substring hit; an ``[ARGS]`` hit is genuine only when an active tool name
    precedes it, so inactive-name prose is neither drained nor parsed."""
    for sig in signals:
        if sig == "[ARGS]":
            if _gguf_rehearsal_signal_pos(text, active_tools) >= 0:
                return True
            continue
        if sig in text:
            return True
    # The parser promotes bare Gemma anywhere, so a mid-prose one is a boundary too.
    return promotable_gemma_call_pos(text, lambda: set(_gguf_active_tool_names(active_tools))) >= 0


_TEXT_TOOL_NAME_RE = re.compile(r'"name"\s*:\s*"([\w.\-]+)"')
_TEXT_TOOL_GEMMA_RE = re.compile(r"\s*call:([\w.\-]+)")
_TEXT_TOOL_REHEARSAL_RE = re.compile(r"\s*([\w.\-]+)\s*\[ARGS\]")


def _sniff_text_tool_name(text: str, enabled_names: set) -> str:
    """Best-effort tool name from a partially drained TEXT tool call, gated on
    enabled names so prose can never spawn a card. Used only to open the live
    argument pane early; the authoritative parse still happens at stream end.

    The two anchored arms only match a MARKERLESS leading call (a wrapper pushes the shape
    off position 0), so they take the parser's gate: a card for a bare ``call:terminal{``
    would show a call that never runs. The ``"name":`` arm searches the whole prefix and so
    also sees a trusted ``[TOOL_CALLS][{"name":"terminal",..}]``; the markerless bare-JSON
    form cannot reach it, since ``strip_leading_bare_json_call`` refuses to drain it."""
    # A blocked leading call will not run, so skip every markerless format before naming.
    text = text[blocked_markerless_prefix_end(text, 0, enabled_names) :]
    m = _TEXT_TOOL_NAME_RE.search(text[:4096])
    if m and m.group(1) in enabled_names:
        return m.group(1)
    m = _TEXT_TOOL_GEMMA_RE.match(text[:256])
    if m and _markerless_promotable(m.group(1), enabled_names):
        return m.group(1)
    m = _TEXT_TOOL_REHEARSAL_RE.match(text[:256])
    if m and _markerless_promotable(m.group(1), enabled_names):
        return m.group(1)
    return ""


def _is_rehearsal_prefix(stripped: str, active_tools: list[dict]) -> bool:
    """True if ``stripped`` is a (possibly partial) prefix of ``NAME[ARGS]`` for a
    markerless-promotable tool: the bare name arriving in its own chunk before
    ``[ARGS]{...}``. An execution-class name is prose here, so it streams rather than being
    held. Mirrors the safetensors loop so the split rehearsal is not leaked."""
    if not stripped or any(ch.isspace() for ch in stripped):
        return False
    for name in _gguf_active_tool_names(active_tools):
        # Use the shared gate, which also refuses mcp__* names.
        if not _markerless_promotable(name, None):
            continue
        if stripped == name or f"{name}[ARGS]".startswith(stripped):
            return True
    return False


def _held_rehearsal_tail_len(text: str, active_tools: list[dict]) -> int:
    """Length of a trailing bare tool-name token that may be a split rehearsal call
    (``...web_search`` with ``[ARGS]{...}`` still to arrive), so STREAMING can hold it
    instead of leaking the name. Returns 0 for ordinary prose. Mirrors safetensors, including
    the trailing bare-Gemma ``call:NAME{..`` the signal scan misses until its ``{``."""
    i = len(text)
    while i > 0 and not text[i - 1].isspace():
        i -= 1
    tail = text[i:]
    held = len(tail) if tail and _is_rehearsal_prefix(tail, active_tools) else 0
    return max(
        held, held_bare_gemma_tail_len(text, lambda: set(_gguf_active_tool_names(active_tools)))
    )


def _should_suppress_forced_no_tool_output(text: str, previous: str = "") -> bool:
    """Suppress only repeated forced-turn planning text, not final answers.

    ``previous`` is the stall text that triggered the nudge, so a retry that
    moved on can be told from one that just said the same thing again.
    """
    stripped = text.strip()
    if not stripped or len(stripped) >= _REPROMPT_MAX_CHARS:
        return False
    if _FINAL_ANSWER_SIGNAL.search(stripped):
        return False
    plan = _FORCED_PLAN_INTENT.search(stripped)
    if plan is not None:
        return _ANSWER_PIVOT.search(stripped[plan.end() :]) is None
    if not _is_short_intent_without_action(stripped):
        return False
    # INTENT_SIGNAL also fires on answer lead-ins; a stall only if the retry adds nothing.
    return not previous or _is_reprompt_restatement(stripped, previous)


_SHARD_FULL_RE = re.compile(r"^(.*)-(\d{5})-of-(\d{5})\.gguf$", re.IGNORECASE)
_SHARD_RE = re.compile(r"^(.*)-\d{5}-of-\d{5}\.gguf$", re.IGNORECASE)


# Per-layer SWA mask when GGUF lacks sliding_window_pattern; see _resolve_swa_pattern tiers.
# Period N: layer i is SWA iff (i + 1) % N != 0, matching transformers.
# Deliberately absent: phi3, the qwen2 family, mistral v0.1/v0.2 (all-SWA is not a period).
_BOOTSTRAP_SWA_DEFAULTS: dict[str, int] = {
    "gemma2": 2,  # Gemma2Config.sliding_window_pattern
    "gemma3": 6,  # Gemma3TextConfig.sliding_window_pattern
    "gemma3n": 5,  # text_config.layer_types: SWA*4 + FULL
    "gpt_oss": 2,  # text_config.layer_types: alternating
    "cohere2": 4,  # Cohere2Config.sliding_window_pattern
}

# Values are int period or list[bool] mask; __missed_repos__ lists repos with no SWA field.
_SWA_CACHE: Optional[dict] = None
_SWA_CACHE_LOCK = threading.Lock()


def _hf_endpoint_host() -> str:
    """Host of the configured hub endpoint (HF_ENDPOINT aware)."""
    from utils.utils import hf_endpoint_host
    return hf_endpoint_host()


def _probe_dns_dead(host: Optional[str] = None, timeout: float = 2.0) -> bool:
    """Quick DNS check on a daemon thread, so concurrent sockets aren't
    affected by socket.setdefaulttimeout. Defaults to the configured endpoint's host."""
    from utils.utils import dns_host_dead, hf_endpoint_host
    return dns_host_dead(host or hf_endpoint_host(), timeout)


def _hf_env_offline() -> bool:
    """True when an HF offline env var is set to any truthy value (1/true/yes/on).

    Mirrors utils.models.model_config._env_offline so a user-set HF_HUB_OFFLINE=true
    (not just "1") still routes through the local-cache reuse path below.
    """
    try:
        from utils.models.model_config import _env_offline
        return _env_offline()
    except Exception:
        return os.environ.get("HF_HUB_OFFLINE", "").strip().lower() in {"1", "true", "yes", "on"}


def _hf_unreachable() -> bool:
    """True when the Hub can't be reached: dead DNS, or DNS that resolves with no egress.

    DNS alone misses the common shapes (WAN down behind a live router, captive portal,
    stale cache), leaving every hub call to burn its retry backoff. The DNS shortcut stands
    down when a proxy is configured, since the proxy resolves the host.
    """
    try:
        from utils.utils import hf_dns_dead, hf_reachability_memo, hf_unreachable
    except Exception:
        return False
    # Reuse a fresh verdict (a slow resolver costs a timeout per guard); peek only, never record.
    memo = hf_reachability_memo()
    if memo is not None:
        return memo
    if hf_dns_dead():
        return True
    return hf_unreachable()


_MISS = object()


# GGUF unsigned value-type id -> byte width (uint8, uint16, uint32, uint64).
_GGUF_UINT_WIDTHS = {0: 1, 2: 2, 4: 4, 10: 8}


@contextlib.contextmanager
def _hf_offline_if_unreachable():
    """Force HF offline for this block only when the Hub is unreachable; restores on exit
    so a transient hiccup can't quarantine the process. No-op if the USER set the env var.

    Env vars alone are too late mid-process (the offline constants are read at import), so
    this holds a refcounted force_hf_offline window. Overlapping requests each take their
    own reference: no-opping would let another guard's exit restore the network
    mid-operation and drop this request back onto the retry path.
    """
    try:
        from utils.utils import force_hf_offline, force_hf_offline_state, hf_env_offline
    except Exception:
        yield False
        return

    ours, hf_hub_env_present = force_hf_offline_state()
    # Membership keeps HF_HUB_OFFLINE=0 as an explicit stay-online override.
    if hf_hub_env_present and not ours:
        yield False
        return
    # The hub ignores TRANSFORMERS_OFFLINE, so honour it here without probing.
    if not ours and hf_env_offline():
        with force_hf_offline():
            yield True
        return
    if not ours and not _hf_unreachable():
        yield False
        return

    if not ours:
        logger.warning("Hugging Face endpoint unreachable; using local HF cache for this load.")
    with force_hf_offline():
        yield True


def _hf_offline_if_unreachable_for(model_name):
    """Guard, but only for remote repo ids: a local path is served from disk and never
    reaches the hub, so probing would add seconds per request and prevent no retry."""
    try:
        from utils.paths import is_local_path
        if isinstance(model_name, str) and is_local_path(model_name):
            return contextlib.nullcontext()
    except Exception:
        pass
    return _hf_offline_if_unreachable()


