    @staticmethod
    def _leading_process_group(pid):
        """The pid's own process group, when it leads one. None otherwise.

        `not pid` rejects 0 and None but not 1, and `getpgid(1) == 1`, so init
        reads as a group leader here and the caller below would then broadcast
        SIGKILL to every process the user owns. The pid comes from a live Popen
        today so it cannot be 1, but the floor is a line and the consequence of
        losing that property later is not recoverable.
        """
        if not _is_signalable_pid(pid):
            return None
        if os.name != "posix" or not hasattr(os, "getpgid"):
            return None
        try:
            pgid = os.getpgid(pid)
        except OSError:
            return None
        return pgid if pgid == pid else None

    @staticmethod
    def _kill_process_group(pgid):
        """Take down what the leader left behind, if anything is still there."""
        if not _is_signalable_pid(pgid):
            return  # killpg(1) is kill(-1); killpg(0) is our own group
        if not hasattr(os, "killpg"):
            return
        try:
            os.killpg(pgid, signal.SIGKILL)
        except OSError:
            pass

    @staticmethod
    def _collect_descendants(pid):
        """`(children, known)` for the kill below.

        `known` is False when the walk could not be made at all: no Toolhelp snapshot, or
        a root whose own identity cannot be read. An empty list then means "not
        enumerable", not "none", and the difference decides whether this unload may drop
        the record and the pidfile. Treating it as "none" terminates the leader, finds no
        survivors and deletes the only handles on whatever the failed walk did not list.
        """
        try:
            from utils.process_lifetime import collect_descendants_known
            return collect_descendants_known(pid)
        except Exception:
            return [], False

    @staticmethod
    def _tree_kill_surviving_process(pid) -> bool:
        """Last resort for a server still alive after terminate. True when it is gone.

        ``owner_verified``: this is reached holding the Popen that spawned the pid, so
        ownership is not in question even when the start time behind the lifetime
        record can no longer be read.
        """
        if not _is_signalable_pid(pid):
            return False
        try:
            from utils.process_lifetime import confirm_pid_exited, terminate_pid
        except Exception:
            return False
        try:
            terminate_pid(pid, timeout = 5.0, owner_verified = True)
        except Exception as e:
            logger.warning(f"Could not terminate surviving llama-server {pid}: {e}")
        try:
            gone = confirm_pid_exited(pid)
        except Exception:
            return False
        if not gone:
            logger.warning(
                f"llama-server {pid} is still running after a tree kill; "
                "keeping its record so the next launch can reap it"
            )
        return gone

    @staticmethod
    def _confirm_group_kill_landed(pid) -> bool:
        """Did the killpg above actually take the leader with it. True when it is gone.

        The cheap half of `_tree_kill_surviving_process`, for the POSIX case where the
        expensive half is a second killpg over a group this teardown has already SIGKILLed.
        No signal is sent from here: the only open question is whether the one already sent
        has finished landing, and kills are asynchronous, so it is answered with a bounded
        poll rather than a single read taken microseconds after the signal.

        False keeps the lifetime record and the pidfile, exactly as a failed tree kill does,
        so a server the group kill could not reach is still reapable by the next launch.
        """
        if not _is_signalable_pid(pid):
            return False
        try:
            from utils.process_lifetime import confirm_pid_exited
        except Exception:
            return False
        try:
            gone = confirm_pid_exited(pid)
        except Exception:
            return False
        if not gone:
            logger.warning(
                f"llama-server {pid} is still running after its process group was killed; "
                "keeping its record so the next launch can reap it"
            )
        return gone

    @staticmethod
    def _terminate_descendants(collected):
        """The diffusion shim's visual server, and anything else it started.

        Returns the survivors as `(pid, identity)`: the ones still running when the sweep
        gave up, each with the creation-time identity the sweep verified. A forced kill can
        simply fail (access denied, a protected process, an uninterruptible driver ioctl),
        and reading the attempt as the outcome is what lets the caller delete the record
        and the pidfile out from under a worker that is still holding the GPU.
        Each survivor is adopted WITH that identity, so it gets a lifetime record of its
        own rather than depending on the leader's: the leader is usually gone by now, and
        on Windows there is no process group standing in for it. The identity travels
        because a survivor can exit between the sweep's last liveness check and the adopt,
        and adopting the bare number would then record a stranger and, where a job object
        is active, put it in a job that kills its members when the app closes.
        """
        if not collected:
            return []
        try:
            from utils.process_lifetime import adopt_pid, terminate_descendants
            survivors = terminate_descendants(collected, timeout = 5.0)
        except Exception as e:
            logger.debug(f"Could not terminate server descendants: {e}")
            return list(collected)
        for pid, identity in survivors:
            try:
                adopt_pid(pid, identity, from_snapshot = True)
            except Exception:
                pass
        if survivors:
            logger.warning(
                f"llama-server descendants still running after the sweep: "
                f"{[pid for pid, _ in survivors]}; "
                "recorded so the next launch can reap them"
            )
        return survivors

    def _publish_healthy(self) -> bool:
        """Commit _healthy under the spawn lock, or refuse if this load is stale.

        Under the lock the teardown mark is set with, so only two orders exist:
        publish then teardown (which clears _healthy), or teardown then a refused
        publish.
        """
        with self._spawn_lock:
            if self._spawn_is_stale():
                logger.info("load no longer belongs to this lifecycle; not publishing it healthy")
                return False
            self._healthy = True
            self._planned_vram_mib = dict(getattr(self, "_pending_plan_mib", {}))
            return True

    def _close_attempt_log(
        self,
        *,
        reason: str = "closed",
        exit_code: "Optional[int]" = None,
    ) -> None:
        """Close the per-attempt tee log opened just before a spawn.

        A refusal publishes no process and _kill_process returns early when there is
        none, so nothing else closes it: the next attempt leaks the descriptor and,
        on Windows, holds the file lock an update needs.
        """
        self._llama_log_tee_failed = False
        fh = getattr(self, "_llama_log_fh", None)
        if fh is None:
            return
        if exit_code is None:
            try:
                exit_code = self._process.poll()
            except Exception:
                pass
        try:
            fh.write(f"[studio] attempt end reason={reason} exit_code={exit_code}\n")
        except Exception:
            pass
        try:
            fh.close()
        except Exception:
            pass
        self._llama_log_fh = None
        try:
            logger.info(
                f"attempt log closed reason={reason} exit_code={exit_code} "
                f"path={getattr(self, '_llama_log_path', None)}"
            )
        except Exception:
            pass

    def _begin_server_lifecycle(self) -> None:
        """Clear shutdown state so a restarted server can launch again.

        The backend is a module singleton and an embedded host may call
        run_server() more than once in one process, so "shutting down" is scoped
        to a lifecycle rather than to the interpreter. Called from run_server
        before anything can spawn.

        """
        # _teardown_lock first, same order as _kill_process.
        with self._teardown_lock:
            with self._spawn_lock:
                self._shutting_down = False
                self._torn_down_process = None

    def _spawn_is_stale(self) -> bool:
        """Whether this load may no longer spawn. Caller holds _spawn_lock."""
        if getattr(self, "_shutting_down", False):
            return True
        # Helper backends are not marked per-instance, so also check the process-wide latch.
        from utils.process_lifetime import is_process_shutting_down

        return is_process_shutting_down()

    @_invalidates_gpu_memory("llama.cpp stop")
    def _kill_process(self, *, teardown: bool = False):
        """Terminate the subprocess if running.

        ``teardown`` marks an app-level stop (shutdown, atexit) rather than the
        retry ladder reaping a child it is about to replace: only the former may
        end an in-flight health wait.

        A teardown holds _teardown_lock for the WHOLE kill, because the terminate and
        wait below keep reading self._process and finally clear it: a lifecycle
        reopened mid-kill would have its new child dropped or terminated here, so
        _begin_server_lifecycle takes the same lock and waits.

        _spawn_lock is taken only long enough to set the flag, NOT across the kill.
        A spawn arriving mid-teardown then reads the flag and refuses in microseconds
        instead of queuing behind a SIGTERM/SIGKILL escalation that can run for
        seconds; the load thread it belongs to is one shutdown is already waiting on.
        Marked above the early return, since a quit during a download still has to be
        recorded.
        """
        if teardown:
            from utils.process_lifetime import mark_process_shutting_down

            mark_process_shutting_down()
            with self._teardown_lock:
                with self._spawn_lock:
                    self._shutting_down = True
                self._kill_process_body(teardown = True)
            return
        self._kill_process_body(teardown = False)

    def _kill_process_body(self, *, teardown: bool):
        """The kill itself. Caller holds _teardown_lock when ``teardown``."""
        # Stop the watchdog first so a planned reload is not seen as a crash.
        self._stop_mtp_crash_watchdog()
        self._reset_effective_parallel_slots()
        self._diffusion_requested_ngl = None
        self._child_gpu_physical_ids = None
        if self._process is None:
            self._planned_vram_mib = {}
            return
        terminable = hasattr(self._process, "terminate")
        if not terminable:
            logger.debug("no terminable llama-server process to kill; clearing state")
        # Read both before terminate: getpgid fails once the leader is reaped.
        _pid = getattr(self._process, "pid", None)
        _pgid = self._leading_process_group(_pid)
        _descendants, _descendants_known = self._collect_descendants(_pid)
        _exited_first = getattr(self._process, "poll", lambda: None)() is not None
        if teardown:
            self._torn_down_process = self._process
        try:
            if terminable:
                self._process.terminate()
                self._process.wait(timeout = 5)
        except subprocess.TimeoutExpired:
            # Signal before logging: a closed stdout makes the logger raise and skip SIGKILL.
            self._process.kill()
            logger.warning("llama-server did not exit on SIGTERM, sent SIGKILL")
            self._process.wait(timeout = 5)
        except Exception as e:
            logger.warning(f"Error killing llama-server process: {e}")
        finally:
            self._kill_process_group(_pgid)
            _surviving_descendants = self._terminate_descendants(_descendants)
            # Teardown must tolerate a partially built backend.
            if getattr(self, "_stats_logger", None) is not None:
                self._stats_logger.stop()
                self._stats_logger = None
            # Forget the pid only once confirmed gone, so a startup sweep can still reap survivors.
            _killed_pid = getattr(self._process, "pid", None)
            _exit_code = getattr(self._process, "poll", lambda: None)()
            _exited = _exit_code is not None
            _owns_child = terminable and callable(getattr(self._process, "poll", None))
            if _owns_child and _killed_pid is not None and not _exited:
                if _pgid is not None and hasattr(os, "killpg"):
                    _exited = self._confirm_group_kill_landed(_killed_pid)
                else:
                    # On Windows terminate only hits the leader; taskkill /T /F is the last handle.
                    _exited = self._tree_kill_surviving_process(_killed_pid)
            # Keep the record while any descendant survives: pidfile and next reap key on it.
            if _surviving_descendants:
                _exited = False
            # Failed enumeration is not an empty tree: keep the record so the next launch can reap.
            if not _descendants_known and _pid is not None:
                logger.warning(
                    "llama-server descendants could not be enumerated before the kill; "
                    "keeping its record so the next launch can reap anything left"
                )
                _exited = False
            if _killed_pid is not None and _exited:
                try:
                    from utils.process_lifetime import forget_pid
                    forget_pid(_killed_pid)
                except Exception:
                    pass
            self._process = None
            self._planned_vram_mib = {}
            # Remove the pidfile only once exit is confirmed; with no child handle drop it as before.
            if getattr(self, "_owns_pidfile", True) and (
                _killed_pid is None or _exited or not _owns_child
            ):
                self._clear_server_pid()
            # Clear healthy so a /load during warm-up can't use the old server's health.
            self._healthy = False
            # Unknown, so the training guard treats the loading server as VRAM-resident.
            self._gpu_offload_active = None
            self._gpu_offload_layers = None
            self._offload_overridden = False
            self._gpu_backend_unavailable = False
            self._last_kill_monotonic = time.monotonic()
            stdout_thread = getattr(self, "_stdout_thread", None)
            if stdout_thread is not None:
                stdout_thread.join(timeout = 2)
                self._stdout_thread = None
            self._close_attempt_log(
                reason = "exited" if _exited_first else "killed", exit_code = _exit_code
            )

    def _other_planned_vram_mib(self) -> dict[int, int]:
        """MiB per GPU the other serving backends' running servers hold."""
        held: dict[int, int] = {}
        serving = _serving_backends_snapshot()
        if self not in serving:
            return held
        for backend in serving:
            if backend is self or not getattr(backend, "is_active", False):
                continue
            for idx, mib in getattr(backend, "_planned_vram_mib", {}).items():
                held[idx] = held.get(idx, 0) + mib
        return held

    def _note_server_pid(self, pid: int) -> None:
        if getattr(self, "_owns_pidfile", True):
            self._record_server_pid(pid)
            return
        try:
            from utils.process_lifetime import adopt_pid
            adopt_pid(pid)
        except Exception as e:
            logger.debug(f"Could not track llama-server for lifetime sweep: {e}")

    @staticmethod
    def _server_pidfile_path() -> Optional[Path]:
        """Pidfile recording the live llama-server PID, under the active studio root
        (per-root, so concurrent Unsloth instances with distinct UNSLOTH_STUDIO_HOME stay
        isolated, mirroring the reaper's custom-root isolation)."""
        try:
            from utils.paths.storage_roots import studio_root  # noqa: WPS433
            return studio_root() / "llama-server.pid"
        except Exception:
            return None

    @classmethod
    def _record_server_pid(cls, pid: int) -> None:
        """Best-effort record of the spawned llama-server PID for orphan reaping.

        Stores ``pid:starttime`` so a later startup can reject a PID that has
        since been recycled to a different process (see ``_pid_start_identity``).
        A bare ``pid`` (no identity) is still accepted on read for compatibility.
        """
        # The lifetime record covers every child; the startup sweep reads it on macOS.
        try:
            from utils.process_lifetime import adopt_pid
            adopt_pid(pid)
        except Exception as e:
            logger.debug(f"Could not track llama-server for lifetime sweep: {e}")
        path = cls._server_pidfile_path()
        if path is None:
            return
        try:
            path.parent.mkdir(parents = True, exist_ok = True)
            path.write_text(f"{pid}:{cls._pid_start_identity(pid)}", encoding = "utf-8")
        except Exception as e:
            logger.debug(f"Could not write llama-server pidfile: {e}")

    @classmethod
    def _clear_server_pid(cls) -> None:
        """Best-effort removal of the llama-server pidfile."""
        path = cls._server_pidfile_path()
        if path is None:
            return
        try:
            path.unlink(missing_ok = True)
        except Exception as e:
            logger.debug(f"Could not remove llama-server pidfile: {e}")

    @staticmethod
    def _pid_is_llama_server(pid: int) -> bool:
        """True only if pid is a live process whose binary is a llama-server. Guards
        against PID reuse before killing a recorded orphan; returns False on any
        uncertainty so an unrelated process is never killed."""
        try:
            import psutil
            try:
                proc = psutil.Process(pid)
                if (proc.name() or "").lower().startswith("llama-server"):
                    return True
                return Path(proc.exe() or "").name.lower().startswith("llama-server")
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                return False
        except ImportError:
            pass
        if sys.platform != "linux":
            return False
        try:
            if Path(os.readlink(f"/proc/{pid}/exe")).name.lower().startswith("llama-server"):
                return True
        except OSError:
            pass
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as fh:
                tokens = fh.read().split(b"\x00")
            first = tokens[0].decode("utf-8", "replace") if tokens else ""
            return Path(first).name.lower().startswith("llama-server")
        except OSError:
            return False

    @staticmethod
    def _pid_start_identity(pid: int) -> str:
        """Stable per-PID identity (process start time) guarding against PID reuse.

        Returns a token string, or "" when it cannot be determined (the caller
        then falls back to the llama-server name check only)."""
        try:
            import psutil
            try:
                return str(psutil.Process(pid).create_time())
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                return ""
        except ImportError:
            pass
        if sys.platform == "linux":
            try:
                with open(f"/proc/{pid}/stat", "rb") as fh:
                    data = fh.read()
                # field 22 (starttime), counted from after the ")" that closes comm.
                return data[data.rfind(b")") + 2 :].split()[19].decode()
            except (OSError, IndexError):
                return ""
        return ""

    @staticmethod
    def _pid_parent_is_alive(pid: int) -> bool:
        """True if the recorded server's parent is still running, i.e. the server is
        NOT orphaned. Lets the cross-session reap kill only a true orphan (parent
        gone) and never a live server owned by a running Unsloth, regardless of which
        process performs the sweep. Biased toward "alive" on uncertainty so a live
        server is never mistakenly reaped."""
        try:
            import psutil

            try:
                ppid = psutil.Process(pid).ppid()
            except psutil.NoSuchProcess:
                return False
            except psutil.Error:
                return True  # never risk killing a live server
            if ppid <= 1:
                return False  # reparented to init -> orphan
            return psutil.pid_exists(ppid)
        except ImportError:
            pass
        if sys.platform == "linux":
            try:
                with open(f"/proc/{pid}/stat", "rb") as fh:
                    data = fh.read()
                ppid = int(data[data.rfind(b")") + 2 :].split()[1])
            except (OSError, IndexError, ValueError):
                return False
            if ppid <= 1:
                return False
            return Path(f"/proc/{ppid}").exists()
        return False

    @staticmethod
    def _unlink_pidfile(path: Path) -> None:
        """Best-effort removal of a resolved pidfile path."""
        try:
            path.unlink(missing_ok = True)
        except Exception:
            pass

    @classmethod
    def _reap_recorded_pid(cls) -> int:
        """Kill the exact llama-server PID recorded at spawn, but only when it is a
        genuine orphan -- its parent (the Unsloth that spawned it) is gone. This is
        the cross-session backstop the parent-death reaper (Job Object /
        PR_SET_PDEATHSIG) cannot cover: an orphan left by an already-dead Unsloth
        (macOS, a best-effort failure, or a pre-existing orphan). Path-independent,
        so it also catches an orphan the install-root match would miss.

        A live server whose parent is still running is never reaped, so constructing
        a second backend in-process (the helper / advisor paths each build a
        LlamaCppBackend) cannot kill the active chat server. A recorded PID that has
        been recycled to a different process is rejected by the start-time identity
        and the llama-server name check, so unrelated user processes are never
        touched. SIGKILL falls back to SIGTERM on Windows, where os.kill maps it to
        TerminateProcess and SIGKILL is undefined."""
        path = cls._server_pidfile_path()
        if path is None or not path.exists():
            return 0

        pid = -1
        identity = ""
        try:
            pid_str, _, identity = path.read_text(encoding = "utf-8").strip().partition(":")
            pid = int(pid_str)
        except Exception:
            pid = -1

        # Bound check before the cmdline check so pid 1 can never get through.
        if not _is_signalable_pid(pid):
            cls._unlink_pidfile(path)
            return 0
        if pid == os.getpid():
            return 0

        if cls._pid_parent_is_alive(pid):
            # Live parent: keep the record so a later startup can reap it if the parent dies.
            return 0

        # Parent gone: reject a PID recycled to something else.
        if identity and cls._pid_start_identity(pid) != identity:
            cls._unlink_pidfile(path)
            return 0

        killed = 0
        if cls._pid_is_llama_server(pid):
            try:
                os.kill(pid, getattr(signal, "SIGKILL", signal.SIGTERM))
                killed = 1
                logger.info(f"Killed orphaned llama-server from pidfile (pid={pid})")
            except (ProcessLookupError, PermissionError):
                pass
            except Exception as e:
                logger.debug(f"Could not kill recorded llama-server pid {pid}: {e}")
        cls._unlink_pidfile(path)
        return killed

    @staticmethod
    def _kill_orphaned_servers() -> int:
        """Kill orphaned llama-server processes started by studio.

        Only kills processes whose resolved binary lives under a known
        Unsloth install dir (or matches an exact env-var override), to avoid
        terminating unrelated llama-server instances. Mirrors every location
        _find_llama_server_binary() can return, so orphans from any
        supported install path are cleaned up.

        Reads /proc directly on Linux and uses psutil elsewhere (macOS, Windows).
        The pgrep fallback the psutil-less path used to take is gone: /proc is
        what that fallback read anyway, and psutil is a hard dependency, so it
        was unreachable from both directions.

        Candidates are collected first and killed afterwards, so an enumeration
        that fails part way kills nothing rather than some. The parent check
        therefore runs after enumeration rather than during it; a parent that
        exits in between makes the process a genuine orphan, and the start-time
        check below still refuses to signal a PID that has been reused.

        Returns the count of processes killed; callers arm the VRAM-settle
        wait on a positive count.
        """
        # Reap the recorded PID only if a true orphan, so a helper backend never kills a live server.
        killed = LlamaCppBackend._reap_recorded_pid()
        try:
            # exact_binaries = env overrides; install_roots = Unsloth-owned trees.
            install_roots: list[Path] = []

            _resolved_sr, _is_legacy = LlamaCppBackend._resolved_studio_root_and_is_legacy()
            _is_custom_root = not _is_legacy
            if _is_custom_root:
                install_roots.append(_resolved_sr / "llama.cpp")

            # Env mode skips this so a custom-root Unsloth can't kill a default install's server.
            if not _is_custom_root:
                install_roots.append(Path.home() / ".unsloth" / "llama.cpp")

            project_root = Path(__file__).resolve().parents[4]
            install_roots.append(project_root / "llama.cpp")

            install_roots.append(project_root / "bin")

            custom_dir = os.environ.get("UNSLOTH_LLAMA_CPP_PATH")
            if custom_dir:
                # expanduser to match _find_llama_server_binary, or we cannot clean up our own server.
                install_roots.append(_expanded_user_path(custom_dir))

            exact_binaries: list[Path] = []
            env_binary = os.environ.get("LLAMA_SERVER_PATH")
            if env_binary:
                try:
                    exact_binaries.append(Path(env_binary).resolve())
                except OSError:
                    pass

            resolved_roots: list[Path] = []
            for root in install_roots:
                try:
                    # Local-link roots resolve into the user's checkout; skip so we never kill their server.
                    if _is_external_link(root):
                        continue
                    resolved_roots.append(root.resolve())
                except OSError:
                    pass

            my_pid = os.getpid()

            candidates = []

            def _looks_like_server(name):
                return bool(name) and name.lower().startswith("llama-server")

            def _stat_start_time(line):
                right = line.rfind(b")")
                fields = line[right + 2 :].split()
                return fields[19] if len(fields) > 19 else None

            def _proc_start_time(proc_dir):
                """Field 22 of /proc/<pid>/stat, in jiffies since boot."""
                try:
                    with open(f"{proc_dir}/stat", "rb") as fh:
                        line = fh.read()
                except OSError:
                    return None
                right = line.rfind(b")")
                if right < 0:
                    return None
                # Fields after comm start at field 3, so starttime is index 19.
                fields = line[right + 2 :].split()
                return fields[19] if len(fields) > 19 else None

            def _make_signal_killer(proc_dir, pid, start_time):
                def _kill():
                    # Re-check starttime: a reused PID gets a later one, so a mismatch is not our process.
                    if start_time is None or _proc_start_time(proc_dir) != start_time:
                        return False
                    try:
                        os.kill(pid, signal.SIGKILL)
                    except (ProcessLookupError, PermissionError):
                        return False
                    return True

                return _kill

            # /proc is Linux only; fall back to psutil. Tests repoint _PROC_ROOT.
            proc_root = _PROC_ROOT
            if sys.platform == "linux" and os.path.isdir(proc_root):
                # Faster than psutil.process_iter: read comm once, resolve exe only on a name match.
                def _proc_exe(proc_dir):
                    try:
                        target = os.readlink(f"{proc_dir}/exe")
                    except OSError:
                        return None
                    if not target:
                        return None
                    # Strip the kernel's ' (deleted)' suffix like psutil does, or upgrade orphans are missed.
                    if target.endswith(" (deleted)") and not os.path.exists(target):
                        target = target[: -len(" (deleted)")]
                    try:
                        return Path(target).resolve()
                    except OSError:
                        return None

                with os.scandir(proc_root) as entries:
                    for entry in entries:
                        if not entry.name.isdigit():
                            continue
                        try:
                            pid = int(entry.name)
                        except ValueError:
                            continue
                        if pid == my_pid:
                            continue
                        try:
                            with open(f"{entry.path}/stat", "rb") as fh:
                                stat_line = fh.read()
                        except OSError:
                            continue
                        left = stat_line.find(b"(")
                        right = stat_line.rfind(b")")
                        if left < 0 or right <= left:
                            continue
                        # comm is truncated to 15 bytes, which keeps the 'llama-server' prefix.
                        name = stat_line[left + 1 : right].decode("utf-8", "replace")
                        if not _looks_like_server(name):
                            continue
                        exe_path = _proc_exe(entry.path)
                        if exe_path is None:
                            continue
                        candidates.append(
                            (
                                pid,
                                exe_path,
                                _make_signal_killer(entry.path, pid, _stat_start_time(stat_line)),
                            )
                        )
            else:
                try:
                    import psutil
                except ImportError:
                    psutil = None

                if psutil is not None:

                    def _make_psutil_killer(psutil_mod, proc):
                        def _kill():
                            try:
                                proc.kill()
                            except (
                                psutil_mod.NoSuchProcess,
                                psutil_mod.AccessDenied,
                                psutil_mod.ZombieProcess,
                            ):
                                return False
                            return True

                        return _kill

                    for proc in psutil.process_iter(["pid", "name", "exe"]):
                        try:
                            pid = proc.info["pid"]
                            if pid == my_pid:
                                continue
                            if not _looks_like_server(proc.info.get("name") or ""):
                                continue
                            exe = proc.info.get("exe")
                            if not exe:
                                continue
                            candidates.append(
                                (pid, Path(exe).resolve(), _make_psutil_killer(psutil, proc))
                            )
                        except (
                            psutil.NoSuchProcess,
                            psutil.AccessDenied,
                            psutil.ZombieProcess,
                        ):
                            pass
                else:
                    return killed

            for pid, binary, kill in candidates:
                # Never touch pid 1: llama-server may be a container entrypoint.
                if not _is_signalable_pid(pid):
                    continue
                is_ours = binary in exact_binaries or any(
                    binary.is_relative_to(root) for root in resolved_roots
                )
                if not is_ours:
                    continue

                if LlamaCppBackend._pid_parent_is_alive(pid):
                    continue

                if kill():
                    killed += 1
                    logger.info(f"Killed orphaned llama-server process (pid={pid})")
        except Exception:
            logger.warning("Error during orphan server cleanup", exc_info = True)
        return killed

    def _cleanup(self):
        """atexit handler to ensure llama-server is terminated (a teardown).

        Nothing here may report a failure through the logging machinery. By the
        time atexit runs, the streams the handlers write to can already be closed,
        and a write then fails -- which is how this was found, as several unrelated
        tracebacks printed after the test summary.

        Two different mechanisms, because there are two kinds of logger in play.
        This module's own logger is a structlog PrintLogger writing straight to
        stdout (loggers/config.py), which has no error handling of its own and does
        not consult raiseExceptions at all, so only the except below covers it.
        raiseExceptions covers the stdlib loggers other libraries install, which
        report a broken handler by printing their own traceback instead of raising.
        Neither one alone is enough.
        """
        raise_exceptions = logging.raiseExceptions
        logging.raiseExceptions = False
        try:
            self._kill_process(teardown = True)
            # Windows locks the exe of a live server, so retry runtime cleanup post-kill.
            self._cleanup_cpu_fallback_runtime()
        except Exception:
            pass
        finally:
            logging.raiseExceptions = raise_exceptions

    def _planned_tensor_spill(
        self,
        inputs: Optional[dict],
        *,
        extra_args: Optional[Iterable[str]] = None,
        env: Optional[Mapping[str, str]] = None,
    ) -> "Optional[SpillPlan]":
        """A ``-ot`` spill plan for a load Unsloth could not fit, or None to abstain.

        Abstaining reproduces today's ``--fit on`` byte for byte, so every
        uncertain input abstains rather than guessing. That is the whole safety
        argument: the only behaviour that changes is the case where a plan was
        produced, and a plan is only produced when the numbers are known.

        The planner must NOT run when anything else owns placement. Pricing a
        placement the child will not actually get is the single bug class behind
        most of the review traffic on the load-mode work, and the cheap way to
        avoid it is to decline rather than to model the override.
        """
        from core.inference.offload_cost_model import HostProfile
        from core.inference.offload_planner import (
            PlanOptions,
            plan_placement,
            smart_offload_enabled,
        )

        source_env = os.environ if env is None else env
        if not smart_offload_enabled(source_env) or not inputs:
            return None

        # Unified memory: spilling moves bytes within one pool, so there is no trade.
        from utils.hardware import is_apple_silicon

        if is_apple_silicon():
            return None

        # Integrated CUDA SoCs (Jetson, DGX Spark) are unified memory too; a spill gains nothing.
        if self._integrated_cuda_unified_memory(inputs.get("gpu_indices")):
            logger.debug("Tensor spill: declined, an integrated CUDA device is unified memory")
            return None

        # Decline when user flags already control placement (-ot, --cpu-moe, -ngl, devices).
        if (
            _args_place_tensors_on_cpu(extra_args)
            or _env_places_tensors_on_cpu(source_env)
            or _extra_args_set_any_flag(extra_args, _GPU_LAYER_FLAGS)
            or str(source_env.get("LLAMA_ARG_N_GPU_LAYERS", "")).strip()
            or _extra_args_set_any_flag(extra_args, _DEVICE_FLAGS)
            or str(source_env.get("LLAMA_ARG_DEVICE", "")).strip()
            # A pinned draft device would be booked on device 0 by the planner; decline.
            or _extra_args_draft_device_pin(extra_args)
            # -sm row/tensor split within tensors, which the row model cannot describe.
            or (_extra_args_split_mode(extra_args, source_env) in ("row", "tensor"))
            # Inherited -sm env may be stripped by load_model later; only argv provably survives.
            or (
                _extra_args_split_mode(extra_args, source_env) == "none"
                and _extra_args_split_mode(extra_args, {}) != "none"
            )
            # LLAMA_ARG_MAIN_GPU still reaches the child and changes which card -sm none keeps.
            or str(source_env.get("LLAMA_ARG_MAIN_GPU", "")).strip()
            # Any explicit --fit: the retry's appended '--fit on' would override a user '--fit off'.
            or any(
                str(a) in ("-fit", "--fit") or str(a).startswith(("-fit=", "--fit="))
                for a in (extra_args or ())
            )
            or str(source_env.get("LLAMA_ARG_FIT", "")).strip()
            # --rpc devices are remote and go first in the list, so local VRAM numbers are wrong.
            or (_extra_args_device(extra_args, {"--rpc"}) or "").strip()
            or str(source_env.get("LLAMA_ARG_RPC", "")).strip()
            # --fit off would silently drop the user's --fit-target margin.
            or fit_target_margin_in(extra_args, source_env) is not None
        ):
            logger.debug("Tensor spill: declined, pass-through arguments own the placement")
            return None

        # llama.cpp is last-wins on --parallel; a larger pass-through grows the cache unpriced.
        priced_parallel = int(inputs.get("n_parallel") or 1)
        override_parallel = _extra_args_n_parallel(extra_args, source_env)
        if override_parallel is not None and override_parallel > priced_parallel:
            logger.debug(
                "Tensor spill: declined, --parallel %d overrides the %d slots this was priced at",
                override_parallel,
                priced_parallel,
            )
            return None

        model_size = int(inputs.get("model_size") or 0)
        kv_cache_bytes = int(inputs.get("kv_cache_bytes") or 0)
        rows = list(inputs.get("gpus") or ())
        if not model_size or not kv_cache_bytes or not rows:
            return None
        if not self._can_estimate_kv():
            return None

        layout = self._tensor_spill_layout(inputs.get("model_path"))
        if layout is None or not layout.complete:
            return None

        # Shared rows are dropped: an iGPU reports host RAM as VRAM, double counting the pool.
        pinned = inputs.get("gpu_indices")
        shared = set(inputs.get("shared_gpu_ids") or ())
        pinned_set = None if pinned is None else set(pinned)
        # The child may still use the shared device and an iGPU takes most layers; decline.
        if shared and (pinned_set is None or (shared & pinned_set)):
            logger.debug(
                "Tensor spill: declined, a shared-memory GPU stays in the child's device list"
            )
            return None
        # Usable budget from Unsloth's fit, falling back to raw free.
        usable_mib = inputs.get("gpu_usable_mib") or {}
        kept = [
            (idx, free_mib)
            for idx, free_mib in rows
            if idx not in shared and (pinned_set is None or idx in pinned_set)
        ]
        # -sm none keeps only devices[main_gpu] (0 here); argv only since env may be stripped.
        if _extra_args_split_mode(extra_args, {}) == "none" and kept:
            kept = kept[:1]
        vram_per_device = [
            int(usable_mib.get(idx, free_mib) * 1024 * 1024) for idx, free_mib in kept
        ]
        # llama.cpp splits rows by RAW free VRAM, so model the split on raw numbers.
        split_weights = [int(free_mib * 1024 * 1024) for _idx, free_mib in kept]
        # -ts replaces the free-memory split. Read the env the child gets: load_model may pop it.
        _inherited_sm = str(source_env.get("LLAMA_ARG_SPLIT_MODE", "")).strip().lower()
        _ts_env = source_env if _inherited_sm in ("", "layer") else {}
        _ts = _extra_args_tensor_split(extra_args, _ts_env)
        if _ts is None and (
            _extra_args_set_any_flag(extra_args, _TENSOR_SPLIT_FLAGS)
            or str(_ts_env.get("LLAMA_ARG_TENSOR_SPLIT", "")).strip()
        ):
            # An unparseable -ts still reaches the child, so decline.
            logger.debug("Tensor spill: declined, -ts is present but could not be parsed")
            return None
        if _ts is not None:
            if len(_ts) < len(kept):
                logger.debug(
                    "Tensor spill: declined, -ts names %d shares for %d devices",
                    len(_ts),
                    len(kept),
                )
                return None
            split_weights = _ts[: len(kept)]
        if not vram_per_device:
            return None
        avail_mib = self._available_system_memory_mib()
        if avail_mib is None:
            return None

        # An unpinned drafter spreads over all GPUs but is booked on device 0; decline.
        if inputs.get("separate_draft_on_gpu") and len(vram_per_device) > 1:
            logger.debug(
                "Tensor spill: declined, a separate drafter's bytes cannot be placed "
                "across %d devices",
                len(vram_per_device),
            )
            return None

        # Charge back the dropped MTP blocks when a draft will engage.
        extra_gpu_bytes = int(inputs.get("extra_gpu_bytes") or 0)
        if inputs.get("mtp_will_engage") and layout.excluded_block_bytes:
            extra_gpu_bytes += layout.excluded_block_bytes

        # Flat compute buffer, charged once on device 0.
        extra_gpu_bytes += int(inputs.get("compute_buffer_flat") or 0)

        # A projector set via env that Studio never sized still loads on GPU; decline.
        if inputs.get("env_mmproj_unsized"):
            logger.debug("Tensor spill: declined, an inherited projector could not be sized")
            return None
        extra_gpu_bytes += int(inputs.get("env_mmproj_bytes") or 0)

        # Pass-through LoRA / control-vector weights are GPU resident and never mmapped.
        sidecar_bytes = _sidecar_adapter_bytes(extra_args)
        if sidecar_bytes is None:
            logger.debug("Tensor spill: declined, a pass-through adapter could not be sized")
            return None
        # Adapter tensors follow layers across cards; per-device share is unknown, so decline.
        if sidecar_bytes and len(vram_per_device) > 1:
            logger.debug(
                "Tensor spill: declined, a pass-through adapter's bytes cannot be placed "
                "across %d devices",
                len(vram_per_device),
            )
            return None
        extra_gpu_bytes += sidecar_bytes

        decode_threads = _spilled_decode_threads(
            inputs.get("n_threads"),
            extra_args,
        )
        if decode_threads is None:
            logger.debug("Tensor spill: declined, decode CPU settings cannot be priced")
            return None

        return plan_placement(
            layout,
            vram_per_device,
            avail_mib * 1024 * 1024,
            int(inputs.get("n_ctx") or 0),
            split_weights_per_device = split_weights,
            kv_layer_weights = list(inputs.get("kv_layer_weights") or ()),
            opts = PlanOptions(
                overhead_bytes_per_device = (
                    int(inputs.get("soft_overhead") or 0)
                    + int(inputs.get("ctx_compute_per_device") or 0)
                ),
                # Charged only for devices after the first, like elsewhere in this file.
                pipeline_overhead_bytes = self._PIPELINE_PER_DEVICE_OVERHEAD_MIB * 1024 * 1024,
                host_ram_headroom_bytes = _HOST_RAM_HEADROOM_MIB * 1024 * 1024,
                # -nkvo moves cache out of VRAM, so it shrinks the deficit.
                kv_on_host = not _kv_offload_from_args(extra_args, env = source_env),
                # Projector and MTP reserve: GPU allocations the layout cannot see.
                extra_resident_bytes = extra_gpu_bytes,
                # Spilled decode runs on the CPU backend, so the penalty tracks core count.
                host = HostProfile(
                    threads = decode_threads,
                    # On unified-memory APUs a spill frees no VRAM; the planner abstains only if told.
                    unified_memory = self._amd_apu_wants_unified_memory(inputs.get("gpu_indices")),
                ),
            ),
            # Floor from Unsloth's accurate cache estimate; layout.kv_bytes() is a bare f16 product.
            kv_bytes_floor = kv_cache_bytes,
        )

    @staticmethod
    def _spill_plan_flags_for(plan: "Optional[SpillPlan]") -> "list[str]":
        """The argv tokens for ``plan``, or ``[]`` when it must not be emitted.

        The emptiness test is the point. ``Plan`` is a dataclass with no
        ``__bool__``/``__len__``, so EVERY instance is truthy -- including the
        ones ``plan_placement`` returns to report that it could not place the
        load (``insufficient``), that it abstained (incomplete layout, unified
        memory, no creditable VRAM), or that the load already fits. Emitting for
        those would append ``-ngl -1 --fit off`` with no tensor moved to the
        host, i.e. pin every layer to the GPU and switch the fitter off on
        exactly the loads the planner just said do not fit. Only a plan that
        actually spills something earns the flags; everything else falls through
        to ``--fit on``, which is what this arm did before the planner existed.

        One flag per pattern: llama-server ACCUMULATES repeated ``-ot``
        (common/arg.cpp:2657 push_backs into the shared override vector). Do not
        join with ";" -- that is llama-bench's separator; llama-server splits an
        ``-ot`` value on ",".

        ``--fit off`` is REQUIRED, not tidiness. The fitter aborts only on an
        n_gpu_layers the USER set (common/fit.cpp:377) and -1 is llama.cpp's own
        default (llama-model.cpp:2453), so ``-ngl -1`` does not hold it off: left
        on, it would re-place layers over this plan and put the cache back on the
        host. ``-ngl -1`` keeps every layer assigned to a GPU so the cache stays
        there (llama-kv-cache.cpp:215); the ``-ot`` patterns move only the named
        weights.
        """
        if plan is None or not plan.spills_anything:
            return []
        tokens = [tok for pat in plan.ot_patterns for tok in ("-ot", f"{pat}=CPU")]
        if not tokens:
            return []
        return ["-ngl", "-1", "--fit", "off", *tokens]

    def _drop_tensor_spill(self, run_cmd: "list[str]", why: str) -> "list[str]":
        """Take the spill plan back out of an argv and restore ``--fit on``.

        Every retry that re-places the model or resizes the cache invalidates the
        arithmetic the plan was built on: a no-flash retry changes the KV dtype, an
        arch fallback changes the device set, a projector move changes the resident
        floor. Rather than re-plan on a path that is already recovering from a
        crash, hand the placement back to llama.cpp, which is what this arm did
        before the planner existed.

        The record is deliberately NOT cleared: the CPU fallback respawns later
        from an argv that may still carry these tokens.
        """
        if not self._spill_plan_flags:
            return run_cmd
        stripped = _without_subsequence(run_cmd, self._spill_plan_flags)
        if stripped == run_cmd:
            return run_cmd
        logger.info("Tensor spill: dropping the plan for the %s retry; %s", why, "using --fit on")
        return [*stripped, "--fit", "on"]

    def _tensor_spill_layout(
        self,
        model_path: "Optional[str]",
        *,
        all_shards: bool = False,
    ) -> "Optional[ModelLayout]":
        """The GGUF's placement buckets, read once per path and cached.

        Per BLOCK, not per bucket total, so the planner can spill the minimum set
        that closes the deficit rather than the whole FFN. That matters: the spill
        penalty is linear in bytes (measured 5.544 ms/GiB across 16/32/48/65
        blocks, intercept -0.10 ms), so every byte spilled beyond the deficit is
        paid on every token for nothing.

        Any read failure returns None and the whole feature abstains, leaving the
        argv byte-identical to today. A guess here would be priced as a fit.
        """
        from core.inference.offload_layout import layout_from_gguf

        if not model_path:
            return None
        # Keyed on (size, mtime_ns), not name, so a replaced file is re-read.
        try:
            st = os.stat(model_path)
            key = (model_path, st.st_size, st.st_mtime_ns, all_shards)
        except OSError:
            key = (model_path, None, None, all_shards)
        cached = getattr(self, "_spill_layout_cache", None)
        if cached is not None and cached[0] == key:
            return cached[1]
        try:
            layout = (
                layout_from_gguf(model_path, all_shards = True)
                if all_shards
                else layout_from_gguf(model_path)
            )
        except Exception as e:
            logger.debug("Tensor spill: cannot read layout from %s (%s)", model_path, e)
            layout = None
        self._spill_layout_cache = (key, layout)
        return layout

    @staticmethod
    def _fit_off_retry_eligible(cmd: "list[str]", use_fit: bool) -> bool:
        """Whether a llama-server startup crash may be retried with --fit off.

        Only when Unsloth's own VRAM math placed the model (use_fit=False)
        and nothing on the command line set the fit mode explicitly
        (-fit / --fit, space- or equals-form). --fit-ctx / --fit-target /
        -fitc / -fitt tune the fit step but do not select the mode, so
        they do not block the retry.
        """
        if use_fit:
            return False
        for a in cmd:
            if a in ("-fit", "--fit") or a.startswith(("-fit=", "--fit=")):
                return False
        return True

    def _probe_mtp_decode(self, timeout: float = 60.0) -> bool:
        """One tiny /completion to confirm MTP survives the first decode.

        MTP-draft can pass /health yet crash the flash-attn kernel only once
        tokens generate (e.g. under --split-mode tensor). False on any error so
        the caller can drop MTP and retry.
        """
        url = f"{self.base_url}/completion"
        payload = {"prompt": "Hi", "n_predict": 4, "temperature": 0.0, "stream": False}
        try:
            resp = httpx.post(
                url,
                json = payload,
                timeout = timeout,
                headers = self._auth_headers,
                trust_env = False,
            )
        except Exception as e:
            logger.debug(f"MTP decode probe failed: {e}")
            return False
        if resp.status_code != 200:
            logger.debug(f"MTP decode probe returned HTTP {resp.status_code}")
            return False
        if self._process is not None and self._process.poll() is not None:
            return False
        return True

    def _slot_launch_fingerprint(self) -> tuple:
        sidecars = []
        for path in self._sidecar_weight_files():
            try:
                st = os.stat(path)
                sidecars.append((path, st.st_size, st.st_mtime_ns))
            except OSError:
                sidecars.append((path, None, None))
        return (
            tuple(self._extra_args or ()),
            tuple(sidecars),
            self._requested_n_ctx,
            self._effective_context_length,
            self._effective_cache_types,
            self.effective_parallel_slots,
            self._swa_full,
            self._kv_cache_unified,
            self._n_ubatch,
            self._flash_attn_enabled,
        )

    @staticmethod
    def _gguf_load_source_identity(path: str, mmproj_path: Optional[str] = None) -> Optional[tuple]:
        """Identity of the exact GGUF inode(s) handed to the resident process."""
        p = Path(path)
        paths = [p]
        match = _SHARD_FULL_RE.match(p.name)
        if match:
            prefix, _first, total = match.groups()
            paths = [
                p.with_name(f"{prefix}-{index:05d}-of-{total}{p.suffix}")
                for index in range(1, int(total) + 1)
            ]
        try:
            identity = []
            for shard in paths:
                resolved = shard.resolve()
                stat = shard.stat()
                identity.append(
                    (
                        str(resolved),
                        stat.st_dev,
                        stat.st_ino,
                        stat.st_size,
                        stat.st_mtime_ns,
                    )
                )
            if mmproj_path:
                projector = Path(mmproj_path)
                resolved = projector.resolve()
                stat = projector.stat()
                identity.append(
                    (
                        "mmproj",
                        str(resolved),
                        stat.st_dev,
                        stat.st_ino,
                        stat.st_size,
                        stat.st_mtime_ns,
                    )
                )
            return tuple(identity)
        except (OSError, RuntimeError):
            return None

    def _gguf_file_identity(self, path) -> Optional[tuple]:
        p = Path(path)
        paths = [p]
        m = _SHARD_FULL_RE.match(p.name)
        if m:
            prefix, _first, total = m.groups()
            paths = [
                p.with_name(f"{prefix}-{i:05d}-of-{total}{p.suffix}")
                for i in range(1, int(total) + 1)
            ]
        try:
            return tuple((sp.stat().st_size, sp.stat().st_mtime_ns) for sp in paths)
        except OSError:
            return None

    _SIDECAR_WEIGHT_FLAGS = (
        "--mmproj",
        "-mm",
        "--lora",
        "--lora-scaled",
        "--control-vector",
        "--control-vector-scaled",
    )

    def _sidecar_weight_files(self) -> list[str]:
        # llama.cpp: comma-separated paths, FNAME:SCALE on -scaled (older: FNAME SCALE).
        args = [str(a).strip() for a in (self._extra_args or ())]
        files: list[str] = []
        for i, arg in enumerate(args):
            flag = _flag_name(arg)
            _, sep, inline = arg.partition("=")
            if flag not in self._SIDECAR_WEIGHT_FLAGS:
                continue
            operand = inline if sep else (args[i + 1] if i + 1 < len(args) else "")
            if not operand:
                continue
            candidates = [operand]
            pieces = [p for p in operand.split(",") if p]
            if len(pieces) > 1:
                candidates.extend(pieces)
            if flag.endswith("-scaled"):
                for item in list(candidates):
                    # rpartition so drive letters are not taken as scales.
                    head, colon, tail = item.rpartition(":")
                    if not (colon and head):
                        continue
                    try:
                        float(tail)
                    except ValueError:
                        continue
                    candidates.append(head)
            for cand in candidates:
                if cand not in files:
                    files.append(cand)
        return files

    def _prompt_cache_off(self) -> bool:
        # Last prompt-cache flag wins; env only when unset.
        last = None
        for arg in self._extra_args or ():
            flag = arg.strip().split("=", 1)[0]
            if flag in ("--cache-prompt", "--no-cache-prompt"):
                last = flag
        if last is not None:
            return last == "--no-cache-prompt"
        if self._prompt_cache_disabled:
            return True
        if os.environ.get("LLAMA_ARG_NO_CACHE_PROMPT") is not None:
            return True
        env = (os.environ.get("LLAMA_ARG_CACHE_PROMPT") or "").strip().lower()
        return env in _LLAMA_ARG_FALSE_VALUES

    def save_slots_for_resume(
        self, should_abort: Optional[Callable[[], bool]] = None
    ) -> Optional[dict]:
        if (
            not self.is_loaded
            or not self._slot_save_dir
            or not self._gguf_path
            or self._prompt_cache_off()
        ):
            return None
        # phi3 GGUFs have a window but no key/value length; llama.cpp uses a non-SWA cache.
        if (
            (self._sliding_window or 0) > 0
            and self._kv_key_length is not None
            and self._kv_value_length is not None
            and not self._swa_full
        ):
            logger.debug("Skipping slot save: compact SWA cache cannot be reused after restart")
            return None
        save_dir = Path(self._slot_save_dir)
        gguf_stat = self._gguf_file_identity(self._gguf_path)
        if gguf_stat is None:
            return None
        launch = self._slot_launch_fingerprint()
        # GGUF or sidecar swapped on disk: live KV belongs to old weights, don't persist.
        if self._slot_loaded_identity is not None and self._slot_loaded_identity != (
            gguf_stat,
            launch,
        ):
            logger.debug("Skipping slot save: model files changed on disk since load")
            return None
        try:
            estimate = self._estimate_kv_cache_bytes(
                self._kv_cache_context_total
                or self._effective_context_length
                or self._context_length
                or 0,
                max(self._effective_cache_types, key = _kv_bytes_per_elem),
                n_parallel = self.effective_parallel_slots,
                swa_full = self._swa_full,
                kv_unified = self._kv_cache_unified,
                n_ubatch = self._n_ubatch,
                flash_attn = self._flash_attn_enabled,
            )
            if estimate > _SLOT_SAVE_MAX_BYTES:
                logger.debug(
                    "Skipping slot save: estimated %d bytes exceeds cap %d",
                    estimate,
                    _SLOT_SAVE_MAX_BYTES,
                )
                return None
            # A 0 estimate means unknown, so require room for the whole cap.
            required = (estimate if estimate > 0 else _SLOT_SAVE_MAX_BYTES) + (1 << 30)
            if shutil.disk_usage(save_dir).free < required:
                logger.debug("Skipping slot save: insufficient free disk")
                return None
        except Exception:
            pass
        token = uuid.uuid4().hex[:8]
        entries: list[dict] = []
        total_bytes = 0
        for slot in range(self.effective_parallel_slots):
            if should_abort is not None and should_abort():
                break
            filename = f"resume-{token}-slot{slot}.bin"
            path = save_dir / filename
            try:
                resp = httpx.post(
                    f"{self.base_url}/slots/{slot}",
                    params = {"action": "save"},
                    json = {"filename": filename},
                    headers = self._auth_headers,
                    timeout = _SLOT_SAVE_HTTP_TIMEOUT,
                    trust_env = False,
                )
            except Exception as e:
                logger.debug(f"slot {slot} save failed: {e}")
                with contextlib.suppress(OSError):
                    path.unlink()
                break
            if resp.status_code != 200:
                logger.debug(f"slot {slot} save returned HTTP {resp.status_code}")
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            try:
                body = resp.json()
                if not isinstance(body, dict):
                    raise ValueError("slot save response was not a JSON object")
                n_saved = int(body.get("n_saved") or 0)
            except Exception as e:
                # Clean up the written file (chat KV) on a malformed 200 too.
                logger.debug(f"slot {slot} save returned an invalid response: {e}")
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            if n_saved <= 0:
                with contextlib.suppress(OSError):
                    path.unlink()
                continue
            # Count bytes on disk, not the server's count, in case a binary under-reports.
            try:
                n_written = path.stat().st_size
            except OSError:
                n_written = 0
            total_bytes += n_written
            entries.append({"id": slot, "filename": filename, "n_saved": n_saved})
            if total_bytes > _SLOT_SAVE_MAX_BYTES:
                break
        if not entries:
            return None
        if total_bytes > _SLOT_SAVE_MAX_BYTES:
            logger.debug(
                "Discarding slot save: %d bytes exceeds cap %d",
                total_bytes,
                _SLOT_SAVE_MAX_BYTES,
            )
            for entry in entries:
                with contextlib.suppress(OSError):
                    (save_dir / entry["filename"]).unlink()
            return None
        return {
            "dir": self._slot_save_dir,
            "binary": self._slot_save_binary,
            "gguf": str(self._gguf_path),
            "gguf_stat": gguf_stat,
            "launch": launch,
            "slots": entries,
        }

    def restore_slots_for_resume(self, manifest: dict) -> None:
        if not self.is_loaded or not self._slot_save_dir:
            return
        for entry in manifest.get("slots") or []:
            try:
                resp = httpx.post(
                    f"{self.base_url}/slots/{int(entry['id'])}",
                    params = {"action": "restore"},
                    json = {"filename": str(entry["filename"])},
                    headers = self._auth_headers,
                    timeout = _SLOT_SAVE_HTTP_TIMEOUT,
                    trust_env = False,
                )
            except Exception as e:
                logger.debug(f"slot restore failed: {e}")
                break
            if resp.status_code != 200:
                logger.debug(f"slot {entry.get('id')} restore returned HTTP {resp.status_code}")

    def _maybe_recover_from_mtp_crash(self, exc: Optional[BaseException] = None) -> bool:
        """Schedule one background reload without MTP after a mid-generation death.

        MTP+tensor can crash the flash-attn kernel on a later request, after
        load_model returned, past the load-time fallback and decode probe. Not a
        persistent ban: a fresh load re-tries MTP. Returns True if scheduled.
        """
        if self._cancel_event.is_set():
            return False
        if not self._mtp_runtime_fallback_active:
            return False
        # Read before claiming: a raise after the claim strands the flag.
        snapshot = self._last_load_intent
        proc = self._process
        if snapshot is None or proc is None:
            return False
        with self._mtp_runtime_fallback_lock:
            if self._mtp_runtime_fallback_in_progress:
                return False
            self._mtp_runtime_fallback_in_progress = True

        def _recover():
            try:
                # Confirm exit so a transient stream error can't disable MTP.
                deadline = time.monotonic() + 5.0
                while proc.poll() is None and time.monotonic() < deadline:
                    time.sleep(0.1)
                if proc.poll() is None:
                    logger.debug("Generation error but llama-server is alive; keeping MTP.")
                    return
                logger.warning(
                    "llama-server exited mid-generation with MTP under tensor "
                    "parallelism (%s); reloading without speculative decoding.",
                    type(exc).__name__ if exc is not None else "server exited",
                )
                # Re-check under the load lock so a newer load isn't clobbered.
                requested_mode = snapshot.speculative_type
                with self._serial_load_lock:
                    with self._lock:
                        if self._cancel_event.is_set():
                            logger.info("MTP-crash reload skipped: load was cancelled/unloaded.")
                            return
                        if self._process is not proc:
                            logger.info("MTP-crash reload skipped: a newer load is already active.")
                            return
                        if self._last_load_intent != snapshot:
                            logger.info("MTP-crash reload skipped: load settings changed.")
                            return
                        unload_epoch = self._unload_epoch
                    # llama.cpp appends spec types, so strip them from extras.
                    _ea = list(snapshot.extra_args or ())
                    fallback_extra_args = snapshot.extra_args
                    if _extra_args_requests_mtp(_ea, env = _child_spec_env(_ea)):
                        fallback_extra_args = tuple(
                            strip_shadowing_flags(
                                _ea,
                                strip_context = False,
                                strip_cache = False,
                                strip_spec = True,
                                strip_template = False,
                                strip_split_mode = False,
                            )
                        )
                    fallback = replace(
                        snapshot,
                        speculative_type = "off",
                        extra_args = fallback_extra_args,
                    )
                    started = bool(self.load_model(fallback))
                    if not started:
                        logger.info("MTP-crash reload stopped before the replacement was ready.")
                        return
                    undo_reload = False
                    with self._lock:
                        if self._cancel_event.is_set() or self._unload_epoch != unload_epoch:
                            undo_reload = True
                        else:
                            # Keep the stripped list, or the comparator reloads the crashing MTP config.
                            if fallback_extra_args is not snapshot.extra_args:
                                self._requested_extra_args = (
                                    self._strip_device_extra_args(_ea)
                                    if self._gpu_ids_own_placement(snapshot.gpu_ids)
                                    else list(_ea)
                                )
                            self._requested_spec_mode = _canonicalize_spec_mode(requested_mode)
                            self._spec_fallback_reason = "runtime_error"
                    if undo_reload:
                        logger.info(
                            "MTP-crash reload undone: the model was unloaded during reload."
                        )
                        self.unload_model()
                        return
                logger.info("Reloaded without MTP after the tensor-parallel crash.")
            except Exception as e:
                logger.error(f"Reload without MTP failed: {e}")
            finally:
                with self._mtp_runtime_fallback_lock:
                    self._mtp_runtime_fallback_in_progress = False

        try:
            threading.Thread(target = _recover, daemon = True, name = "mtp-crash-reload").start()
        except RuntimeError as exc:
            # Release the claim, or respawn is blocked forever.
            with self._mtp_runtime_fallback_lock:
                self._mtp_runtime_fallback_in_progress = False
            logger.error(f"Could not start the MTP-crash reload: {exc}")
            return False
        return True

    def _start_mtp_crash_watchdog(self) -> None:
        """Background poll that recovers on an MTP+tensor crash even when no
        request observes it (direct proxy endpoints, or nothing in flight).

        Armed only for a live MTP+tensor launch; the no-MTP reload disarms it, so
        it can't loop.
        """
        if not self._mtp_runtime_fallback_active:
            return
        proc = self._process
        if proc is None:
            return
        self._stop_mtp_crash_watchdog()
        stop = threading.Event()
        self._mtp_watchdog_stop = stop

        def _watch():
            # _kill_process sets stop before terminating; only a real crash recovers.
            while not stop.wait(1.0):
                if proc.poll() is not None:
                    if not stop.is_set():
                        self._maybe_recover_from_mtp_crash()
                    return

        t = threading.Thread(target = _watch, daemon = True, name = "mtp-crash-watchdog")
        self._mtp_watchdog_thread = t
        t.start()

    def _stop_mtp_crash_watchdog(self) -> None:
        """Signal the crash watchdog to exit; called before any deliberate kill."""
        stop = getattr(self, "_mtp_watchdog_stop", None)
        if stop is not None:
            stop.set()
        self._mtp_watchdog_thread = None

    _HEALTH_STALL_TIMEOUT_S = 600.0
    _STARTUP_PROGRESS_SAMPLE_S = 5.0
    # Ignore activity from the health probes themselves.
    _STARTUP_PROGRESS_MIN_BYTES = 1 << 20
    _STARTUP_PROGRESS_MIN_PAGE_FAULTS = 64
    _STARTUP_PROGRESS_MIN_CPU_FRACTION = 0.05

    @staticmethod
    def _page_faults(member, memory) -> int:
        # mmap loading progresses via page faults while RSS stays flat.
        for field in ("pfaults", "num_page_faults"):  # macOS, Windows
            if hasattr(memory, field):
                return getattr(memory, field)
        try:
            with open(f"/proc/{member.pid}/stat", "rb") as f:
                fields = f.read().rsplit(b")", 1)[1].split()
            return int(fields[7]) + int(fields[9])  # minflt + majflt
        except (OSError, IndexError, ValueError):
            return 0

    @classmethod
    def _startup_work_sample(cls, process) -> Optional[tuple[float, int, int, int]]:
        """Return cumulative (CPU, RSS, bytes read, page faults) for the process tree."""
        pid = getattr(process, "pid", None)
        if not isinstance(pid, int):
            return None
        try:
            import psutil
            root = psutil.Process(pid)
            members = [root, *root.children(recursive = True)]
        except Exception:
            return None
        cpu = 0.0
        rss = read = faults = 0
        for member in members:
            try:
                with member.oneshot():
                    times = member.cpu_times()
                    memory = member.memory_info()
                    try:
                        io = member.io_counters()
                    except (AttributeError, psutil.AccessDenied):
                        io = None
                member_faults = cls._page_faults(member, memory)
            except Exception:
                if member is root:
                    return None
                continue
            cpu += times.user + times.system
            rss += memory.rss
            faults += member_faults
            if io is not None:
                read += getattr(io, "read_chars", io.read_bytes)
        return (cpu, rss, read, faults)

    @classmethod
    def _made_startup_progress(
        cls, before: tuple[float, int, int, int], after: tuple[float, int, int, int], elapsed: float
    ) -> bool:
        # RSS is a high-water mark so evicted pages are not counted twice.
        return (
            after[1] - before[1] >= cls._STARTUP_PROGRESS_MIN_BYTES
            or after[2] - before[2] >= cls._STARTUP_PROGRESS_MIN_BYTES
            or after[3] - before[3] >= cls._STARTUP_PROGRESS_MIN_PAGE_FAULTS
            or after[0] - before[0] >= cls._STARTUP_PROGRESS_MIN_CPU_FRACTION * elapsed
        )

    def _wait_for_health(
        self,
        timeout: float = 120.0,
        interval: float = 0.5,
        cancelled: Optional[Callable[[], bool]] = None,
    ) -> bool:
        """Poll /health until success, exit, cancellation, or a startup stall."""
        deadline = time.monotonic() + timeout
        work_sample = None
        work_sampled_at = None
        work_checked_at = None
        url = f"{self.base_url}/health"
        health_probe_event = getattr(self, "_health_probe_event", None)
        if health_probe_event is None:
            health_probe_event = self._health_probe_event = threading.Event()

        if cancelled is None:
            cancel_event = getattr(self, "_cancel_event", None)
            cancelled = cancel_event.is_set if cancel_event is not None else None

        self._health_wait_cancelled = False
        # No teardown reset here: _torn_down_process is matched by identity.
        process = None

        while (now := time.monotonic()) < deadline:
            if getattr(self, "_shutting_down", False):
                logger.info("llama-server was torn down while waiting for it to become healthy")
                self._health_wait_cancelled = True
                return False
            # unload_model() blocks on self._lock, which the load holds across this wait.
            if cancelled is not None and cancelled():
                logger.info("llama-server startup cancelled before it became healthy")
                self._health_wait_cancelled = True
                return False
            health_probe_event.clear()
            # Read once: shutdown clears the reference from another thread.
            process = self._process
            if process is None:
                logger.info("llama-server was torn down while waiting for it to become healthy")
                self._health_wait_cancelled = True
                return False
            if process.poll() is not None:
                # A teardown holds the reference, so this child exiting is deliberate.
                if getattr(self, "_torn_down_process", None) is process:
                    logger.info("llama-server was torn down while waiting for it to become healthy")
                    self._health_wait_cancelled = True
                    return False
                if self._stdout_thread is not None:
                    self._stdout_thread.join(timeout = 2)
                output = "\n".join(self._stdout_lines[-50:])
                # Keep the tail: crash details print after the long startup banner.
                _log_hint = (
                    f" Full log: {self._llama_log_path}"
                    if getattr(self, "_llama_log_path", None)
                    else ""
                )
                logger.error(
                    f"llama-server exited with code {process.returncode}. "
                    f"Output (tail): {output[-2000:]}{_log_hint}"
                )
                return False

            if work_checked_at is None or now - work_checked_at >= self._STARTUP_PROGRESS_SAMPLE_S:
                work_checked_at = now
                sample = self._startup_work_sample(process)
                if sample is not None:
                    if work_sample is not None and self._made_startup_progress(
                        work_sample, sample, now - work_sampled_at
                    ):
                        deadline = now + timeout
                    peak = sample[1] if work_sample is None else max(work_sample[1], sample[1])
                    work_sample = (sample[0], peak, sample[2], sample[3])
                    work_sampled_at = now

            try:
                # trust_env=False: an HTTP proxy can 503 for 127.0.0.1 and hang the load.
                resp = httpx.get(url, timeout = 2.0, trust_env = False)
                if resp.status_code == 200:
                    # A cancel during the 2s probe must not publish the dropped model.
                    if cancelled is not None and cancelled():
                        logger.info("llama-server became healthy after the load was cancelled")
                        self._health_wait_cancelled = True
                        return False
                    if getattr(self, "_shutting_down", False):
                        logger.info("llama-server became healthy while the app was shutting down")
                        self._health_wait_cancelled = True
                        return False
                    return True
            except (
                httpx.ConnectError,
                httpx.TimeoutException,
                # TCP RST while binding (Windows WinError 10054).
                httpx.ReadError,
                httpx.RemoteProtocolError,
                httpx.WriteError,
            ):
                pass

            health_probe_event.wait(interval)

        if cancelled is not None and cancelled():
            logger.info("llama-server startup cancelled at the health-check deadline")
            self._health_wait_cancelled = True
            return False

        # Check both: _shutting_down is set on entry, _torn_down_process later.
        if getattr(self, "_shutting_down", False) or (
            process is not None and getattr(self, "_torn_down_process", None) is process
        ):
            logger.info("llama-server was torn down while waiting for it to become healthy")
            self._health_wait_cancelled = True
            return False

        # Marker lets _classify_llama_start_failure tell a hung load from a bad GGUF.
        marker = f"llama-server health check timed out: no startup progress for {timeout:g}s"
        self._stdout_lines.append(marker)
        logger.error(marker)
        return False

    @staticmethod
    def _fit_target_margin_mib(
        *,
        auto_fit: bool,
        fit_target_delta_mib: float = 0.0,
        supports_fit_target: bool = True,
    ) -> float:
        """Free VRAM per device llama.cpp's fitter keeps for itself under ``--fit on``.

        One reader for the flag and for the load-mode fit, so the margin the child is
        told to keep and the margin the fit refuses to spend cannot drift. A server
        too old for ``--fit-target`` still keeps llama.cpp's own 1024 MiB default
        (common/common.h, ``fit_params_target``), which is also what the legacy path
        deliberately stays silent about.
        """
        if not supports_fit_target:
            return _LLAMA_FIT_TARGET_DEFAULT_MIB
        base = _VRAM_FLOOR_RESERVE_MIB if auto_fit else _LLAMA_FIT_TARGET_DEFAULT_MIB
        return max(_VRAM_FLOOR_RESERVE_MIB, base + fit_target_delta_mib)

    @staticmethod
    def _ctx_integrity_flags(
        n_parallel: int,
        use_fit: bool,
        auto_fit: bool,
        requested_ctx: int,
        effective_ctx: int,
        caps: dict,
        *,
        fit_target_delta_mib: float = 0.0,
    ) -> list[str]:
        """Flags that keep the per-request window equal to the advertised ctx.

        Explicit ``--parallel`` disables llama-server's auto-slots
        ``--kv-unified`` default, silently splitting ``-c`` into per-slot
        windows of ``-c / N``; restore the shared pool so one request can use
        the full context. With ``--fit on``, ``--fit-ctx`` floors the fit step
        at an explicitly requested ctx so it offloads or fails instead of
        silently shrinking the window. The 8192 auto-floor applies only under
        Manual + Auto (``auto_fit``), which omits ``-c``: on the legacy auto path
        ``-c 0`` already pins the native window and ``--fit-ctx 8192`` would
        override it down to 8192. ``--fit-target`` starts from the tighter 512 MiB
        margin there and from llama.cpp's own default on the legacy path, moved by
        whatever the VRAM budget asks for either way (``fit_target_delta_mib``)
        and never below the 512 MiB floor.
        """
        flags: list[str] = []
        if n_parallel > 1 and caps.get("supports_kv_unified"):
            flags.append("--kv-unified")
        if use_fit and caps.get("supports_fit_ctx"):
            if requested_ctx > 0 and effective_ctx > 0:
                flags.extend(["--fit-ctx", str(effective_ctx)])
            elif auto_fit:
                # Manual + Auto omits -c, so floor at 8192 so --fit keeps a usable window.
                flags.extend(["--fit-ctx", "8192"])
        if use_fit and caps.get("supports_fit_target"):
            # 512 margin under Manual + Auto, llama.cpp's 1024 default on the legacy path.
            _target = LlamaCppBackend._fit_target_margin_mib(
                auto_fit = auto_fit,
                fit_target_delta_mib = fit_target_delta_mib,
            )
            if auto_fit or _target != _LLAMA_FIT_TARGET_DEFAULT_MIB:
                flags.extend(["--fit-target", str(int(_target))])
        return flags

    def _query_server_props(self) -> Optional[dict]:
        """llama-server's ``/props``, or None when it cannot be read."""
        url = f"{self.base_url}/props"
        try:
            # /props is not one of llama-server's public endpoints, so with the
            # child's --api-key an unauthenticated read 401s: the context readback silently keeps
            # the requested -c, and video reads as unsupported on a model that
            # supports it. None when there is no child key, which is httpx's
            # default and what every other call site here relies on.
            resp = httpx.get(url, headers = self._auth_headers, timeout = 5.0, trust_env = False)
            if resp.status_code != 200:
                return None
            props = resp.json()
            return props if isinstance(props, dict) else None
        except Exception:
            return None

    def _query_server_n_ctx(self) -> Optional[int]:
        """Per-slot context llama-server actually allocated, from ``/props``.

        The memory-fit step or ``--parallel`` slot split can leave this below
        the requested ``-c``; requests are validated against this value.

        Records the declared modalities on the way past: video input depends on
        build flags and ffmpeg, neither visible from the GGUF.
        """
        props = self._query_server_props()
        if props is None:
            return None
        modalities = props.get("modalities")
        if isinstance(modalities, dict):
            self._has_video_input = bool(modalities.get("video"))
        settings = props.get("default_generation_settings") or {}
        n_ctx = settings.get("n_ctx")
        return int(n_ctx) if n_ctx else None

    def _reconcile_effective_ctx_with_server(self, requested_n_ctx: int = 0) -> None:
        """Adopt the server's real ``n_ctx`` within an explicit requested ceiling.

        Keeps ``context_length`` (load response, status route, passthrough
        ``max_tokens`` ceiling) honest; clients sized to the requested value
        would otherwise hit ``exceed_context_size_error`` 400s early. A trailing
        pass-through ``--ctx-size`` can also make the server larger than Studio's
        pre-launch VRAM-fit estimate; publish that confirmed allocation without
        advertising beyond the user's resolved explicit request.

        ``requested_n_ctx`` is the EXPLICIT pass-through override (0 when absent),
        not ``resolve_requested_ctx``'s field fallback: only a flag emitted after
        Studio's own ``-c`` can allocate past the fit, so gating on the flag keeps
        llama.cpp's context padding from being published as an override that does
        not exist.

        ``_max_context_length`` deliberately stays put: /props confirms what was
        ALLOCATED, not that it fits VRAM without spilling, so the "may use system
        RAM" warning is right and ``max_context_length < context_length`` is legal.
        """
        actual_n_ctx = self._query_server_n_ctx()
        if not actual_n_ctx or actual_n_ctx <= 0:
            return
        slots = 1 if self._kv_cache_unified else self.effective_parallel_slots
        self._kv_cache_context_total = actual_n_ctx * slots
        effective_n_ctx = self._effective_context_length
        if not effective_n_ctx:
            self._effective_context_length = (
                min(actual_n_ctx, requested_n_ctx) if requested_n_ctx > 0 else actual_n_ctx
            )
            return
        if actual_n_ctx < effective_n_ctx:
            logger.warning(
                "llama-server allocated a smaller per-request context than "
                f"requested ({effective_n_ctx} -> {actual_n_ctx}; "
                "memory fit or --parallel slot split); clients must treat "
                f"{actual_n_ctx} as the real context window."
            )
            self._effective_context_length = actual_n_ctx
            return
        if requested_n_ctx > effective_n_ctx:
            confirmed_n_ctx = min(actual_n_ctx, requested_n_ctx)
            if confirmed_n_ctx > effective_n_ctx:
                logger.info(
                    "llama-server confirmed a larger per-request context from "
                    f"the explicit override ({effective_n_ctx} -> {confirmed_n_ctx})."
                )
                self._effective_context_length = confirmed_n_ctx

    @staticmethod
    def _parse_tool_calls_from_text(
        content: str,
        *,
        allow_incomplete: bool = True,
        enabled_tool_names: Optional[set] = None,
    ) -> list[dict]:
        """Wrapper around the shared parser; ``enabled_tool_names`` gates the markerless bare-JSON form."""
        return _shared_parse_tool_calls_from_text(
            content,
            allow_incomplete = allow_incomplete,
            enabled_tool_names = enabled_tool_names,
        )

    @staticmethod
    def _build_openai_messages(messages: list[dict], image_b64: Optional[str] = None) -> list[dict]:
        """Build OpenAI-format messages, optionally injecting an image_url part
        into the last user message for vision models. As-is if no image."""
        if not image_b64:
            return messages

        result = [msg.copy() for msg in messages]
        last_user_idx = None
        for i, msg in enumerate(result):
            if msg["role"] == "user":
                last_user_idx = i

        if last_user_idx is not None:
            text_content = result[last_user_idx].get("content", "")
            result[last_user_idx]["content"] = [
                {"type": "text", "text": text_content},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/png;base64,{image_b64}",
                    },
                },
            ]

        return result

    @contextlib.contextmanager
    def _open_stream(self, url: str, payload: dict, cancel_event):
        """Open a streaming POST to llama-server, retrying through prefill, and
        yield ``(response, first_token_deadline)`` once a 200 lands. Owns the
        httpx.Client + auth headers for the stream's lifetime; raises
        RuntimeError on a non-200. Shared scaffold for the streaming consumers,
        which differ only in how they parse the SSE body."""
        from core.inference.mcp_images import prepare_image_turn_boundaries

        if "messages" in payload:
            payload = {
                **payload,
                "messages": prepare_image_turn_boundaries(
                    payload["messages"],
                    getattr(self, "_chat_template_override", None)
                    or getattr(self, "_chat_template", None),
                ),
            }
        stream_timeout = httpx.Timeout(connect = 10, read = 0.5, write = 10, pool = 10)
        with httpx.Client(
            timeout = stream_timeout,
            limits = httpx.Limits(max_keepalive_connections = 0),
            trust_env = False,
            verify = _local_ssl_context(),
        ) as client:
            first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
            with self._stream_with_retry(
                client,
                url,
                payload,
                cancel_event,
                headers = self._auth_headers,
                first_token_deadline = first_token_deadline,
            ) as response:
                if response.status_code != 200:
                    error_body = response.read().decode()
                    raise RuntimeError(
                        f"llama-server returned {response.status_code}: {error_body}"
                    )
                yield response, first_token_deadline

    @staticmethod
    def _sse_event_payload(event: str) -> Optional[dict]:
        """Decode one complete SSE event's ``data:`` payload, or None."""
        payload_lines = [
            line[5:].lstrip() for line in event.splitlines() if line.startswith("data:")
        ]
        if not payload_lines:
            return None
        try:
            data = json.loads("\n".join(payload_lines))
        except (TypeError, json.JSONDecodeError):
            return None
        return data if isinstance(data, dict) else None

    @staticmethod
    def _sse_event_prefill_progress(event: str) -> Optional[float]:
        """Return the reported processed prompt tokens, if present."""
        data = LlamaCppBackend._sse_event_payload(event)
        if data is None:
            return None
        progress = data.get("prompt_progress")
        if not isinstance(progress, dict):
            return None
        try:
            return float(progress.get("processed"))
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _sse_event_has_generated_output(event: str) -> bool:
        """Return true when a complete SSE event carries model-generated output."""
        data = LlamaCppBackend._sse_event_payload(event)
        if data is None:
            return False
        return _llama_chunk_has_generated_output(data)

    @staticmethod
    def _iter_text_cancellable(
        response: "httpx.Response",
        cancel_event: Optional[threading.Event] = None,
        stall_timeout_s: float = _DEFAULT_STREAM_STALL_TIMEOUT_S,
        first_token_deadline: Optional[float] = None,
        post_first_chunk_read_timeout_s: Optional[float] = _DEFAULT_STREAM_STALL_TIMEOUT_S,
    ) -> Generator[str, None, None]:
        """Iterate a stream while polling cancel and stall timeouts."""
        text_iter = response.iter_text()
        if first_token_deadline is None:
            first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
        last_chunk_at: Optional[float] = None
        last_prefill_progress: Optional[float] = None
        prefill_sse_buffer = ""
        while True:
            if cancel_event is not None and cancel_event.is_set():
                response.close()
                return
            try:
                if last_chunk_at is None:
                    remaining_s = first_token_deadline - time.monotonic()
                    if remaining_s <= 0:
                        raise httpx.ReadTimeout("The model did not produce a first token in time.")
                    LlamaCppBackend._set_stream_read_timeout(response, remaining_s)
                chunk = next(text_iter)
                starts_output = last_chunk_at is not None
                if chunk and last_chunk_at is None:
                    prefill_sse_buffer += chunk
                    while match := re.search(r"(?:\r\n|\r|\n){2}", prefill_sse_buffer):
                        event = prefill_sse_buffer[: match.start()]
                        prefill_sse_buffer = prefill_sse_buffer[match.end() :]
                        if LlamaCppBackend._sse_event_has_generated_output(event):
                            starts_output = True
                            prefill_sse_buffer = ""
                            break
                        # Renew only on increasing progress so repeated events still time out.
                        processed = LlamaCppBackend._sse_event_prefill_progress(event)
                        if processed is not None and (
                            last_prefill_progress is None or processed > last_prefill_progress
                        ):
                            last_prefill_progress = processed
                            first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
                if chunk and starts_output:
                    if last_chunk_at is None and post_first_chunk_read_timeout_s is not None:
                        LlamaCppBackend._set_stream_read_timeout(
                            response,
                            post_first_chunk_read_timeout_s,
                        )
                    last_chunk_at = time.monotonic()
                yield chunk
            except StopIteration:
                return
            except httpx.ReadTimeout:
                now = time.monotonic()
                if last_chunk_at is None:
                    if now >= first_token_deadline:
                        raise
                elif now - last_chunk_at >= stall_timeout_s:
                    raise httpx.ReadTimeout("The model stopped producing tokens mid-response.")
                continue

    @staticmethod
    def _set_stream_read_timeout(response: "httpx.Response", read_timeout_s: float) -> None:
        """Lower only post-header stream reads; keep prefill timeout long."""
        try:
            timeout_ext = response.request.extensions.get("timeout")
            if isinstance(timeout_ext, dict):
                timeout_ext["read"] = read_timeout_s
        except Exception:
            logger.debug("Could not lower response read timeout", exc_info = True)

    @staticmethod
    def _shutdown_active_httpx_sockets(client: "httpx.Client") -> None:
        """Best-effort interrupt for a sync httpx read blocked in recv(), whether
        parked before headers (prefill) or mid-stream."""
        try:
            pool = getattr(getattr(client, "_transport", None), "_pool", None)
            connections = list(getattr(pool, "_connections", []) or [])
            for connection in connections:
                inner = getattr(connection, "_connection", None)
                stream = getattr(inner, "_network_stream", None)
                sock = getattr(stream, "_sock", None)
                if sock is None:
                    continue
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
                try:
                    sock.close()
                except OSError:
                    pass
        except Exception:
            logger.debug("Could not shutdown active httpx socket", exc_info = True)
        try:
            client.close()
        except Exception:
            logger.debug("Could not close httpx client", exc_info = True)

    @staticmethod
    def _install_cancel_aware_read(
        client: "httpx.Client",
        cancel_event: threading.Event,
        response: Optional["httpx.Response"] = None,
        poll_s: float = 0.2,
    ) -> None:
        """Wrap the httpcore stream so the reader interrupts its own blocked recv() on cancel.

        A cross-thread socket shutdown wakes a parked recv() on POSIX but not on
        Windows (Winsock), so read in short slices and poll cancel_event between them
        (plain or TLS); slice timeouts are swallowed so a slow-but-alive stream survives.
        httpcore snapshots request.extensions["timeout"]["read"] once at body start, so
        given ``response`` we re-read the live value per call to honor the post-first-token
        stall timeout instead of the long prefill timeout."""
        import httpcore

        def _live_read_timeout() -> Optional[float]:
            if response is None:
                return None
            try:
                ext = response.request.extensions.get("timeout")
                if isinstance(ext, dict):
                    value = ext.get("read")
                    if isinstance(value, (int, float)):
                        return float(value)
            except Exception:
                pass
            return None

        try:
            pool = getattr(getattr(client, "_transport", None), "_pool", None)
            for connection in list(getattr(pool, "_connections", []) or []):
                inner = getattr(connection, "_connection", None)
                stream = getattr(inner, "_network_stream", None)
                if stream is None or getattr(stream, "_unsloth_cancel_wrapped", False):
                    continue
                orig_read = stream.read

                def read(
                    max_bytes,
                    timeout = None,
                    _orig = orig_read,
                ):
                    live = _live_read_timeout()
                    effective = live if live is not None else timeout
                    deadline = None if effective is None else time.monotonic() + effective
                    while True:
                        if cancel_event.is_set():
                            raise httpcore.ReadError("stream cancelled by user")
                        if deadline is None:
                            step = poll_s
                        else:
                            remaining = deadline - time.monotonic()
                            if remaining <= 0:
                                raise httpcore.ReadTimeout("read operation timed out")
                            step = min(poll_s, remaining)
                        try:
                            return _orig(max_bytes, timeout = step)
                        except httpcore.ReadTimeout:
                            if deadline is not None and time.monotonic() >= deadline:
                                raise
                            continue

                stream.read = read
                stream._unsloth_cancel_wrapped = True
        except Exception:
            logger.debug("Could not install cancel-aware read", exc_info = True)

    @staticmethod
    @contextlib.contextmanager
    def _stream_with_retry(
        client: "httpx.Client",
        url: str,
        payload: dict,
        cancel_event: Optional[threading.Event] = None,
        headers: Optional[dict] = None,
        first_token_deadline: Optional[float] = None,
    ):
        """Open one streaming POST and let cancel interrupt prefill or reads."""
        if cancel_event is not None and cancel_event.is_set():
            raise _LlamaStreamCancelled

        _cancel_closed = threading.Event()
        _response_ref: list = [None]

        def _cancel_watcher():
            while not _cancel_closed.is_set():
                if cancel_event.wait(timeout = 0.3):
                    while not _cancel_closed.is_set():
                        r = _response_ref[0]
                        try:
                            # close() can't wake a blocked recv(); shut the socket down first.
                            LlamaCppBackend._shutdown_active_httpx_sockets(client)
                            if r is not None:
                                r.close()
                            return
                        except Exception as e:
                            logger.debug(f"Error closing request in cancel watcher: {e}")
                        _cancel_closed.wait(timeout = 0.1)
                    return

        watcher = None
        if cancel_event is not None:
            watcher = threading.Thread(target = _cancel_watcher, daemon = True, name = "prefill-cancel")
            watcher.start()

        try:
            if first_token_deadline is None:
                first_token_deadline = time.monotonic() + _DEFAULT_FIRST_TOKEN_TIMEOUT_S
            prefill_read_timeout = max(0.1, first_token_deadline - time.monotonic())
            prefill_timeout = httpx.Timeout(
                connect = 30,
                read = prefill_read_timeout,
                write = 10,
                pool = 10,
            )
            with client.stream(
                "POST",
                url,
                json = payload,
                timeout = prefill_timeout,
                headers = headers,
            ) as response:
                _response_ref[0] = response
                if cancel_event is not None:
                    # Reader polls cancel itself; Windows socket shutdown does not interrupt reads.
                    LlamaCppBackend._install_cancel_aware_read(client, cancel_event, response)
                if cancel_event is not None and cancel_event.is_set():
                    raise _LlamaStreamCancelled
                yield response
                return
        except (httpx.RequestError, RuntimeError):
            if cancel_event is not None and cancel_event.is_set():
                raise _LlamaStreamCancelled
            raise
        finally:
            _cancel_closed.set()

    def _server_socket_is_open(self, timeout_s: float = 0.15) -> bool:
        """True if anything still accepts on the server port.

        The listening socket dies with the process, so this tells a live server
        from a dead one without waiting for the child to become reapable.
        """
        port = self._port
        if not port:
            return False
        try:
            with socket.create_connection(("127.0.0.1", port), timeout = timeout_s):
                return True
        except OSError:
            return False

    def _respawn_if_dead(self) -> bool:
        """Relaunch the llama-server if its process has exited.

        A loaded chat model can be SIGKILL'd mid-session (usually GPU/RAM pressure
        from a training run on the same box), leaving a defunct process while
        ``is_loaded`` still reads True. Replay the last ``load_model`` call to
        recover, returning True once healthy. Serialised on ``_respawn_lock`` so
        many generations hitting the dead server trigger at most one reload.
        """
        # Read outside the lock so queued callers skip the grace wait for a replaced child.
        served_by = self._process
        with self._respawn_lock:
            proc = self._process
            if proc is None:
                return False
            if self._cancel_event.is_set():
                # unload_model sets this before it kills; don't aim the retry at it.
                return False
            if proc is not served_by:
                return self._healthy
            if proc.poll() is None:
                # Still serving: transient error, skip the grace wait.
                if self._server_socket_is_open():
                    return self._healthy
                # A closing server can beat its own exit status; wait briefly for it.
                deadline = time.monotonic() + _RESPAWN_REAP_GRACE_S
                while proc.poll() is None and time.monotonic() < deadline:
                    time.sleep(0.05)
            if proc.poll() is None:
                return self._healthy
            with self._mtp_runtime_fallback_lock:
                if self._mtp_runtime_fallback_in_progress:
                    # An MTP-free reload owns this; replaying old kwargs would abort it.
                    logger.info("Respawn skipped: an MTP-free reload is already recovering.")
                    return False
            with self._serial_load_lock:
                if self._process is not proc:
                    logger.info("Respawn skipped: a newer load is already active.")
                    return self._healthy
                # Snapshot under _lock: unload holds it, never _serial_load_lock.
                with self._lock:
                    if self._cancel_event.is_set():
                        logger.info("Respawn skipped: the model was unloaded.")
                        return False
                    intent = self._last_load_intent
                    if intent is None:
                        return False
                    epoch = self._unload_epoch
                    self._healthy = False
                logger.warning(
                    f"llama-server for '{self._model_identifier}' exited "
                    f"(code {proc.returncode}); respawning to recover the session"
                )
                try:
                    started = bool(self.load_model(intent))
                except Exception as exc:
                    logger.error(f"Failed to respawn llama-server: {exc}")
                    return False
                if started and self._unload_epoch != epoch:
                    # load_model cleared _cancel_event, so the epoch is the only unload evidence.
                    logger.info("Respawn undone: the model was unloaded during the reload.")
                    self.unload_model()
                    return False
                return started

    def _retire_device_lost_server(self, served_by) -> None:
        """Kill the llama-server that hit a lost GPU device, if it is still current (#11453).

        It survives VK_ERROR_DEVICE_LOST but fails every later request; a dead child is
        what _respawn_if_dead already recovers.
        """
        with self._respawn_lock:
            if (
                served_by is None
                or served_by is not self._process
                or served_by.poll() is not None
                or self._cancel_event.is_set()
            ):
                return
            # Else the MTP watchdog reads this kill as an MTP crash.
            self._stop_mtp_crash_watchdog()
            try:
                served_by.kill()
                served_by.wait(timeout = 10)
            except (OSError, subprocess.TimeoutExpired):
                pass
        try:
            logger.warning(
                f"llama-server for '{self._model_identifier}' lost its GPU device "
                "(the graphics driver reset it); restarted it. On Intel Arc with "
                "Vulkan, GGML_VK_DISABLE_COOPMAT=1 may avoid the reset."
            )
        except Exception:
            # The logger raises once stdout is closed; recovery must not.
            pass

    def _retire_device_lost_server_soon(self, served_by) -> None:
        """Retire after a device loss in the server log, for the passthrough routes.

        The grace lets a chat request that hit the same error retire and retry first.
        """

        def _retire():
            time.sleep(_DEVICE_LOST_LOG_GRACE_S)
            self._retire_device_lost_server(served_by)

        try:
            threading.Thread(target = _retire, daemon = True, name = "llama-device-lost").start()
        except RuntimeError:
            pass

    @contextlib.contextmanager
    def _open_chat_stream_with_respawn_retry(
        self,
        payload: dict,
        cancel_event,
        on_respawn: Optional[Callable[[], None]] = None,
    ):
        """Open a chat stream, respawning a dead llama-server once before streaming.

        Retry only when opening the response fails: once it is open a consumer may
        already have emitted content or tool events, so a replay could duplicate
        output and side effects. ``base_url`` is resolved per attempt because a
        respawn may pick a new port. The budget is one retry per model request, not
        per chat turn, so a long tool loop never discards a completed tool.

        A child dying after the accept but before the headers surfaces as
        ReadError/WriteError/RemoteProtocolError rather than ConnectError, and which
        one differs per OS. llama-server flushes its 200 at slot start, so that window
        is an upload still in flight or a request behind busy slots; a death during
        decode arrives with the response open and is not replayed. Timeouts are
        excluded: the server is slow, not dead, and a replay would spend the
        first-token budget twice.
        """
        for attempt in range(2):
            response_opened = False
            served_by = getattr(self, "_process", None)
            try:
                url = f"{self.base_url}/v1/chat/completions"
                with self._open_stream(url, payload, cancel_event) as opened:
                    response_opened = True
                    yield opened
                    return
            except RuntimeError as exc:
                if not _is_gpu_device_lost(exc):
                    raise
                # Retry only before the 200; once opened the consumer may have emitted output.
                self._retire_device_lost_server(served_by)
                if response_opened or attempt > 0 or not self._respawn_if_dead():
                    raise
                logger.warning(
                    "llama-server lost its GPU device; restarted it and retrying the generation"
                )
                if on_respawn is not None:
                    on_respawn()
                continue
            except (httpx.NetworkError, httpx.RemoteProtocolError) as exc:
                if response_opened:
                    raise
                if self._maybe_recover_from_mtp_crash(exc):
                    raise RuntimeError("Lost connection to llama-server") from exc
                if attempt == 0 and self._respawn_if_dead():
                    logger.warning(
                        "llama-server was unreachable; respawned it and retrying the generation"
                    )
                    if on_respawn is not None:
                        on_respawn()
                    continue
                raise

    @staticmethod
    def decode_slot_from_chunk(chunk) -> Optional[int]:
        """The llama-server slot a stream chunk was decoded on, None if it does not say.

        Only the final result carries ``__verbose``, and only when asked for.
        """
        if not isinstance(chunk, dict):
            return None
        verbose = chunk.get("__verbose")
        if not isinstance(verbose, dict):
            return None
        slot = verbose.get("id_slot")
        if type(slot) is not int or slot < 0:
            return None
        return slot

    def release_idle_chat_slot(self, base_url: str, slot: int) -> bool:
        """Erase one completed round's cached context, True once the engine says so.

        Declines unless the round decoded on this server, which a reload renumbers, and
        unless --slot-save-path is in play, which the endpoint requires. An erase aimed at
        a slot since handed to another request is deferred rather than dropped, so even a
        timeout can cost that chat its prefix.
        """
        if (
            not self._slot_save_dir
            or base_url != self.base_url
            or type(slot) is not int
            or slot < 0
        ):
            return False
        try:
            response = httpx.post(
                f"{base_url}/slots/{slot}",
                params = {"action": "erase"},
                headers = self._auth_headers,
                timeout = 2.0,
                trust_env = False,
            )
            response.raise_for_status()
            result = response.json()
            return (
                result.get("id_slot") == slot
                and type(result.get("n_erased")) is int
                and result["n_erased"] >= 0
            )
        except Exception:
            logger.debug("Approval cache reclamation failed; retaining reservation", exc_info = True)
            return False

    def generate_chat_completion(
        self,
        messages: list[dict],
        image_b64: Optional[str] = None,
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 20,
        min_p: float = 0.01,
        max_tokens: Optional[int] = None,
        repetition_penalty: float = 1.0,
        presence_penalty: float = 0.0,
        frequency_penalty: float = 0.0,
        logit_bias: Optional[dict] = None,
        stop: Optional[list[str]] = None,
        cancel_event: Optional[threading.Event] = None,
        enable_thinking: Optional[bool] = None,
        reasoning_effort: Optional[str] = None,
        preserve_thinking: Optional[bool] = None,
        continue_final_message: bool = False,
        seed: Optional[int] = None,
        promote_reasoning_only: bool = True,
        perf_callback: Optional[Callable[[dict], None]] = None,
        reasoning_provenance: Optional[dict] = None,
        context_overflow: Optional[str] = None,
        context_policy: Optional[str] = None,
        compaction_headroom_ratio: Optional[float] = None,
        thread_id: Optional[str] = None,
        tools_withheld: bool = False,
        thinking_budget_tokens: Optional[int] = None,
        _allow_respawn_retry: bool = True,
    ) -> Generator[Union[str, dict], None, None]:
        """
        Send a chat completion to llama-server and stream tokens back.

        Uses /v1/chat/completions -- llama-server applies the chat template
        and handles vision (multimodal image_url parts) natively.

        Yields cumulative text (matching InferenceBackend's convention).
        """
        if not self.is_loaded:
            raise RuntimeError("llama-server is not loaded")

        from core.inference.chat_template_helpers import (
            neutralize_control_markup_in_messages,
            trailing_assistant_resume_kind,
        )

        openai_messages = self._build_openai_messages(messages, image_b64)
        _resume_kind = (
            trailing_assistant_resume_kind(openai_messages) if continue_final_message else None
        )
        continue_final_message = _resume_kind is not None
        resumed_reasoning = (
            openai_messages[-1]["reasoning_content"] if _resume_kind == "reasoning_content" else ""
        )

        payload = {
            "messages": neutralize_control_markup_in_messages(
                openai_messages, None, self.markup_profile
            ),
            "stream": True,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
            "presence_penalty": presence_penalty,
            "frequency_penalty": frequency_penalty,
        }
        retry_messages = messages
        retry_image_b64 = image_b64
        retry_max_tokens = max_tokens
        retry_context_overflow = context_overflow
        retry_preflight_context_length = None
        payload["return_progress"] = True
        if _perf_callback_wants_timings(perf_callback):
            payload["timings_per_token"] = True
        if logit_bias:
            payload["logit_bias"] = logit_bias
        _reasoning_kw = self._request_reasoning_kwargs(
            enable_thinking, reasoning_effort, preserve_thinking
        )
        if _reasoning_kw is not None:
            payload["chat_template_kwargs"] = _reasoning_kw
        if thinking_budget_tokens is not None:
            payload["thinking_budget_tokens"] = thinking_budget_tokens
        if continue_final_message:
            # llama-server rejects both flags set true.
            payload["continue_final_message"] = True
            payload["add_generation_prompt"] = False
        payload["max_tokens"] = (
            max_tokens
            if max_tokens is not None
            else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
        )
        if context_overflow == "truncate_oldest" and self._effective_context_length:
            try:
                _before_fit = openai_messages
                # Same value for boundary read and fit, so they agree on epochs.
                _can_reset = _can_reset_epoch(
                    thread_id,
                    _backend_supports_tools(self),
                    tools_withheld = tools_withheld,
                )
                _sticky, _sticky_is_checkpoint = _sticky_compaction_state(
                    thread_id,
                    _before_fit,
                    context_policy = context_policy,
                    can_reset = _can_reset,
                    compaction_headroom_ratio = compaction_headroom_ratio,
                )
                openai_messages, truncation = _fit_with_instruction_pins(
                    openai_messages,
                    context_length = self._effective_context_length,
                    max_tokens = payload["max_tokens"],
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(
                            messages_without_unpriced_media(fitted), None, self.markup_profile
                        ),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        continue_final_message = continue_final_message,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    estimate_message = estimate_message_tokens_without_unpriced_media,
                    reserve_tokens = _conversation_recall_reserve(thread_id),
                    sticky_dropped = _sticky,
                    sticky_is_checkpoint = _sticky_is_checkpoint,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _can_reset,
                    recall_offered = False,
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                if truncation:
                    # Inline: no tools array here, and strict templates reject a lone tool role.
                    _recalled = _archive_and_recall(
                        openai_messages,
                        _before_fit,
                        branch_messages = _before_fit,
                        thread_id = thread_id,
                        style = "inline",
                        # Checkpoint mode recalls once; rolling recalls every turn that evicted.
                        force_recall = bool(truncation.get("checkpoint_started", True)),
                        recall_done = not truncation["fits"],
                        recall_budget_tokens = _retrieval_budget(
                            self._effective_context_length,
                            payload["max_tokens"],
                            truncation.get("prompt_tokens_after") or 0,
                        ),
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                messages_without_unpriced_media(fitted),
                                None,
                                self.markup_profile,
                            ),
                            None,
                            None,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = continue_final_message,
                        ),
                    )
                    openai_messages = _recalled["conversation"]
                    truncation = {**truncation, **_recalled["counts"]}
                if truncation and _records_boundary(truncation):
                    truncation = {
                        **truncation,
                        **_boundary_metadata(
                            openai_messages, _before_fit, compaction_headroom_ratio
                        ),
                    }
                payload["messages"] = neutralize_control_markup_in_messages(
                    openai_messages, None, self.markup_profile
                )
                # Reuse the fitted request; re-running preflight would duplicate the event.
                retry_messages = openai_messages
                retry_image_b64 = None
                retry_max_tokens = payload["max_tokens"]
                retry_context_overflow = None
                retry_preflight_context_length = self._effective_context_length
                # Report even when it does not fit: it carries the diagnosis for the client.
                if truncation:
                    yield {"type": "context_truncated", **truncation}
            except Exception as exc:
                logger.warning("Could not preflight the rolling context window: %s", exc)
        if stop:
            payload["stop"] = stop
        _apply_seeded_llama_request(payload, seed)
        payload["stream_options"] = {"include_usage": True}

        served_by = getattr(self, "_process", None)
        url = f"{self.base_url}/v1/chat/completions"
        cumulative = ""
        in_thinking = False
        _stream_done = False
        _metadata_usage = None
        _metadata_timings = None
        _metadata_finish_reason = None

        def _replay_on_replacement_server():
            context_overflow_ = retry_context_overflow
            max_tokens_ = retry_max_tokens
            if (
                retry_preflight_context_length is not None
                and retry_preflight_context_length != self._effective_context_length
            ):
                # Refit the compacted prompt against the replacement server's window;
                # any event now reports only additional evictions.
                context_overflow_ = context_overflow
                if max_tokens is None:
                    max_tokens_ = None
            yield from self.generate_chat_completion(
                retry_messages,
                image_b64 = retry_image_b64,
                temperature = temperature,
                top_p = top_p,
                top_k = top_k,
                min_p = min_p,
                max_tokens = max_tokens_,
                repetition_penalty = repetition_penalty,
                presence_penalty = presence_penalty,
                frequency_penalty = frequency_penalty,
                logit_bias = logit_bias,
                stop = stop,
                cancel_event = cancel_event,
                enable_thinking = enable_thinking,
                reasoning_effort = reasoning_effort,
                preserve_thinking = preserve_thinking,
                continue_final_message = continue_final_message,
                seed = seed,
                promote_reasoning_only = promote_reasoning_only,
                perf_callback = perf_callback,
                reasoning_provenance = reasoning_provenance,
                context_overflow = context_overflow_,
                context_policy = context_policy,
                compaction_headroom_ratio = compaction_headroom_ratio,
                # The retry refits for the replacement window and can evict more than
                # the first attempt did. Without the thread those extra turns are
                # archived nowhere and no reserve or boundary applies, on the one path
                # that deliberately compacts again.
                thread_id = thread_id,
                # The retry refits, so it must be told the same about this request's
                # tools as the first attempt was.
                tools_withheld = tools_withheld,
                thinking_budget_tokens = thinking_budget_tokens,
                _allow_respawn_retry = False,
            )

        try:
            with self._open_stream(url, payload, cancel_event) as (
                response,
                first_token_deadline,
            ):
                buffer = ""
                has_content_tokens = False
                # A literal `</think>` can appear in the answer.
                answer_text = ""
                reasoning_text = ""
                _prov_entry = None
                for raw_chunk in self._iter_text_cancellable(
                    response,
                    cancel_event,
                    first_token_deadline = first_token_deadline,
                ):
                    buffer += raw_chunk
                    while "\n" in buffer:
                        line, buffer = buffer.split("\n", 1)
                        line = line.strip()

                        if not line:
                            continue
                        if line == "data: [DONE]":
                            if in_thinking:
                                if has_content_tokens:
                                    cumulative += "</think>"
                                    _prov_entry = None
                                    yield cumulative
                                else:
                                    # Reasoning-only reply (e.g. Qwen3 always-think): show it as the
                                    # main response.
                                    cumulative = _finalize_reasoning_only_cumulative(
                                        cumulative,
                                        reasoning_text,
                                        _metadata_finish_reason,
                                        promote_reasoning_only,
                                        resumed_reasoning,
                                    )
                                    _prov_entry = None
                                    yield cumulative
                            _stream_done = True
                            break
                        if not line.startswith("data: "):
                            continue

                        try:
                            data = json.loads(line[6:])
                            _report_live_llama_timings(perf_callback, data)
                            # Diffusion frame from the shim: forward untouched, never into content.
                            if data.get("type") == "diffusion_frame":
                                yield data
                                continue
                            _chunk_timings = data.get("timings")
                            if _chunk_timings:
                                _metadata_timings = _chunk_timings
                            _chunk_usage = data.get("usage")
                            if _chunk_usage:
                                _metadata_usage = _chunk_usage
                            # Error chunks have no choices; raise so the failure is surfaced.
                            _stream_error = stream_error_from_chunk(data)
                            if _stream_error is not None:
                                raise _stream_error
                            choices = data.get("choices", [])
                            if choices:
                                delta = choices[0].get("delta", {})
                                _fr = choices[0].get("finish_reason")
                                if _fr:
                                    _metadata_finish_reason = _fr

                                reasoning = delta.get("reasoning_content", "")
                                if reasoning:
                                    reasoning_text += reasoning
                                    if not in_thinking:
                                        # A leading <think> opened here is genuine reasoning, unlike
                                        # literal tags.
                                        if reasoning_provenance is not None and not cumulative:
                                            reasoning_provenance["wrapped"] = (
                                                reasoning_provenance.get("wrapped", 0) + 1
                                            )
                                            _prov_entry = {"len": 0}
                                            reasoning_provenance.setdefault("wraps", []).append(
                                                _prov_entry
                                            )
                                        cumulative += "<think>"
                                        in_thinking = True
                                    cumulative += reasoning
                                    if _prov_entry is not None:
                                        _prov_entry["len"] += len(reasoning)
                                    yield cumulative

                                token = delta.get("content", "")
                                if token:
                                    has_content_tokens = True
                                    answer_text += token
                                    if in_thinking:
                                        cumulative += "</think>"
                                        in_thinking = False
                                        _prov_entry = None
                                    cumulative += token
                                    yield cumulative
                        except json.JSONDecodeError:
                            logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                    if _stream_done:
                        break
                _cut = _quote_cut_event(
                    reasoning_text,
                    answer_text,
                    _metadata_finish_reason,
                    promote_reasoning_only,
                )
                if _cut is not None:
                    yield _cut
                if _metadata_usage or _metadata_timings or _metadata_finish_reason:
                    _metadata_usage = _backfill_usage_from_timings(
                        _metadata_usage, _metadata_timings
                    )
                    yield {
                        "type": "metadata",
                        # Never None: consumers call usage.get(...).
                        "usage": _metadata_usage or {},
                        "timings": _metadata_timings,
                        "finish_reason": _metadata_finish_reason,
                    }

        except _LlamaStreamCancelled:
            return
        except httpx.ConnectError as e:
            # MTP+tensor crash: reload without MTP and fail. Else (likely OOM kill) respawn and retry once.
            if self._maybe_recover_from_mtp_crash(e):
                raise RuntimeError("Lost connection to llama-server")
            if _allow_respawn_retry and not cumulative and self._respawn_if_dead():
                logger.warning(
                    "llama-server was unreachable; respawned it and retrying the generation"
                )
                yield from _replay_on_replacement_server()
                return
            raise RuntimeError("Lost connection to llama-server")
        except Exception as e:
            if cancel_event is not None and cancel_event.is_set():
                return
            if _is_gpu_device_lost(e):
                self._retire_device_lost_server(served_by)
                if _allow_respawn_retry and not cumulative and self._respawn_if_dead():
                    logger.warning(
                        "llama-server lost its GPU device; restarted it and retrying the generation"
                    )
                    yield from _replay_on_replacement_server()
                    return
                raise
            # Died mid-generation: recover MTP, re-raise unchanged for this request.
            self._maybe_recover_from_mtp_crash(e)
            raise

    def generate_chat_completion_with_tools(
        self,
        messages: list[dict],
        tools: list[dict],
        replayed_image_parts: "tuple" = (),
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 20,
        min_p: float = 0.01,
        max_tokens: Optional[int] = None,
        repetition_penalty: float = 1.0,
        presence_penalty: float = 0.0,
        frequency_penalty: float = 0.0,
        logit_bias: Optional[dict] = None,
        stop: Optional[list[str]] = None,
        cancel_event: Optional[threading.Event] = None,
        enable_thinking: Optional[bool] = None,
        reasoning_effort: Optional[str] = None,
        preserve_thinking: Optional[bool] = None,
        continue_final_message: bool = False,
        max_tool_iterations: int = 25,
        auto_heal_tool_calls: bool = True,
        nudge_tool_calls: Optional[bool] = None,
        tool_call_timeout: int = 300,
        session_id: Optional[str] = None,
        thread_id: Optional[str] = None,
        rag_scope: Optional[dict] = None,
        seed: Optional[int] = None,
        disable_parallel_tool_use: bool = False,
        confirm_tool_calls: bool = False,
        bypass_permissions: bool = False,
        permission_mode: Optional[str] = None,
        promote_reasoning_only: bool = True,
        perf_callback: Optional[Callable[[dict], None]] = None,
        reasoning_provenance: Optional[dict] = None,
        context_overflow: Optional[str] = None,
        context_policy: Optional[str] = None,
        compaction_headroom_ratio: Optional[float] = None,
        tool_choice: Any = None,
        # Append new parameters only: no bare `*`, so inserting rebinds positional args.
        # MAY BLOCK waiting for KV room; called at the top of each round.
        on_conversation_grew: Optional[Callable[[list], None]] = None,
        on_decode_slot: Optional[Callable[[str, int], None]] = None,
        thinking_budget_tokens: Optional[int] = None,
        mcp_image = None,
        deduplicate_tool_calls: bool = True,
        instruction_anchor_ids = None,
        sandbox_level: Optional[str] = None,
    ) -> Generator[dict, None, None]:
        """
        Agentic loop: let the model call tools, execute them, and continue.

        permission_mode: "ask" confirms every call (with confirm_tool_calls),
        "auto" only pauses calls detected as potentially unsafe, "off" never
        pauses (sandbox stays on), "full" is the same as bypass_permissions.
        Unset/unknown behaves as "ask".

        Yields dicts:
          {"type": "status", "text": "Searching: ..."/"Reading: ..."}   -- tool status updates
          {"type": "content", "text": "token"}            -- streamed content tokens (cumulative)
          {"type": "reasoning", "text": "token"}          -- streamed reasoning tokens (cumulative)
        """
        from core.inference.tool_stream_exec import (
            accepts_kwarg,
            accepts_output_callback,
            search_images_kwargs,
            stream_tool_execution,
        )
        from core.inference.tools import (
            build_rag_autoinject,
            execute_tool,
            has_text_only_provisional_card,
            is_high_risk_tool_call,
            mcp_image_share,
            mcp_image_targets,
            never_needs_approval,
        )
        from core.inference.mcp_image import note_attached_image

        # 'full' and bypass_permissions are the same switch. Unknown falls back to 'ask'.
        from state.tool_policy import (
            account_tool_stream,
            needs_tool_confirmation,
            normalize_sandbox_level,
            normalize_tool_permissions,
            requires_os_isolation,
            runs_without_os_sandbox,
            tool_call_may_prompt,
        )

        permission_mode, bypass_permissions = normalize_tool_permissions(
            permission_mode, bypass_permissions
        )
        sandbox_level = normalize_sandbox_level(sandbox_level)
        stream_tool_execution = account_tool_stream(stream_tool_execution)

        if not self.is_loaded:
            raise RuntimeError("llama-server is not loaded")

        if mcp_image is not None:
            messages = note_attached_image(
                messages, mcp_image_targets(_gguf_active_tool_names(tools))
            )
        conversation = list(messages)
        _rolling_anchor_ids: set[int] = set(instruction_anchor_ids or ())
        # Recall once per request, or each refit stacks more recalled turns.
        _conversation_recall_done = False
        # Apply the sticky boundary once; refits run on already-fitted history.
        _sticky_boundary_applied = False
        # Estimator misses the tool catalogue and template framing; the offset corrects it.
        _prompt_token_offset: Optional[int] = None
        # Archive holds the whole DAG; recall needs the live branch.
        _request_branch: list[dict] = list(messages)
        # Accumulated so recall can return this run's own evicted tool results.
        _live_branch: list[dict] = list(messages)
        _live_branch_ids: set[int] = {id(message) for message in messages}

        def _extend_live_branch(current: list[dict]) -> list[dict]:
            for message in current:
                if id(message) not in _live_branch_ids:
                    _live_branch_ids.add(id(message))
                    _live_branch.append(message)
            return _live_branch

        for message in reversed(conversation):
            if message.get("role") == "user":
                _rolling_anchor_ids.add(id(message))
                break

        def _attach_internal_feedback_to_tool_result(feedback: str) -> bool:
            """Keep controller instructions inside the current tool exchange."""
            if not conversation or conversation[-1].get("role") != "tool":
                return False
            content = conversation[-1].get("content")
            if not isinstance(content, str):
                return False
            # Replace, not mutate: the dicts may be the caller's history.
            conversation[-1] = {**conversation[-1], "content": f"{content}\n\n{feedback}"}
            return True

        # Forced first-pass RAG; skipped only in ask mode, where retrieval would prompt.
        from core.inference.chat_template_helpers import (
            forced_tool_name,
            trailing_assistant_resume_kind,
            trailing_assistant_text,
        )

        initial_forced_name = forced_tool_name(tool_choice)
        if initial_forced_name and initial_forced_name not in _gguf_active_tool_names(tools):
            raise ValueError(
                f"Forced tool '{initial_forced_name}' is not enabled for this request."
            )

        # A resumed turn must keep the partial trailing; autoinject would move the boundary.
        _skip_autoinject = (
            tool_choice == "none"
            or (
                confirm_tool_calls
                and not bypass_permissions
                and permission_mode not in ("auto", "off")
            )
        ) or bool(
            continue_final_message and trailing_assistant_resume_kind(conversation) is not None
        )
        _auto = None if _skip_autoinject else build_rag_autoinject(conversation, rag_scope)
        if _auto:
            for _ev in _auto["events"]:
                yield _ev
            conversation.extend(_auto["messages"])
        _auto_satisfies_forced_choice = bool(_auto) and (
            tool_choice == "required" or forced_tool_name(tool_choice) == "search_knowledge_base"
        )

        _accumulated_completion_tokens = 0
        _accumulated_predicted_ms = 0.0
        _accumulated_predicted_n = 0
        _reasoning_started_at: Optional[float] = None
        _reasoning_summary_emitted = False

        # Built from the ORIGINAL tools so a spent one-shot still reads as a tool name.
        _enabled_names_gate = set(_gguf_active_tool_names(tools)) if tools else None
        # Same names as the strip gate, else a repeat is stripped but not drained.
        _detect_tools = list(tools or [])

        def _reasoning_summary_event(started_at: float) -> dict:
            return {
                "type": "reasoning_summary",
                "duration_ms": round((time.monotonic() - started_at) * 1000.0),
            }

        _enabled_tool_names = None

        def _gemma_lead_promotable(text: str) -> bool:
            # Reads _enabled_tool_names at call time: it is rebound each iteration.
            return leading_bare_gemma_call_is_promotable(text, _enabled_tool_names)

        def _strip_tool_markup(
            text: str,
            *,
            final: bool = False,
            force: bool = False,
        ) -> str:
            if not (auto_heal_tool_calls or force):
                return text
            # Shared parser-side strip covers every family; tool_healing's omits loop-only forms.
            return _shared_strip_tool_markup(
                text, final = final, enabled_tool_names = _enabled_names_gate
            )

        # Avoids quadratic rescans. Think blocks stay verbatim.
        _streaming_stripper = _StreamingMarkupStripper(_enabled_names_gate)

        _final_answer_stripper = _StreamingMarkupStripper(_enabled_names_gate, seg_final = False)

        def _strip_tool_markup_streaming(text: str, *, force: bool = False) -> str:
            if not (auto_heal_tool_calls or force):
                return text
            return _streaming_stripper.strip(text)

        def _build_metadata_event(usage, timings, finish_reason):
            """Final usage+timings metadata event for the given pass, merging its
            usage/timings with the running cross-iteration accumulators. None when
            there is nothing to report."""
            _fu = _backfill_usage_from_timings(usage, timings) or {}
            _fp = _fu.get("prompt_tokens", 0)
            _tc = _fu.get("completion_tokens", 0) + _accumulated_completion_tokens
            if not (usage or timings or _accumulated_completion_tokens or finish_reason):
                return None
            _mt = dict(timings) if timings else {}
            if _accumulated_predicted_ms or _accumulated_predicted_n:
                _mt["predicted_ms"] = _mt.get("predicted_ms", 0) + _accumulated_predicted_ms
                _mt["predicted_n"] = _mt.get("predicted_n", 0) + _accumulated_predicted_n
                if _mt["predicted_ms"] > 0:
                    _mt["predicted_per_second"] = _mt["predicted_n"] / (
                        _mt["predicted_ms"] / 1000.0
                    )
            _usage = {
                "prompt_tokens": _fp,
                "completion_tokens": _tc,
                "total_tokens": _fp + _tc,
            }
            # Earlier passes' completions are already inside _fp, so the context is _fp + this pass only.
            if _accumulated_completion_tokens:
                _usage["context_tokens"] = _fp + int(_fu.get("completion_tokens") or 0)
            # Preserve KV-cache hit details (cached_tokens) so the tool path
            # reports them like the standard non-tool path does, not always 0.
            if _fu.get("prompt_tokens_details"):
                _usage["prompt_tokens_details"] = _fu["prompt_tokens_details"]
            return {
                "type": "metadata",
                "usage": _usage,
                "timings": _mt,
                "finish_reason": finish_reason,
            }

        def _flush_reasoning_and_buffer():
            """Close a live-streamed <think> block (or emit the buffered reasoning
            as one block if it never streamed), then append the held
            content_buffer to the cumulative display text."""
            nonlocal cumulative_display, in_thinking, _prov_entry, _buffer_in_display
            if in_thinking:
                cumulative_display += "</think>"
                in_thinking = False
                _prov_entry = None
            elif reasoning_accum:
                if (
                    reasoning_provenance is not None
                    and not cumulative_display
                    and not _suppress_visible_output
                ):
                    reasoning_provenance["wrapped"] = reasoning_provenance.get("wrapped", 0) + 1
                    reasoning_provenance.setdefault("wraps", []).append(
                        {"len": len(reasoning_accum)}
                    )
                cumulative_display += "<think>" + reasoning_accum + "</think>"
            cumulative_display += content_buffer
            # Not cleared: callers measure len(content_buffer) right after.
            _buffer_in_display = True

        def _cancelled_hold_text() -> str:
            """Display text the guards are still holding, which a cancel would drop.

            Mirrors the safetensors loop: a completed blocked markerless object keeps the
            chain guard true while its suffix is empty, so the whole object sits in
            ``content_buffer`` as ordinary display text the parser will never promote, and
            returning on cancellation lost the reply outright. The final strip removes
            genuinely promotable markup, so an aborted real call contributes only prose."""
            if _suppress_visible_output:
                return ""
            held = cumulative_display + ("" if _buffer_in_display else content_buffer)
            if not held:
                return ""
            cleaned = _strip_tool_markup(held, final = True, force = True)
            return cleaned if len(cleaned) > len(_last_emitted) else ""

        def _close_streamed_think() -> bool:
            """Close a live-streamed <think> before a tool call drains, so
            consumers without a reasoning extractor (Anthropic) get a balanced
            block. Returns True when the caller should yield the result."""
            nonlocal cumulative_display, in_thinking, _last_emitted, _prov_entry
            if not in_thinking:
                return False
            cumulative_display += "</think>"
            in_thinking = False
            _prov_entry = None
            if len(cumulative_display) > len(_last_emitted) and not _suppress_visible_output:
                _last_emitted = cumulative_display
                return True
            return False

        def _looks_like_enabled_bare_json(text: str, enabled_tool_names: set) -> bool:
            """True when ``text`` opens with an ENABLED markerless bare-JSON call; an ordinary JSON answer returns False."""
            probe = strip_llama3_leading_sentinels(text.lstrip())
            if not (probe.startswith("{") and ('"name"' in probe or '"function"' in probe)):
                return False
            return strip_leading_bare_json_call(probe, enabled_tool_names) != probe

        # Sanitize at construction: structured tool_calls bypass the name gate.
        from core.inference.chat_template_helpers import (
            neutralize_tool_descriptions as _neutralize_tool_descriptions,
        )

        controller_tools = (
            []
            if tool_choice == "none"
            else _neutralize_tool_descriptions(tools, None, self.markup_profile)
        )
        tool_controller = ToolLoopController(
            tools = controller_tools,
            auto_heal_tool_calls = auto_heal_tool_calls,
            deduplicate_tool_calls = deduplicate_tool_calls,
            session_id = session_id,
            thread_id = thread_id,
        )

        def _tool_succeeded(tool_name: str) -> bool:
            key_prefix = f"{tool_name}:"
            return any(
                record.executed and not record.is_error and record.key.startswith(key_prefix)
                for record in tool_controller.history
            )

        _MAX_BUFFER_CHARS = 32
        _MAX_BARE_JSON_BUFFER = 16384
        _append_budget_exhausted_nudge = True
        _limit_notice_in_user_turn = False
        _kb_search_count = 0

        # Re-prompt once when the model states intent without calling a tool.
        _reprompt_count = 0
        _post_tool_reprompts = 0
        _last_reprompt_text = ""
        # Counts real tool turns so re-prompt slots don't extend the budget.
        _tool_iters_done = 0
        _forced_tool_call_pending = False
        # Turns cut off mid-thought: continue them in a fresh turn with thinking off.
        _length_continuations = 0
        _effective_enable_thinking = enable_thinking
        # An explicit effort wins over enable_thinking, so clear it too.
        _effective_reasoning_effort = reasoning_effort
        _caller_continue_final_message = continue_final_message
        _last_tool_result_key: list = [None]
        _identical_result_runs: list = [0]
        _starved_call: list = [False]

        _extra = _MAX_REPROMPTS + 1 if max_tool_iterations > 0 else 0
        from core.inference.chat_template_helpers import sweep_cache as _sweep_cache

        _markup_cache = _sweep_cache()

        def _evict_until_it_fits(
            candidate,
            tools,
            reasoning_kw,
            continue_flag = False,
            protect = None,
        ):
            """Drop older turns from a continuation candidate that is one eviction short.

            Only reached once the candidate has already been priced and found too large.
            The single-turn case the callers were written for genuinely has nothing to
            evict, but a multi-turn chat under `truncate_oldest` usually does, and
            refusing there ended the turn before the NEXT iteration's ordinary preflight
            could ever run -- so a recoverable continuation was abandoned.

            Deliberately the plain rolling fit with instruction pins, not the loop's full
            preflight: that one archives, recalls and moves this thread's sticky boundary,
            and none of that should happen a second time in the middle of one turn.
            Returns the evicted candidate, or None when there was nothing to evict.

            ``protect`` keeps the current turn intact while older history is evicted.
            """
            if context_overflow != "truncate_oldest" or not self._effective_context_length:
                return None
            try:
                _fitted, _truncation = _fit_with_instruction_pins(
                    list(candidate),
                    context_length = self._effective_context_length,
                    # Room the continuation needs, not the caller's cap (a small cap overstates room).
                    max_tokens = max(
                        int(max_tokens or 0), _reply_floor(self._effective_context_length)
                    ),
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(
                            messages_without_unpriced_media(fitted),
                            _markup_cache,
                            self.markup_profile,
                        ),
                        None,
                        tools,
                        strict = True,
                        chat_template_kwargs = reasoning_kw,
                        continue_final_message = continue_flag,
                    ),
                    estimate_message = estimate_message_tokens_without_unpriced_media,
                    anchor_ids = (_rolling_anchor_ids | protect) if protect else _rolling_anchor_ids,
                )
            except Exception:
                logger.debug("continuation eviction: fit failed", exc_info = True)
                return None
            if not _truncation or not _truncation.get("dropped_messages"):
                return None
            logger.info(
                "Continuation did not fit; evicted %s older message(s) to try to keep it",
                _truncation.get("dropped_messages"),
            )
            return _fitted

        def _loop_continuation_fits(
            candidate,
            tools,
            reasoning_kw,
            continue_flag = False,
        ) -> bool:
            """Whether the retry's own prompt still fits once the partial is in it.

            The final pass has the same guard. This path did not, and it is the one a
            request with tools enabled actually takes: a `length` stop that came from
            exhausting the window makes the retry prompt window-sized, and with a single
            user turn there is no older history to evict, so llama-server rejects it or
            leaves room for a stub. A count that cannot be taken is not a refusal.
            """
            if not self._effective_context_length:
                return True
            try:
                _tokens = self.count_chat_tokens(
                    neutralize_control_markup_in_messages(
                        messages_without_unpriced_media(candidate),
                        _markup_cache,
                        self.markup_profile,
                    ),
                    None,
                    tools,
                    strict = True,
                    chat_template_kwargs = reasoning_kw,
                    # continue_final_message renders differently; price the request actually sent.
                    continue_final_message = continue_flag,
                )
            except Exception:
                logger.debug("in-loop continuation: prompt count failed", exc_info = True)
                return True
            return _tokens + _reply_floor(self._effective_context_length) <= (
                self._effective_context_length
            )

        def _loop_budget_left(spent_this_attempt: int) -> "Optional[int]":
            """What remains of a cap the CALLER set, or None when they set none.

            The in-loop payload rebuilds `max_tokens` from the caller's value on every
            iteration, so without this a request capped at 100 tokens ran two more
            100-token generations after its own cap stopped the first.
            """
            if max_tokens is None:
                return None
            window = self._effective_context_length or 0
            if window and max_tokens >= window:
                return None
            return max(0, max_tokens - _accumulated_completion_tokens - spent_this_attempt)

        _forced_choice_resolved = _auto_satisfies_forced_choice
        # Continuations get a credit so they don't consume the caller's tool budget.
        # Holds the remaining output cap for the next iteration.
        _continuation_max_tokens: Optional[int] = None
        _continuation_credits = 0
        _MAX_CONTINUATION_CREDITS = _MAX_LENGTH_CONTINUATIONS * max(1, max_tool_iterations)
        iteration = -1
        # Cap is across the whole conversation, seeded with already promoted images.
        loop_mcp_image_parts: list = list(replayed_image_parts)
        while True:
            iteration += 1
            if on_conversation_grew is not None:
                try:
                    on_conversation_grew(conversation)
                except Exception:  # accounting must never break a run
                    logger.debug("tool loop recost failed", exc_info = True)
            if iteration >= max_tool_iterations + _extra + _continuation_credits:
                break
            if cancel_event is not None and cancel_event.is_set():
                return
            _turn_executed_real_tool = False
            _reasoning_cap_spent = False

            active_tools = tool_controller.active_tools()
            if not active_tools:
                _append_budget_exhausted_nudge = False
                break
            from core.inference.chat_template_helpers import (
                neutralize_tool_descriptions,
                reconciled_tool_choice,
            )

            # Drop unsafe-markup tools from execution too, not just from the prompt.
            safe_tools = neutralize_tool_descriptions(
                active_tools, _markup_cache, self.markup_profile
            )
            requested_choice = "auto" if tool_choice is None else tool_choice
            if _forced_choice_resolved and requested_choice not in ("auto", "none"):
                requested_choice = "auto"
            requested_choice = reconciled_tool_choice(requested_choice, tools, safe_tools) or "auto"
            forced_name = forced_tool_name(requested_choice)
            if forced_name:
                matching_tools = [
                    tool
                    for tool in safe_tools
                    if (tool.get("function") or {}).get("name") == forced_name
                ]
                if matching_tools:
                    safe_tools = matching_tools
                    requested_choice = "required"
            _enabled_tool_names = {
                (tool.get("function") or {}).get("name")
                for tool in safe_tools
                if (tool.get("function") or {}).get("name")
            }
            _tool_xml_signals = _SHARED_TOOL_XML_SIGNALS

            from core.inference.chat_template_helpers import (
                append_assistant_turn,
                neutralize_control_markup,
                neutralize_control_markup_in_messages,
            )

            _reasoning_kw = self._request_reasoning_kwargs(
                _effective_enable_thinking, _effective_reasoning_effort, preserve_thinking
            )
            # On a continuation only the remainder of the caller's cap; read before the payload.
            _iteration_max_tokens = (
                _continuation_max_tokens if _continuation_max_tokens is not None else max_tokens
            )
            _preflight_context_length = None
            _preflight_succeeded = False
            if context_overflow == "truncate_oldest" and self._effective_context_length:
                _preflight_context_length = self._effective_context_length
                try:
                    _before_fit = conversation
                    _iteration_can_reset = _can_reset_epoch(
                        thread_id,
                        _backend_supports_tools(self),
                        tools_withheld = _memory_tool_withheld(thread_id, tools),
                    )
                    _iteration_sticky, _iteration_sticky_is_checkpoint = (
                        (0, True)
                        if _sticky_boundary_applied
                        else _sticky_compaction_state(
                            thread_id,
                            _request_branch,
                            context_policy = context_policy,
                            can_reset = _iteration_can_reset,
                            compaction_headroom_ratio = compaction_headroom_ratio,
                        )
                    )
                    conversation, truncation = _fit_with_instruction_pins(
                        conversation,
                        context_length = self._effective_context_length,
                        max_tokens = _iteration_max_tokens,
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                messages_without_unpriced_media(fitted),
                                _markup_cache,
                                self.markup_profile,
                            ),
                            None,
                            safe_tools,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = bool(
                                continue_final_message
                                and trailing_assistant_resume_kind(fitted) is not None
                            ),
                            should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                        ),
                        estimate_message = estimate_message_tokens_without_unpriced_media,
                        anchor_ids = _rolling_anchor_ids,
                        keeps_boundary = _keeps_compaction_boundary(thread_id),
                        can_reset = _iteration_can_reset,
                        recall_offered = "search_conversation" in (_enabled_tool_names or ()),
                        reserve_tokens = _conversation_recall_reserve(thread_id),
                        sticky_dropped = _iteration_sticky,
                        sticky_is_checkpoint = _iteration_sticky_is_checkpoint,
                        **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                    )
                    _sticky_boundary_applied = True
                    if truncation and truncation.get("fits"):
                        _prompt_token_offset = int(
                            truncation.get("prompt_tokens_after") or 0
                        ) - estimate_messages_tokens_without_unpriced_media(conversation)
                    if truncation:
                        _recalled = _archive_and_recall(
                            conversation,
                            _before_fit,
                            branch_messages = _extend_live_branch(_before_fit),
                            thread_id = thread_id,
                            # Forge a tool exchange only when search_conversation is advertised.
                            style = (
                                "tool" if "search_conversation" in _enabled_tool_names else "inline"
                            ),
                            force_recall = bool(truncation.get("checkpoint_started", True)),
                            recall_done = _conversation_recall_done or not truncation["fits"],
                            recall_budget_tokens = _retrieval_budget(
                                self._effective_context_length,
                                _iteration_max_tokens,
                                truncation.get("prompt_tokens_after") or 0,
                                reply_returns = True,
                            ),
                            count_tokens = lambda fitted: self.count_chat_tokens(
                                neutralize_control_markup_in_messages(
                                    messages_without_unpriced_media(fitted),
                                    _markup_cache,
                                    self.markup_profile,
                                ),
                                None,
                                safe_tools,
                                strict = True,
                                chat_template_kwargs = _reasoning_kw,
                            ),
                        )
                        conversation = _recalled["conversation"]
                        truncation = {**truncation, **_recalled["counts"]}
                        if _recalled["recalled"]:
                            _conversation_recall_done = True
                            # Anchor exactly what the injection added, not the last two messages.
                            for _message in _recalled["anchored"]:
                                _rolling_anchor_ids.add(id(_message))
                            for _ev in _recalled["events"]:
                                yield _ev
                    if truncation and _records_boundary(truncation):
                        truncation = {
                            **truncation,
                            **_boundary_metadata(
                                conversation, _request_branch, compaction_headroom_ratio
                            ),
                        }
                    if truncation:
                        yield {"type": "context_truncated", **truncation}
                    _preflight_succeeded = True
                except Exception as exc:
                    logger.warning("Could not preflight the rolling context window: %s", exc)

            payload = {
                # Re-run each iteration: tool results may contain forged turns.
                "messages": neutralize_control_markup_in_messages(
                    conversation, _markup_cache, self.markup_profile
                ),
                "stream": True,
                "stream_options": {"include_usage": True},
                "temperature": temperature,
                "top_p": top_p,
                "top_k": top_k if top_k >= 0 else 0,
                "min_p": min_p,
                "repeat_penalty": repetition_penalty,
                "presence_penalty": presence_penalty,
                "frequency_penalty": frequency_penalty,
            }

            payload["return_progress"] = True
            if on_decode_slot is not None:
                payload["verbose"] = True
                payload["response_fields"] = ["id_slot"]
            if _perf_callback_wants_timings(perf_callback):
                payload["timings_per_token"] = True
            if logit_bias:
                payload["logit_bias"] = logit_bias
            # An empty list would still advertise tool use.
            if safe_tools:
                payload["tools"] = llama_grammar_tools(safe_tools)
                payload["tool_choice"] = requested_choice
            if _reasoning_kw is not None:
                payload["chat_template_kwargs"] = _reasoning_kw
            if thinking_budget_tokens is not None:
                payload["thinking_budget_tokens"] = thinking_budget_tokens
            _resume_kind = (
                trailing_assistant_resume_kind(conversation) if continue_final_message else None
            )
            if _resume_kind is not None:
                payload["continue_final_message"] = True
                payload["add_generation_prompt"] = False
            _resumed_reasoning = (
                conversation[-1]["reasoning_content"] if _resume_kind == "reasoning_content" else ""
            )
            payload["max_tokens"] = (
                max_tokens
                if max_tokens is not None
                else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
            )
            # A continuation spends the caller's output budget once, not per attempt.
            if _continuation_max_tokens is not None:
                payload["max_tokens"] = _continuation_max_tokens
                _continuation_max_tokens = None
            if stop:
                payload["stop"] = stop
            _apply_seeded_llama_request(payload, seed)

            _respawn_truncations: list[dict] = []

            def _refit_iteration_after_respawn() -> None:
                nonlocal conversation
                _before_respawn_fit = conversation
                if (
                    _preflight_context_length is None
                    or not self._effective_context_length
                    or (
                        _preflight_succeeded
                        and _preflight_context_length == self._effective_context_length
                    )
                ):
                    return
                if max_tokens is None:
                    payload["max_tokens"] = self._effective_context_length
                try:
                    conversation, truncation = _fit_with_instruction_pins(
                        conversation,
                        context_length = self._effective_context_length,
                        max_tokens = _iteration_max_tokens,
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                messages_without_unpriced_media(fitted),
                                _markup_cache,
                                self.markup_profile,
                            ),
                            None,
                            safe_tools,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                            continue_final_message = bool(
                                continue_final_message
                                and trailing_assistant_resume_kind(fitted) is not None
                            ),
                            should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                        ),
                        estimate_message = estimate_message_tokens_without_unpriced_media,
                        anchor_ids = _rolling_anchor_ids,
                        keeps_boundary = _keeps_compaction_boundary(thread_id),
                        can_reset = _can_reset_epoch(
                            thread_id,
                            _backend_supports_tools(self),
                            tools_withheld = _memory_tool_withheld(thread_id, tools),
                        ),
                        recall_offered = "search_conversation" in (_enabled_tool_names or ()),
                        **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                    )
                    # Record here: the reopened stream raises before forwarding sees the refusal.
                    from core.inference import context_refusal  # noqa: PLC0415

                    context_refusal.record_fit(truncation)
                    if truncation:
                        truncation.update(
                            _archive_and_recall(
                                conversation,
                                _before_respawn_fit,
                                thread_id = thread_id,
                                style = "inline",
                                recall_done = True,
                                branch_messages = _extend_live_branch(conversation),
                            )["counts"]
                        )
                    payload["messages"] = neutralize_control_markup_in_messages(
                        conversation, _markup_cache, self.markup_profile
                    )
                    if truncation:
                        if _records_boundary(truncation):
                            truncation.update(
                                _boundary_metadata(
                                    conversation, _request_branch, compaction_headroom_ratio
                                )
                            )
                        _respawn_truncations.append(truncation)
                except Exception as exc:
                    logger.warning("Could not refit rolling context after respawn: %s", exc)
                    raise

            try:
                # BUFFERING: hold content, check for tool signals
                # STREAMING: no tool, yield tokens; DRAINING: tool found, consume silently
                _S_BUFFERING = 0
                _S_STREAMING = 1
                _S_DRAINING = 2

                detect_state = _S_BUFFERING
                content_buffer = ""
                _buffer_in_display = False
                content_accum = ""
                reasoning_accum = ""
                _prov_entry = None
                _reasoning_started_at = None
                _reasoning_summary_emitted = False
                _deferred_reasoning_summary = None
                cumulative_display = ""
                _streaming_stripper.reset()
                in_thinking = False
                has_content_tokens = False
                tool_calls_acc = {}
                # index -> accumulator key, (index, call_id) after a fork
                tool_calls_open_key: dict[Any, Any] = {}
                tool_calls_synthetic_ids: set[Any] = set()
                has_structured_tc = False
                _iter_usage = None
                _iter_timings = None
                _iter_finish_reason = None
                _stream_done = False
                _last_emitted = ""
                provisional_started_tool_calls: dict[str, str] = {}
                resolved_provisional_tool_call_ids: set[str] = set()
                _suppress_visible_output = _forced_tool_call_pending
                arg_streamed_tool_call_ids: set[str] = set()
                # Provisional card uses the parser's first-call id ('call_0') so tool_start reconciles.
                _text_args_call_start = -1
                _text_args_streamed_upto = -1
                _text_args_id = ""
                _text_args_name = ""
                _confirm_gated_iteration = bool(confirm_tool_calls) and not bypass_permissions

                # Compact when the prompt eats the reply room, not only when it doesn't fit. Never refuses.
                if self._effective_context_length and conversation:
                    _reply_target = prompt_budget(
                        self._effective_context_length, _iteration_max_tokens
                    )
                    if (
                        estimate_messages_tokens_dense(
                            messages_without_unpriced_media(conversation)
                        )
                        > 0.7 * _reply_target
                    ):
                        try:
                            _prompt_now = self.count_chat_tokens(
                                neutralize_control_markup_in_messages(
                                    messages_without_unpriced_media(conversation),
                                    _markup_cache,
                                    self.markup_profile,
                                ),
                                None,
                                safe_tools,
                                strict = True,
                                chat_template_kwargs = _reasoning_kw,
                            )
                        except Exception:
                            logger.debug("reply-room fit: prompt count failed", exc_info = True)
                            _prompt_now = None
                        if _prompt_now is not None and _prompt_now > _reply_target:
                            _roomy, _n_roomy = compact_completed_tool_arguments(
                                conversation, protect_last = 1
                            )
                            if _n_roomy:
                                conversation[:] = _roomy
                                payload["messages"] = neutralize_control_markup_in_messages(
                                    conversation, _markup_cache, self.markup_profile
                                )
                                logger.info(
                                    "Compacted %d completed tool call(s) for reply room: "
                                    "prompt was %d tokens against a %d-token budget",
                                    _n_roomy,
                                    _prompt_now,
                                    _reply_target,
                                )

                with self._open_chat_stream_with_respawn_retry(
                    payload,
                    cancel_event,
                    on_respawn = _refit_iteration_after_respawn,
                ) as (
                    response,
                    first_token_deadline,
                ):
                    for truncation in _respawn_truncations:
                        yield {"type": "context_truncated", **truncation}
                    raw_buf = ""
                    for raw_chunk in self._iter_text_cancellable(
                        response,
                        cancel_event,
                        first_token_deadline = first_token_deadline,
                    ):
                        raw_buf += raw_chunk
                        while "\n" in raw_buf:
                            line, raw_buf = raw_buf.split("\n", 1)
                            line = line.strip()

                            if not line:
                                continue
                            if line == "data: [DONE]":
                                if detect_state == _S_STREAMING and in_thinking:
                                    if has_content_tokens:
                                        cumulative_display += "</think>"
                                        _prov_entry = None
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": _strip_tool_markup(
                                                    cumulative_display,
                                                    final = True,
                                                ),
                                            }
                                    else:
                                        cumulative_display = _finalize_reasoning_only_cumulative(
                                            cumulative_display,
                                            reasoning_accum,
                                            _iter_finish_reason,
                                            promote_reasoning_only,
                                            _resumed_reasoning,
                                        )
                                        _prov_entry = None
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": cumulative_display,
                                            }
                                _stream_done = True
                                break
                            if not line.startswith("data: "):
                                continue

                            try:
                                chunk_data = json.loads(line[6:])
                                if on_decode_slot is not None:
                                    slot = self.decode_slot_from_chunk(chunk_data)
                                    if slot is not None:
                                        on_decode_slot(self.base_url, slot)

                                _report_live_llama_timings(perf_callback, chunk_data)
                                _ct = chunk_data.get("timings")
                                if _ct:
                                    _iter_timings = _ct
                                _cu = chunk_data.get("usage")
                                if _cu:
                                    _iter_usage = _cu

                                # Error chunks have no choices; don't drop them.
                                _stream_error = stream_error_from_chunk(chunk_data)
                                if _stream_error is not None:
                                    raise _stream_error
                                choices = chunk_data.get("choices", [])
                                if not choices:
                                    continue

                                delta = choices[0].get("delta", {})
                                _fr = choices[0].get("finish_reason")
                                if _fr:
                                    _iter_finish_reason = _fr

                                tc_deltas = delta.get("tool_calls")
                                if tc_deltas:
                                    has_structured_tc = True
                                    detect_state = _S_DRAINING
                                    if _close_streamed_think():
                                        yield {"type": "content", "text": cumulative_display}
                                    for tc_d in tc_deltas:
                                        idx = tc_d.get("index", 0)
                                        tc_id = tc_d.get("id")
                                        # A reused index with a new call forks its own slot.
                                        acc_key = tool_calls_open_key.get(idx, idx)
                                        if isinstance(tc_id, str) and tc_id:
                                            open_id = tool_calls_acc.get(acc_key, {}).get("id")
                                            # A synthetic placeholder is not a rival call.
                                            if (
                                                open_id
                                                and acc_key not in tool_calls_synthetic_ids
                                                and open_id != tc_id
                                            ):
                                                first_id = tool_calls_acc.get(idx, {}).get("id")
                                                acc_key = idx if first_id == tc_id else (idx, tc_id)
                                        tool_calls_open_key[idx] = acc_key
                                        if acc_key not in tool_calls_acc:
                                            tool_calls_acc[acc_key] = {
                                                "id": tc_id or f"call_{idx}",
                                                "type": "function",
                                                "function": {
                                                    "name": "",
                                                    "arguments": "",
                                                },
                                            }
                                            if not tc_id:
                                                tool_calls_synthetic_ids.add(acc_key)
                                        elif tc_id:
                                            tool_calls_acc[acc_key]["id"] = tc_id
                                            tool_calls_synthetic_ids.discard(acc_key)
                                        func = tc_d.get("function", {})
                                        if func.get("name"):
                                            tool_calls_acc[acc_key]["function"]["name"] += func[
                                                "name"
                                            ]
                                        if func.get("arguments"):
                                            tool_calls_acc[acc_key]["function"]["arguments"] += (
                                                func["arguments"]
                                            )
                                        current_name = tool_calls_acc[acc_key]["function"].get(
                                            "name", ""
                                        )
                                        fallback_id = f"call_{idx}"
                                        current_id = tool_calls_acc[acc_key].get("id", fallback_id)
                                        is_first_accumulated_call = (
                                            next(iter(tool_calls_acc)) == acc_key
                                        )
                                        already_started = (
                                            current_id in provisional_started_tool_calls
                                        )
                                        has_real_id = bool(current_id) and current_id != fallback_id
                                        _is_completed_one_shot = (
                                            current_name == "render_html"
                                            and _tool_succeeded("render_html")
                                        )
                                        _one_shot_already_provisional = (
                                            current_name == "render_html"
                                            and "render_html"
                                            in provisional_started_tool_calls.values()
                                        )
                                        # Later parallel cards only reconcile when parallel use is enabled.
                                        # In auto mode an always-safe tool (render_html) never
                                        # prompts, so it must stream its early card too; mirror
                                        # that here instead of gating on the raw confirm flag.
                                        _confirm_gated = (
                                            tool_call_may_prompt(
                                                confirm_tool_calls = bool(confirm_tool_calls),
                                                bypass_permissions = bypass_permissions,
                                                permission_mode = permission_mode,
                                                name = current_name,
                                                sandbox_level = sandbox_level,
                                            )
                                            # A text-preview card still streams while gated;
                                            # hiding it blanks the chat.
                                            and not has_text_only_provisional_card(current_name)
                                        )
                                        # Keep small-argument tools on the normal path.
                                        _args_len = len(
                                            tool_calls_acc[acc_key]["function"].get("arguments", "")
                                        )
                                        _payload_is_large = (
                                            current_name == "render_html"
                                            or _args_len >= _PROVISIONAL_ARGS_MIN_CHARS
                                        )
                                        if (
                                            current_name
                                            and (
                                                is_first_accumulated_call
                                                or not disable_parallel_tool_use
                                            )
                                            and has_real_id
                                            and not already_started
                                            and not _is_completed_one_shot
                                            and not _one_shot_already_provisional
                                            and not _confirm_gated
                                            and _payload_is_large
                                            and any(
                                                (tool.get("function") or {}).get("name")
                                                == current_name
                                                for tool in safe_tools
                                            )
                                        ):
                                            provisional_started_tool_calls[current_id] = (
                                                current_name
                                            )
                                            yield {
                                                "type": "tool_start",
                                                "tool_name": current_name,
                                                "tool_call_id": current_id,
                                                "arguments": {},
                                                "provenance": provisional_tool_provenance(
                                                    current_name
                                                ),
                                            }
                                        if current_id in provisional_started_tool_calls:
                                            if current_id not in arg_streamed_tool_call_ids:
                                                arg_streamed_tool_call_ids.add(current_id)
                                                _args_backlog = tool_calls_acc[acc_key][
                                                    "function"
                                                ].get("arguments", "")
                                                if _args_backlog:
                                                    yield {
                                                        "type": "tool_args",
                                                        "tool_call_id": current_id,
                                                        "tool_name": current_name,
                                                        "text": _args_backlog,
                                                    }
                                            elif func.get("arguments"):
                                                yield {
                                                    "type": "tool_args",
                                                    "tool_call_id": current_id,
                                                    "tool_name": current_name,
                                                    "text": func["arguments"],
                                                }
                                    continue

                                # Reasoning streams live except while DRAINING.
                                reasoning = delta.get("reasoning_content", "")
                                if reasoning:
                                    if _reasoning_started_at is None:
                                        _reasoning_started_at = time.monotonic()
                                    reasoning_accum += reasoning
                                    if detect_state != _S_DRAINING:
                                        if not in_thinking:
                                            # Suppressed iterations emit no content, so don't record
                                            # their wraps.
                                            if (
                                                reasoning_provenance is not None
                                                and not cumulative_display
                                                and not _suppress_visible_output
                                            ):
                                                reasoning_provenance["wrapped"] = (
                                                    reasoning_provenance.get("wrapped", 0) + 1
                                                )
                                                _prov_entry = {"len": 0}
                                                reasoning_provenance.setdefault("wraps", []).append(
                                                    _prov_entry
                                                )
                                            cumulative_display += "<think>"
                                            in_thinking = True
                                        cumulative_display += reasoning
                                        if _prov_entry is not None:
                                            _prov_entry["len"] += len(reasoning)
                                        if not _suppress_visible_output:
                                            yield {
                                                "type": "content",
                                                "text": cumulative_display,
                                            }

                                token = delta.get("content", "")
                                if token:
                                    if (
                                        _reasoning_started_at is not None
                                        and not _reasoning_summary_emitted
                                    ):
                                        _reasoning_summary_emitted = True
                                        _summary = _reasoning_summary_event(_reasoning_started_at)
                                        if _suppress_visible_output:
                                            _deferred_reasoning_summary = _summary
                                        else:
                                            yield _summary
                                    has_content_tokens = True
                                    content_accum += token

                                    if detect_state == _S_DRAINING:
                                        # Stream the drained TEXT call to a provisional card, gated
                                        # on name sniff and size.
                                        if not has_structured_tc and _text_args_call_start >= 0:
                                            if not _text_args_id:
                                                _call_text = content_accum[_text_args_call_start:]
                                                _sniffed = _sniff_text_tool_name(
                                                    _call_text, _enabled_tool_names
                                                )
                                                if (
                                                    _sniffed
                                                    and not (
                                                        _confirm_gated_iteration
                                                        and (
                                                            permission_mode != "off"
                                                            or tool_call_may_prompt(
                                                                confirm_tool_calls = True,
                                                                bypass_permissions = False,
                                                                permission_mode = "off",
                                                                name = _sniffed,
                                                                sandbox_level = sandbox_level,
                                                            )
                                                        )
                                                        and not has_text_only_provisional_card(
                                                            _sniffed
                                                        )
                                                    )
                                                    and (
                                                        _sniffed == "render_html"
                                                        or len(_call_text)
                                                        >= _PROVISIONAL_ARGS_MIN_CHARS
                                                    )
                                                ):
                                                    _text_args_id = "call_0"
                                                    _text_args_name = _sniffed
                                                    if (
                                                        _text_args_id
                                                        not in provisional_started_tool_calls
                                                    ):
                                                        provisional_started_tool_calls[
                                                            _text_args_id
                                                        ] = _sniffed
                                                        yield {
                                                            "type": "tool_start",
                                                            "tool_name": _sniffed,
                                                            "tool_call_id": _text_args_id,
                                                            "arguments": {},
                                                            "provenance": provisional_tool_provenance(
                                                                _sniffed
                                                            ),
                                                        }
                                                    yield {
                                                        "type": "tool_args",
                                                        "tool_call_id": _text_args_id,
                                                        "tool_name": _sniffed,
                                                        "text": _call_text,
                                                    }
                                                    _text_args_streamed_upto = len(content_accum)
                                            elif len(content_accum) > _text_args_streamed_upto:
                                                yield {
                                                    "type": "tool_args",
                                                    "tool_call_id": _text_args_id,
                                                    "tool_name": _text_args_name,
                                                    "text": content_accum[
                                                        _text_args_streamed_upto:
                                                    ],
                                                }
                                                _text_args_streamed_upto = len(content_accum)

                                    elif detect_state == _S_STREAMING:
                                        if in_thinking:
                                            cumulative_display += "</think>"
                                            in_thinking = False
                                            _prov_entry = None
                                        cumulative_display += token
                                        cleaned = _strip_tool_markup_streaming(cumulative_display)
                                        # Hold a trailing bare tool name until [ARGS] arrives.
                                        _hold = _held_rehearsal_tail_len(cleaned, _detect_tools)
                                        _emit = (
                                            cleaned[: len(cleaned) - _hold] if _hold else cleaned
                                        )
                                        if len(_emit) > len(_last_emitted):
                                            _last_emitted = _emit
                                            if not _suppress_visible_output:
                                                yield {
                                                    "type": "content",
                                                    "text": _emit,
                                                }

                                    elif detect_state == _S_BUFFERING:
                                        content_buffer += token
                                        stripped_buf = content_buffer.lstrip()
                                        if not stripped_buf:
                                            continue

                                        is_prefix = False
                                        is_match = False
                                        for sig in _tool_xml_signals:
                                            if stripped_buf.startswith(sig):
                                                is_match = True
                                                break
                                            if sig.startswith(stripped_buf):
                                                is_prefix = True
                                                break
                                            if sig == "[ARGS]":
                                                if (
                                                    _gguf_rehearsal_signal_pos(
                                                        stripped_buf, _detect_tools
                                                    )
                                                    >= 0
                                                ):
                                                    is_match = True
                                                    break
                                            elif sig.startswith("[") and sig in stripped_buf:
                                                is_match = True
                                                break

                                        is_rehearsal_prefix = False
                                        if (
                                            not is_match
                                            and not is_prefix
                                            and _is_rehearsal_prefix(stripped_buf, _detect_tools)
                                        ):
                                            is_prefix = True
                                            is_rehearsal_prefix = True

                                        # Signal-less call shapes: Llama-3.2 bare JSON and Gemma call:NAME{...}.
                                        _hold_buffer = False
                                        _drain_silently = False
                                        if not is_match and not is_prefix:
                                            _bare = strip_llama3_leading_sentinels(stripped_buf)
                                            if _bare.startswith("{"):
                                                if _balanced_brace_end(_bare, 0) is None:
                                                    if len(stripped_buf) < _MAX_BARE_JSON_BUFFER:
                                                        _hold_buffer = True
                                                    elif _looks_like_enabled_bare_json(
                                                        _bare, _enabled_tool_names
                                                    ):
                                                        _drain_silently = True
                                                elif self._parse_tool_calls_from_text(
                                                    content_buffer,
                                                    allow_incomplete = auto_heal_tool_calls,
                                                    enabled_tool_names = _enabled_tool_names,
                                                ):
                                                    _drain_silently = True
                                                elif blocked_bare_json_chain_may_continue(
                                                    content_buffer, _enabled_tool_names
                                                ):
                                                    if len(stripped_buf) < _MAX_BARE_JSON_BUFFER:
                                                        _hold_buffer = True
                                                    else:
                                                        # Fail closed rather than expose text a later peer
                                                        # could make executable.
                                                        _drain_silently = True
                                            elif (
                                                "call:".startswith(stripped_buf)
                                                or _GEMMA_BARE_TC_PREFIX_RE.match(stripped_buf)
                                                is not None
                                                or _gemma_lead_promotable(stripped_buf)
                                                or blocked_gemma_chain_may_continue(
                                                    stripped_buf, _enabled_tool_names
                                                )
                                            ):
                                                if _gemma_lead_promotable(stripped_buf):
                                                    _drain_silently = True
                                                elif blocked_gemma_chain_may_continue(
                                                    stripped_buf, _enabled_tool_names
                                                ):
                                                    # A promotable peer behind a blocked call must not
                                                    # stream first.
                                                    if self._parse_tool_calls_from_text(
                                                        content_buffer,
                                                        allow_incomplete = auto_heal_tool_calls,
                                                        enabled_tool_names = _enabled_tool_names,
                                                    ):
                                                        _drain_silently = True
                                                    elif len(stripped_buf) < _MAX_BARE_JSON_BUFFER:
                                                        _hold_buffer = True
                                                    else:
                                                        _drain_silently = True
                                                elif len(stripped_buf) < _MAX_BUFFER_CHARS:
                                                    _hold_buffer = True

                                        if _drain_silently:
                                            detect_state = _S_DRAINING
                                            _text_args_call_start = len(content_accum) - len(
                                                content_buffer
                                            )
                                            if _close_streamed_think():
                                                yield {
                                                    "type": "content",
                                                    "text": cumulative_display,
                                                }
                                        elif is_match:
                                            # Final strip: the buffer holds the whole call, a
                                            # streaming strip would leak markup.
                                            _flush_reasoning_and_buffer()
                                            cleaned = _strip_tool_markup(
                                                cumulative_display,
                                                final = True,
                                                force = True,
                                            )
                                            if len(cleaned) > len(_last_emitted):
                                                _last_emitted = cleaned
                                                if not _suppress_visible_output:
                                                    yield {
                                                        "type": "content",
                                                        "text": cleaned,
                                                    }
                                            detect_state = _S_DRAINING
                                            _text_args_call_start = len(content_accum) - len(
                                                content_buffer
                                            )
                                        elif _hold_buffer or (
                                            is_prefix
                                            and (
                                                is_rehearsal_prefix
                                                or len(stripped_buf) < _MAX_BUFFER_CHARS
                                            )
                                        ):
                                            # Rehearsal prefix is self-bounded; the cap must not cut
                                            # long MCP names.
                                            pass
                                        else:
                                            detect_state = _S_STREAMING
                                            _flush_reasoning_and_buffer()
                                            cleaned = _strip_tool_markup(
                                                cumulative_display,
                                            )
                                            _hold = _held_rehearsal_tail_len(cleaned, _detect_tools)
                                            _emit = (
                                                cleaned[: len(cleaned) - _hold]
                                                if _hold
                                                else cleaned
                                            )
                                            if len(_emit) > len(_last_emitted):
                                                _last_emitted = _emit
                                                if not _suppress_visible_output:
                                                    yield {
                                                        "type": "content",
                                                        "text": _emit,
                                                    }

                            except json.JSONDecodeError:
                                logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                        if _stream_done:
                            break

                if detect_state == _S_BUFFERING:
                    stripped_buf = content_buffer.lstrip()
                    # Bare JSON has no XML signal; route to DRAINING or it is flushed raw.
                    _bare_eos = strip_llama3_leading_sentinels(stripped_buf)
                    _is_bare_tc = bool(active_tools) and _looks_like_enabled_bare_json(
                        _bare_eos, _enabled_tool_names
                    )
                    if stripped_buf and _gguf_has_genuine_tool_signal(
                        stripped_buf, _tool_xml_signals, _detect_tools
                    ):
                        detect_state = _S_DRAINING
                    elif _is_bare_tc:
                        detect_state = _S_DRAINING
                    elif content_accum or reasoning_accum:
                        detect_state = _S_STREAMING
                        if content_buffer:
                            _flush_reasoning_and_buffer()
                            if not _suppress_visible_output:
                                yield {
                                    "type": "content",
                                    "text": _strip_tool_markup(
                                        cumulative_display,
                                        final = True,
                                    ),
                                }
                        elif reasoning_accum and not has_content_tokens:
                            # Reasoning-only reply: show as main response, like the no-tool path.
                            if _reasoning_started_at is not None and not _reasoning_summary_emitted:
                                _reasoning_summary_emitted = True
                                _summary = _reasoning_summary_event(_reasoning_started_at)
                                if _suppress_visible_output:
                                    _deferred_reasoning_summary = _summary
                                else:
                                    yield _summary
                            cumulative_display = _finalize_reasoning_only_cumulative(
                                cumulative_display,
                                reasoning_accum,
                                _iter_finish_reason,
                                promote_reasoning_only,
                                _resumed_reasoning,
                            )
                            _prov_entry = None
                            if not _suppress_visible_output:
                                yield {
                                    "type": "content",
                                    "text": cumulative_display,
                                }
                    else:
                        # A leading `{` is an ordinary JSON answer; other partial markup is dropped.
                        _held = strip_llama3_leading_sentinels(content_buffer.lstrip())
                        if _held.startswith("{") and not _suppress_visible_output:
                            yield {"type": "content", "text": _held}
                        return

                if detect_state == _S_STREAMING:
                    # Safety net: re-parse unconditionally; bare-JSON and Gemma calls have no XML signal.
                    _safety_tc = self._parse_tool_calls_from_text(
                        content_accum,
                        allow_incomplete = auto_heal_tool_calls,
                        enabled_tool_names = _enabled_tool_names,
                    )
                    if not _safety_tc:
                        # Classify only what the user sees.
                        _visible_raw = content_accum.strip()
                        _visible = (
                            _strip_tool_markup(content_accum, final = True).strip()
                            if _visible_raw
                            else ""
                        )
                        _reasoning = reasoning_accum.strip()
                        # Magistral-style bracketed reasoning is stripped whole; fall back to raw.
                        _stripped = _visible or _reasoning or _visible_raw
                        _visible_answer = _text_outside_think(_visible).strip()
                        # On the Anthropic path reasoning stays a thinking block, unseen.
                        _reasoning_shown = (
                            not has_content_tokens
                            and promote_reasoning_only
                            and _iter_finish_reason != "length"
                        )
                        _artifact_text = (
                            _visible_answer
                            if _visible_answer
                            else (_reasoning if _reasoning_shown else "")
                        )
                        _intent_text = _visible_answer if _visible_answer else _stripped

                        # Answer cut by the window: continue it via continue_final_message so it
                        # resumes mid-token.
                        _partial_answer = content_accum.strip()
                        if (
                            _iter_finish_reason == "length"
                            and _partial_answer
                            and not tool_calls_acc
                            and _length_continuations < _MAX_LENGTH_CONTINUATIONS
                        ):
                            # Refuse to continue repetitive output, or the echo is stitched into the answer.
                            if is_repetition_dominated(_partial_answer):
                                logger.info(
                                    "Truncated answer is repetition-dominated (%d chars); "
                                    "keeping it as-is rather than continuing an echo",
                                    len(_partial_answer),
                                )
                            else:
                                _length_continuations += 1
                                logger.info(
                                    "Answer cut off at %d chars; continuing %d/%d",
                                    len(_partial_answer),
                                    _length_continuations,
                                    _MAX_LENGTH_CONTINUATIONS,
                                )
                                # Candidate first: an unservable retry must not spend conversation or usage.
                                _cand_c = list(conversation)
                                append_assistant_turn(
                                    _cand_c,
                                    # Unstripped, so the replayed prefix matches the streamed text exactly.
                                    {"role": "assistant", "content": content_accum},
                                    continue_final_message = True,
                                )
                                _fu_c = (
                                    _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                                )
                                # A `length` stop spent the whole allowance; charge that when usage is missing.
                                _spent_c = _fu_c.get("completion_tokens", 0) or int(
                                    payload.get("max_tokens") or 0
                                )
                                _cap_left_c = _loop_budget_left(_spent_c)
                                _fits_c = _cap_left_c != 0 and _loop_continuation_fits(
                                    _cand_c, safe_tools, _reasoning_kw, True
                                )
                                if _cap_left_c != 0 and not _fits_c:
                                    _evicted_c = _evict_until_it_fits(
                                        _cand_c, safe_tools, _reasoning_kw, True
                                    )
                                    if _evicted_c is not None and _loop_continuation_fits(
                                        _evicted_c, safe_tools, _reasoning_kw, True
                                    ):
                                        _cand_c = _evicted_c
                                        _fits_c = True
                                if _cap_left_c == 0 or not _fits_c:
                                    logger.info(
                                        "Not continuing the answer: %s",
                                        "the caller's output cap is spent"
                                        if _cap_left_c == 0
                                        else "the retry prompt would not be served",
                                    )
                                    _length_continuations -= 1
                                else:
                                    conversation[:] = _cand_c
                                    continue_final_message = True
                                    if _cap_left_c is not None:
                                        _continuation_max_tokens = _cap_left_c
                                    _accumulated_completion_tokens += _fu_c.get(
                                        "completion_tokens", 0
                                    )
                                    _it_c = _iter_timings or {}
                                    _accumulated_predicted_ms += _it_c.get("predicted_ms", 0)
                                    _accumulated_predicted_n += _it_c.get("predicted_n", 0)
                                    if _continuation_credits < _MAX_CONTINUATION_CREDITS:
                                        _continuation_credits += 1
                                    yield {"type": "status", "text": ""}
                                    yield {
                                        "type": "status",
                                        "text": _CONTINUE_TRUNCATED_ANSWER_STATUS,
                                    }
                                    continue

                        # Ahead of the re-prompt, which only handles SHORT responses.
                        if (
                            _iter_finish_reason == "length"
                            and not content_accum.strip()
                            and reasoning_accum.strip()
                            and _length_continuations < _MAX_LENGTH_CONTINUATIONS
                        ):
                            _length_continuations += 1
                            # Thinking off, or the retry fails the same way.
                            _effective_enable_thinking = False
                            _effective_reasoning_effort = None
                            logger.info(
                                "Turn ended inside its reasoning (%d chars, finish_reason "
                                "length); continuing %d/%d with thinking off",
                                len(reasoning_accum),
                                _length_continuations,
                                _MAX_LENGTH_CONTINUATIONS,
                            )
                            # Check fit and cap: the recovery request must not be rejected.
                            _cand_l = list(conversation)
                            append_assistant_turn(
                                _cand_l,
                                {
                                    "role": "assistant",
                                    "content": _unfinished_thought_progress(
                                        _resumed_reasoning + reasoning_accum
                                    ),
                                },
                                continue_final_message = continue_final_message,
                            )
                            if _resumed_reasoning:
                                _cand_l[-1].pop("reasoning_content", None)
                            _cand_l.append(
                                {
                                    "role": "user",
                                    "content": _continue_after_length_message(),
                                }
                            )
                            _fu_l = _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                            _spent_l = _fu_l.get("completion_tokens", 0) or int(
                                payload.get("max_tokens") or 0
                            )
                            _cap_left_l = _loop_budget_left(_spent_l)
                            # Recompute kwargs with thinking off so admission prices the real request.
                            _off_kw_l = self._request_reasoning_kwargs(
                                False, None, preserve_thinking
                            )
                            _fits_l = _cap_left_l != 0 and _loop_continuation_fits(
                                _cand_l, safe_tools, _off_kw_l
                            )
                            if _cap_left_l != 0 and not _fits_l:
                                # Try eviction: refusing here ends the turn.
                                _evicted_l = _evict_until_it_fits(_cand_l, safe_tools, _off_kw_l)
                                if _evicted_l is not None and _loop_continuation_fits(
                                    _evicted_l, safe_tools, _off_kw_l
                                ):
                                    _cand_l = _evicted_l
                                    _fits_l = True
                            if _cap_left_l == 0 or not _fits_l:
                                logger.info(
                                    "Not continuing the thought: %s",
                                    "the caller's output cap is spent"
                                    if _cap_left_l == 0
                                    else "the retry prompt would not be served",
                                )
                                # Record whether Max Tokens or the window ran out, so the message
                                # names the right lever.
                                _reasoning_cap_spent = _cap_left_l == 0
                                _length_continuations -= 1
                                _effective_enable_thinking = enable_thinking
                                _effective_reasoning_effort = reasoning_effort
                            else:
                                conversation[:] = _cand_l
                                if _cap_left_l is not None:
                                    _continuation_max_tokens = _cap_left_l
                                _accumulated_completion_tokens += _fu_l.get("completion_tokens", 0)
                                _it_l = _iter_timings or {}
                                _accumulated_predicted_ms += _it_l.get("predicted_ms", 0)
                                _accumulated_predicted_n += _it_l.get("predicted_n", 0)
                                # Blank status first so the route resets its text cursor.
                                if _continuation_credits < _MAX_CONTINUATION_CREDITS:
                                    _continuation_credits += 1
                                yield {"type": "status", "text": ""}
                                yield {"type": "status", "text": _CONTINUE_AFTER_LENGTH_STATUS}
                                continue

                        if (
                            _iter_finish_reason == "length"
                            and not content_accum.strip()
                            and reasoning_accum.strip()
                        ):
                            # Allowance spent: say so rather than return an empty message.
                            logger.info(
                                "Reasoning exhausted the window %d times; giving up with "
                                "an explanation",
                                _length_continuations,
                            )
                            # Re-read the cap: the last attempt may have exhausted Max Tokens.
                            _fu_g = _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                            _spent_g = _fu_g.get("completion_tokens", 0) or int(
                                payload.get("max_tokens") or 0
                            )
                            yield {"type": "status", "text": ""}
                            yield {
                                "type": "content",
                                "text": (
                                    _reasoning_cap_spent_message(max_tokens)
                                    if _reasoning_cap_spent or _loop_budget_left(_spent_g) == 0
                                    else _thinking_exhausted_message(self._effective_context_length)
                                ),
                            }
                            _meta = _build_metadata_event(
                                _iter_usage, _iter_timings, _iter_finish_reason
                            )
                            if _meta is not None:
                                yield _meta
                            return

                        _render_html_already_done_intent = _tool_succeeded(
                            "render_html"
                        ) and re.search(
                            r"(?i)\brender[_\s-]?html\b",
                            _stripped,
                        )
                        # Post-tool stall gets one nudge (retries re-run tools). _auto counts RAG autoinject.
                        _already_acted = bool(_auto) or any(
                            record.executed for record in tool_controller.history
                        )
                        if _already_acted:
                            _reprompt_used, _reprompt_cap = _post_tool_reprompts, 1
                        else:
                            _reprompt_used, _reprompt_cap = _reprompt_count, _MAX_REPROMPTS
                        if (
                            auto_heal_tool_calls
                            and _nudge_enabled(nudge_tool_calls)
                            and active_tools
                            and not _render_html_already_done_intent
                            and _reprompt_used < _reprompt_cap
                            and not _is_reprompt_repeat(_stripped, _last_reprompt_text)
                            # _stripped is what gets replayed; intent text may be a short tail.
                            and len(_stripped) < _REPROMPT_MAX_CHARS
                            and _is_short_intent_without_action(_intent_text)
                            and not (_artifact_text and _has_answer_artifact(_artifact_text))
                        ):
                            _reprompt_count += 1
                            if _already_acted:
                                _post_tool_reprompts += 1
                            _last_reprompt_text = _stripped
                            logger.info(
                                f"Re-prompt {_reprompt_used + 1}/{_reprompt_cap}: "
                                f"model responded without calling tools "
                                f"({len(_stripped)} chars)"
                            )
                            # Merge into a resumed partial to keep role alternation.
                            append_assistant_turn(
                                conversation,
                                {"role": "assistant", "content": _stripped},
                                continue_final_message = continue_final_message,
                            )
                            available_tool_names = [
                                (tool.get("function") or {}).get("name")
                                for tool in active_tools
                                if isinstance(tool, dict) and isinstance(tool.get("function"), dict)
                            ]
                            available_tool_names = [name for name in available_tool_names if name]
                            tool_hint = " or ".join(available_tool_names) or "an available tool"
                            _forced_tool_call_pending = True
                            conversation.append(
                                {
                                    "role": "user",
                                    "content": _reprompt_to_act_message(tool_hint),
                                }
                            )
                            _fu_r = _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                            _accumulated_completion_tokens += _fu_r.get("completion_tokens", 0)
                            _it_r = _iter_timings or {}
                            _accumulated_predicted_ms += _it_r.get("predicted_ms", 0)
                            _accumulated_predicted_n += _it_r.get("predicted_n", 0)
                            # Blank first (the route resets its cursor only on empty status).
                            yield {"type": "status", "text": ""}
                            yield {"type": "status", "text": _NUDGE_TOOL_CALLS_STATUS}
                            continue

                        if _forced_tool_call_pending:
                            _forced_tool_call_pending = False
                            if not _should_suppress_forced_no_tool_output(
                                _stripped,
                                _last_reprompt_text,
                            ):
                                if cumulative_display:
                                    forced_visible_text = _strip_tool_markup(
                                        cumulative_display,
                                        final = True,
                                    )
                                elif content_accum:
                                    forced_visible_text = _strip_tool_markup(
                                        content_accum,
                                        final = True,
                                    )
                                else:
                                    forced_visible_text = reasoning_accum
                                if forced_visible_text:
                                    yield {
                                        "type": "content",
                                        "text": forced_visible_text,
                                    }
                                    if _deferred_reasoning_summary is not None:
                                        yield _deferred_reasoning_summary
                        elif not _suppress_visible_output:
                            _final_clean = _strip_tool_markup_streaming(cumulative_display)
                            if len(_final_clean) > len(_last_emitted):
                                yield {"type": "content", "text": _final_clean}

                        yield {"type": "status", "text": ""}
                        _cut = _quote_cut_event(
                            reasoning_accum,
                            _visible,
                            _iter_finish_reason,
                            promote_reasoning_only,
                        )
                        if _cut is not None:
                            yield _cut
                        _meta = _build_metadata_event(
                            _iter_usage, _iter_timings, _iter_finish_reason
                        )
                        if _meta is not None:
                            yield _meta
                        return

                    tool_calls = _safety_tc
                    content_text = _strip_tool_markup(
                        content_accum,
                        final = True,
                        force = True,
                    )
                    logger.info(
                        f"Safety net: parsed {len(tool_calls)} tool call(s) from streamed content"
                    )
                else:
                    tool_calls = None
                    content_text = content_accum
                    if has_structured_tc:
                        # Drop incomplete fragments. First-seen order so forked calls run last.
                        tool_calls = [
                            call
                            for call in tool_calls_acc.values()
                            if (call.get("function", {}).get("name", "").strip())
                        ] or None
                    if not tool_calls:
                        # Unconditional: bare-JSON / Gemma calls carry no XML signal.
                        tool_calls = self._parse_tool_calls_from_text(
                            content_accum,
                            allow_incomplete = auto_heal_tool_calls,
                            enabled_tool_names = _enabled_tool_names,
                        )
                    if tool_calls and not has_structured_tc:
                        content_text = _strip_tool_markup(
                            content_text,
                            final = True,
                            force = True,
                        )
                        # Also drop a leading bare-JSON call so it isn't replayed as text.
                        content_text = strip_leading_bare_json_call(
                            content_text, _enabled_tool_names
                        )
                    if tool_calls:
                        logger.info(
                            f"Parsed {len(tool_calls)} tool call(s) from "
                            f"{'structured delta' if has_structured_tc else 'content text'}"
                        )
                    if not tool_calls:
                        # False positive: close provisional cards or they spin forever.
                        for _pid, _pname in provisional_started_tool_calls.items():
                            if _pid not in resolved_provisional_tool_call_ids:
                                resolved_provisional_tool_call_ids.add(_pid)
                                yield {
                                    "type": "tool_end",
                                    "tool_name": _pname,
                                    "tool_call_id": _pid,
                                    "result": "",
                                    "provenance": provisional_tool_provenance(_pname),
                                }
                        yield {"type": "status", "text": ""}
                        if content_accum:
                            content_accum = _strip_tool_markup(content_accum, final = True)
                        # With Auto-Heal on, drop a truncated ENABLED-tool JSON fragment; off keeps it.
                        if content_accum and active_tools and auto_heal_tool_calls:
                            content_accum = strip_leading_bare_json_call(
                                content_accum, _enabled_tool_names
                            )
                        if content_accum:
                            yield {"type": "content", "text": content_accum}
                        _meta = _build_metadata_event(
                            _iter_usage, _iter_timings, _iter_finish_reason
                        )
                        if _meta is not None:
                            yield _meta
                        return

                # Progress made: reset stall counters and restore thinking.
                _length_continuations = 0
                _effective_enable_thinking = enable_thinking
                _effective_reasoning_effort = reasoning_effort
                # Captured before the reset: later records must merge into a resumed partial.
                _merge_into_partial = continue_final_message
                continue_final_message = _caller_continue_final_message
                _accumulated_completion_tokens += (
                    _backfill_usage_from_timings(_iter_usage, _iter_timings) or {}
                ).get("completion_tokens", 0)
                _it = _iter_timings or {}
                _accumulated_predicted_ms += _it.get("predicted_ms", 0)
                _accumulated_predicted_n += _it.get("predicted_n", 0)

                # Dedupe and cap TEXTUAL fallback calls (see _MAX_TOOL_CALLS_PER_TURN).
                _over_cap: list = []
                _limit_notice_in_user_turn = False
                if tool_calls and not has_structured_tc and len(tool_calls) > 1:
                    _seen_keys: set = set()
                    _last_workspace_key = None
                    # One rerun per piece of new work, so read/edit loops cannot fill the cap.
                    _novel_kept = 0
                    _novel_at_last_keep: dict = {}
                    _deduped: list = []
                    if not deduplicate_tool_calls:
                        _deduped = tool_calls[:_MAX_TOOL_CALLS_PER_TURN]
                        _over_cap = tool_calls[_MAX_TOOL_CALLS_PER_TURN:]
                    for _tc in tool_calls if deduplicate_tool_calls else ():
                        _fn = _tc.get("function", {}) or {}
                        _key = (_fn.get("name", ""), str(_fn.get("arguments", "")))
                        if _fn.get("name") in _WORKSPACE_TOOLS:
                            if _key == _last_workspace_key:
                                continue
                            if _key in _seen_keys:
                                if _novel_kept <= _novel_at_last_keep.get(_key, 0):
                                    continue
                            elif _fn.get("name") not in _WORKSPACE_READ_TOOLS:
                                _novel_kept += 1
                            _novel_at_last_keep[_key] = _novel_kept
                            _last_workspace_key = _key
                        elif _key in _seen_keys:
                            continue
                        _seen_keys.add(_key)
                        if len(_deduped) < _MAX_TOOL_CALLS_PER_TURN:
                            _deduped.append(_tc)
                        else:
                            _over_cap.append(_tc)
                    if len(_deduped) + len(_over_cap) != len(tool_calls):
                        logger.info(
                            "GGUF textual fallback: collapsed %d repeated tool call(s) "
                            "in one turn to %d",
                            len(tool_calls),
                            len(_deduped) + len(_over_cap),
                        )
                    if _over_cap:
                        logger.info(
                            "GGUF textual fallback: skipped %d tool call(s) over the "
                            "per-turn limit of %d",
                            len(_over_cap),
                            _MAX_TOOL_CALLS_PER_TURN,
                        )
                    tool_calls = _deduped

                # Truncate before building assistant_msg so extra calls never execute.
                if disable_parallel_tool_use and tool_calls and len(tool_calls) > 1:
                    tool_calls = tool_calls[:1]
                    _over_cap = []

                assistant_msg: dict = {"role": "assistant", "content": content_text}
                if reasoning_accum.strip():
                    assistant_msg["reasoning_content"] = reasoning_accum
                assistant_appended = False
                # Flush no-op feedback after the batch so later parallel calls aren't dropped.
                deferred_noop_msgs: list = []
                deferred_noop_tools: set = set()
                batch_mcp_images: list = []
                batch_conversation_start = len(conversation)

                # Reuse the text-path card id ('call_0') for a Mistral-style call to avoid duplicates.
                _text_provisional_id = _text_args_id if not has_structured_tc else ""

                for _call_index, tc in enumerate(tool_calls or []):
                    func = tc.get("function", {})
                    tool_name = func.get("name", "")
                    if (
                        _text_provisional_id
                        and _text_provisional_id in provisional_started_tool_calls
                        and _text_provisional_id not in resolved_provisional_tool_call_ids
                        and tc.get("id") not in provisional_started_tool_calls
                        and provisional_started_tool_calls[_text_provisional_id] == tool_name
                    ):
                        tc = {**tc, "id": _text_provisional_id}
                    provisional_match = tc.get("id") in provisional_started_tool_calls
                    decision = tool_controller.prepare_call(
                        tc,
                        forced = _forced_tool_call_pending,
                        provisional = provisional_match,
                        allowed_tool_names = {forced_name} if forced_name else None,
                    )
                    image_share = None
                    if decision.should_execute and mcp_image is not None:
                        image_share = mcp_image_share(
                            decision.tool_name, decision.arguments, mcp_image
                        )
                        if image_share is not None:
                            decision = tool_controller.reprepare_call(
                                decision,
                                forced = _forced_tool_call_pending,
                                provisional = provisional_match,
                                allowed_tool_names = {forced_name} if forced_name else None,
                            )

                    if not decision.should_execute:
                        if provisional_match:
                            # Close the provisional card when the call becomes an internal no-op.
                            resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                            yield {
                                "type": "tool_end",
                                "tool_name": decision.tool_name,
                                "tool_call_id": decision.tool_call_id,
                                "result": "",
                                "provenance": decision.provenance,
                            }
                        completion = tool_controller.record_noop(decision)
                        deferred_noop_msgs.append(completion.model_message())
                        deferred_noop_tools.add(decision.tool_name)
                        if _forced_tool_call_pending:
                            _forced_tool_call_pending = False
                        logger.info(
                            "Suppressed local GGUF tool call as internal no-op: "
                            f"action={decision.action} tool={decision.tool_name}"
                        )
                        continue

                    if not assistant_appended:
                        assistant_msg["tool_calls"] = [decision.as_assistant_tool_call()]
                        append_assistant_turn(
                            conversation,
                            assistant_msg,
                            continue_final_message = _merge_into_partial,
                        )
                        assistant_appended = True
                    else:
                        assistant_msg.setdefault("tool_calls", []).append(
                            decision.as_assistant_tool_call()
                        )

                    # Bypass wins. 'auto' pauses high-risk calls; 'off' only unsandboxed python/terminal.
                    needs_confirm = needs_tool_confirmation(
                        confirm_tool_calls = bool(confirm_tool_calls),
                        bypass_permissions = bypass_permissions,
                        permission_mode = permission_mode,
                        name = decision.tool_name,
                        arguments = decision.arguments,
                        is_high_risk = is_high_risk_tool_call,
                        never_needs = never_needs_approval,
                        sandbox_level = sandbox_level,
                    )
                    # Sending the user's image always asks, whatever the permission mode.
                    needs_confirm = needs_confirm or image_share is not None
                    strict_isolation = requires_os_isolation(
                        confirm_tool_calls = bool(confirm_tool_calls),
                        bypass_permissions = bypass_permissions,
                        permission_mode = permission_mode,
                        name = decision.tool_name,
                        arguments = decision.arguments,
                        prompted = needs_confirm,
                        is_high_risk = is_high_risk_tool_call,
                        sandbox_level = sandbox_level,
                    )
                    approval_id = new_approval_id() if needs_confirm else ""
                    decision_slot = (
                        begin_tool_decision(session_id, approval_id) if needs_confirm else None
                    )
                    start_event = decision.tool_start_event()
                    start_event["approval_id"] = approval_id
                    start_event["awaiting_confirmation"] = needs_confirm
                    if image_share is not None:
                        start_event["image_disclosure"] = image_share["disclosure"]

                    try:
                        yield {
                            "type": "status",
                            "text": (
                                awaiting_approval_status(decision.tool_name)
                                if needs_confirm
                                else decision.status_text
                            ),
                        }
                        yield start_event

                        _decision = (
                            wait_tool_decision(
                                decision_slot,
                                approval_id,
                                cancel_event = cancel_event,
                            )
                            if decision_slot is not None
                            else None
                        )
                        # Read before decision_slot is dropped in the deny branch.
                        _decision_reason = decision_reason(decision_slot)
                        if _decision is not None and _decision != "deny":
                            yield {"type": "status", "text": decision.status_text}
                        if _decision == "deny":
                            decision_slot = None
                            _forced_choice_resolved = True
                            resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                            _denied_text = (
                                TOOL_APPROVAL_EXPIRED_MESSAGE
                                if _decision_reason == DECISION_EXPIRED
                                else TOOL_REJECTED_MESSAGE
                            )
                            yield {
                                "type": "tool_end",
                                "tool_name": decision.tool_name,
                                "tool_call_id": decision.tool_call_id,
                                "result": _denied_text,
                                "provenance": decision.provenance,
                            }
                            denied_message = {
                                "role": "tool",
                                "name": decision.tool_name,
                                "content": _denied_text,
                            }
                            if decision.tool_call_id:
                                denied_message["tool_call_id"] = decision.tool_call_id
                            conversation.append(denied_message)
                            # The denial renders the refused arguments, so compact them or the
                            # context overflows.
                            if decision.tool_call_id:
                                conversation[:] = compact_refused_tool_arguments(
                                    conversation, decision.tool_call_id
                                )
                                # Rebuilt, not mutated: rebind the handle or later calls land on a stale object.
                                for _dmsg in reversed(conversation):
                                    if _dmsg.get("role") != "assistant":
                                        continue
                                    if any(
                                        (_tc or {}).get("id") == decision.tool_call_id
                                        for _tc in (_dmsg.get("tool_calls") or [])
                                    ):
                                        assistant_msg = _dmsg
                                        break
                            if _forced_tool_call_pending:
                                _forced_tool_call_pending = False
                            continue
                        decision_slot = None
                    finally:
                        if decision_slot is not None:
                            abort_tool_decision(decision_slot, approval_id)

                    # The prompt may already not fit with this call's own arguments; compact history,
                    # then refuse, before the tool runs and writes to disk.
                    _unservable_text: Optional[str] = None
                    _compact_after_execution = False
                    _compacted_turn_tokens: Optional[int] = None
                    if self._effective_context_length:
                        _room_target = prompt_budget(
                            self._effective_context_length, _iteration_max_tokens
                        )
                        # Cheap conservative estimate decides whether to do an exact count (base64
                        # ~1 char/token).
                        if (
                            estimate_messages_tokens_conservative(
                                messages_without_unpriced_media(conversation)
                            )
                            > 0.7 * _room_target
                        ):
                            # Templates render tool_calls only once a tool reply follows, so add an
                            # empty stand-in.
                            _probe_message: dict = {
                                "role": "tool",
                                "name": decision.tool_name,
                                "content": "",
                            }
                            if decision.tool_call_id:
                                _probe_message["tool_call_id"] = decision.tool_call_id
                            _compacted_calls = 0
                            for _attempt in range(2):
                                try:
                                    _turn_tokens = self.count_chat_tokens(
                                        neutralize_control_markup_in_messages(
                                            messages_without_unpriced_media(
                                                [*conversation, _probe_message]
                                            ),
                                            _markup_cache,
                                            self.markup_profile,
                                        ),
                                        None,
                                        safe_tools,
                                        strict = True,
                                        chat_template_kwargs = _reasoning_kw,
                                    )
                                except Exception:
                                    # Count failed: run it and let llama-server decide.
                                    logger.debug(
                                        "pre-execution fit: prompt count failed",
                                        exc_info = True,
                                    )
                                    break
                                if turn_is_servable(
                                    self._effective_context_length, max_tokens, _turn_tokens
                                ):
                                    break
                                if _attempt == 0:
                                    _compacted, _n = compact_completed_tool_arguments(
                                        conversation, protect_last = 1
                                    )
                                    if _n:
                                        conversation[:] = _compacted
                                        _compacted_calls = _n
                                        logger.info(
                                            "Compacted arguments of %d completed tool call(s) "
                                            "to fit the context window",
                                            _n,
                                        )
                                        continue
                                # Last resort: run it and compact its arguments after; refusing
                                # costs the same tokens.
                                if decision.tool_call_id:
                                    _as_if_run = compact_executed_call_arguments(
                                        [*conversation, _probe_message],
                                        decision.tool_call_id,
                                    )
                                    try:
                                        _after_tokens = self.count_chat_tokens(
                                            neutralize_control_markup_in_messages(
                                                messages_without_unpriced_media(_as_if_run),
                                                _markup_cache,
                                                self.markup_profile,
                                            ),
                                            None,
                                            safe_tools,
                                            strict = True,
                                            chat_template_kwargs = _reasoning_kw,
                                        )
                                    except Exception:
                                        _after_tokens = None
                                    if _after_tokens is not None and turn_is_servable(
                                        self._effective_context_length,
                                        max_tokens,
                                        _after_tokens,
                                    ):
                                        _compact_after_execution = True
                                        _compacted_turn_tokens = _after_tokens
                                        logger.info(
                                            "Running %s despite a %d-token turn: compacting "
                                            "its own arguments afterwards brings the next "
                                            "prompt to %d, so the file gets written",
                                            decision.tool_name,
                                            _turn_tokens,
                                            _after_tokens,
                                        )
                                        break
                                from core.inference import context_refusal  # noqa: PLC0415

                                _unservable_text = context_refusal.describe_unservable_tool_call(
                                    decision.tool_name,
                                    _turn_tokens,
                                    self._effective_context_length,
                                    compacted_calls = _compacted_calls,
                                )
                                logger.warning(
                                    "Refused %s before execution: prompt would be %d tokens "
                                    "against a %d-token window",
                                    decision.tool_name,
                                    _turn_tokens,
                                    self._effective_context_length,
                                )
                                break

                    if _unservable_text is not None:
                        resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                        yield {
                            "type": "tool_end",
                            "tool_name": decision.tool_name,
                            "tool_call_id": decision.tool_call_id,
                            "result": _unservable_text,
                            "provenance": decision.provenance,
                        }
                        _refused_message = {
                            "role": "tool",
                            "name": decision.tool_name,
                            "content": _unservable_text,
                        }
                        if decision.tool_call_id:
                            _refused_message["tool_call_id"] = decision.tool_call_id
                        conversation.append(_refused_message)
                        # The refusal renders the call's arguments, so compact them too.
                        _before_refused_compaction = len(json.dumps(conversation, default = str))
                        conversation[:] = compact_refused_tool_arguments(
                            conversation, decision.tool_call_id
                        )
                        _after_refused_compaction = len(json.dumps(conversation, default = str))
                        if _after_refused_compaction < _before_refused_compaction:
                            logger.info(
                                "Compacted refused %s arguments: %d -> %d chars",
                                decision.tool_name,
                                _before_refused_compaction,
                                _after_refused_compaction,
                            )
                        if _forced_tool_call_pending:
                            _forced_tool_call_pending = False
                        # A refusal resolves the forced choice, or the model is pushed to call it again.
                        _forced_choice_resolved = True
                        for _rmsg in reversed(conversation):
                            if _rmsg.get("role") != "assistant":
                                continue
                            if any(
                                (_tc or {}).get("id") == decision.tool_call_id
                                for _tc in (_rmsg.get("tool_calls") or [])
                            ):
                                assistant_msg = _rmsg
                                break
                        continue

                    _effective_timeout = None if tool_call_timeout >= 9999 else tool_call_timeout
                    if (
                        decision.tool_name in RAG_SEARCH_TOOLS
                        and _kb_search_count >= RAG_MAX_SEARCHES_PER_TURN
                    ):
                        result = RAG_SEARCH_CAP_NUDGE
                    else:
                        # Worker thread so stdout chunks and heartbeats stream while the tool blocks.
                        _last_result_budget: list = ["<not passed>"]

                        _host_access_approved = _decision not in (None, "deny")

                        def _invoke_tool(
                            _output_callback,
                            _decision = decision,
                            _approved = _host_access_approved,
                            _strict = strict_isolation,
                        ):
                            # execute_tool may be patched with an older signature; pass kwargs only if accepted.
                            kwargs = dict(
                                cancel_event = cancel_event,
                                timeout = _effective_timeout,
                                session_id = session_id,
                                thread_id = thread_id,
                                rag_scope = rag_scope,
                                disable_sandbox = bypass_permissions,
                            )
                            if _strict and accepts_kwarg(execute_tool, "tool_execution_mode"):
                                kwargs["tool_execution_mode"] = "required"
                            elif runs_without_os_sandbox(
                                _decision.tool_name, sandbox_level
                            ) and accepts_kwarg(execute_tool, "tool_execution_mode"):
                                kwargs["tool_execution_mode"] = "software"
                            # Same branch the forced recall is filtered against, so a
                            # model-initiated search cannot reach a sibling response the
                            # forced recall correctly refused.
                            if accepts_kwarg(execute_tool, "conversation_branch"):
                                kwargs["conversation_branch"] = _extend_live_branch(conversation)
                            if _approved and accepts_kwarg(execute_tool, "host_access_approved"):
                                kwargs["host_access_approved"] = True
                            # Bound top_k to the room left: the tool exchange is protected from truncation.
                            if self._effective_context_length:
                                # Exact count with the catalogue, recomputed every call; the offset
                                # is only a fallback.
                                _exact_prompt_tokens: Optional[int] = None
                                # Include a stand-in tool reply so this call's own arguments are counted.
                                _size_probe: dict = {
                                    "role": "tool",
                                    "name": decision.tool_name,
                                    "content": "",
                                }
                                if decision.tool_call_id:
                                    _size_probe["tool_call_id"] = decision.tool_call_id
                                try:
                                    _exact_prompt_tokens = self.count_chat_tokens(
                                        neutralize_control_markup_in_messages(
                                            messages_without_unpriced_media(
                                                [*conversation, _size_probe]
                                            ),
                                            _markup_cache,
                                            self.markup_profile,
                                        ),
                                        None,
                                        safe_tools,
                                        strict = True,
                                        chat_template_kwargs = _reasoning_kw,
                                    )
                                except Exception:
                                    logger.debug(
                                        "recall budget: exact prompt count failed",
                                        exc_info = True,
                                    )
                                # When compaction will run, price against the compacted prompt.
                                _spent = (
                                    _compacted_turn_tokens
                                    if _compact_after_execution and _compacted_turn_tokens
                                    else _exact_prompt_tokens
                                    if _exact_prompt_tokens is not None
                                    else estimate_messages_tokens_dense(
                                        messages_without_unpriced_media(conversation)
                                    )
                                    + (
                                        _prompt_token_offset
                                        if _prompt_token_offset is not None
                                        else estimate_messages_tokens_dense(safe_tools or [])
                                    )
                                )
                                # Budget for what ANY result may add before the next prompt overflows.
                                if accepts_kwarg(execute_tool, "result_budget_tokens"):
                                    # Split across the rest of the batch and their arguments.
                                    _pending = list(tool_calls or [])[_call_index + 1 :]
                                    _pending_msgs = [
                                        {
                                            "role": "assistant",
                                            "content": json.dumps(_call, default = str),
                                        }
                                        for _call in _pending
                                    ]
                                    if _over_cap:
                                        _pending_msgs.append(
                                            tool_call_limit_nudge(
                                                _over_cap, _MAX_TOOL_CALLS_PER_TURN
                                            )
                                        )
                                    # Measured: pending args may be base64/JSON/code that tokenise densely.
                                    _pending_args = 0
                                    if _pending_msgs:
                                        try:
                                            _pending_args = self.count_chat_tokens(
                                                _pending_msgs, None, None, strict = True
                                            )
                                        except Exception:
                                            logger.debug(
                                                "result budget: pending call count failed",
                                                exc_info = True,
                                            )
                                            _pending_args = 2 * estimate_messages_tokens_dense(
                                                _pending_msgs
                                            )
                                    _result_budget = tool_result_budget(
                                        self._effective_context_length,
                                        _iteration_max_tokens,
                                        _spent + _pending_args,
                                    ) // (len(_pending) + 1)
                                    # A near-zero budget yields only a truncation notice; compact first.
                                    if (
                                        _result_budget < _MIN_USEFUL_RESULT_TOKENS
                                        and self._effective_context_length
                                    ):
                                        _roomier, _n_roomier = compact_completed_tool_arguments(
                                            conversation, protect_last = 1
                                        )
                                        if _n_roomier:
                                            conversation[:] = _roomier
                                            try:
                                                _spent_after = self.count_chat_tokens(
                                                    neutralize_control_markup_in_messages(
                                                        messages_without_unpriced_media(
                                                            [*conversation, _size_probe]
                                                        ),
                                                        _markup_cache,
                                                        self.markup_profile,
                                                    ),
                                                    None,
                                                    safe_tools,
                                                    strict = True,
                                                    chat_template_kwargs = _reasoning_kw,
                                                )
                                            except Exception:
                                                logger.debug(
                                                    "result budget rescue: count failed",
                                                    exc_info = True,
                                                )
                                                _spent_after = None
                                            if _spent_after is not None:
                                                _rescued = tool_result_budget(
                                                    self._effective_context_length,
                                                    _iteration_max_tokens,
                                                    _spent_after + _pending_args,
                                                ) // (len(_pending) + 1)
                                                logger.info(
                                                    "Result budget for %s was %d; compacted "
                                                    "%d completed call(s) and it is now %d",
                                                    decision.tool_name,
                                                    _result_budget,
                                                    _n_roomier,
                                                    _rescued,
                                                )
                                                _result_budget = max(_result_budget, _rescued)
                                    kwargs["result_budget_tokens"] = _result_budget
                                    _last_result_budget[0] = kwargs["result_budget_tokens"]
                                    _starved_call[0] = _result_budget < _MIN_USEFUL_RESULT_TOKENS
                                if accepts_kwarg(execute_tool, "conversation_budget_tokens"):
                                    if accepts_kwarg(execute_tool, "conversation_token_counter"):
                                        # Hand over the tokenizer: char estimates undercount dense ASCII.
                                        kwargs["conversation_token_counter"] = lambda text: (
                                            self.count_chat_tokens(
                                                [{"role": "tool", "content": text}],
                                                None,
                                                None,
                                                strict = False,
                                            )
                                        )
                                    kwargs["conversation_budget_tokens"] = _retrieval_budget(
                                        self._effective_context_length,
                                        _iteration_max_tokens,
                                        _spent,
                                        reply_returns = True,
                                    )
                            if accepts_output_callback(execute_tool):
                                kwargs["output_callback"] = _output_callback
                            kwargs.update(search_images_kwargs(execute_tool, _decision.tool_name))
                            if image_share is not None:
                                kwargs["mcp_image"] = image_share["image"]
                            return execute_tool(
                                _decision.tool_name,
                                _decision.arguments,
                                **kwargs,
                            )

                        # A raising tool is the tool's failure; return it rather than kill the answer.
                        try:
                            result = yield from stream_tool_execution(
                                _invoke_tool,
                                tool_name = decision.tool_name,
                                tool_call_id = decision.tool_call_id,
                                cancel_event = cancel_event,
                            )
                        except _LlamaStreamCancelled:
                            # Subclasses Exception; re-raise so the arm below doesn't eat the cancel.
                            raise
                        except Exception as _tool_exc:
                            if cancel_event is not None and cancel_event.is_set():
                                raise
                            logger.exception(
                                "Tool %s raised: %s",
                                decision.tool_name,
                                _tool_exc,
                            )
                            result = f"Error: tool raised an exception: {_tool_exc}"
                        if decision.tool_name in RAG_SEARCH_TOOLS:
                            _kb_search_count += 1
                    logger.info(
                        "tool result: name=%s budget_tokens=%s chars=%d",
                        decision.tool_name,
                        _last_result_budget[0],
                        len(result) if isinstance(result, str) else -1,
                    )
                    _result_was_starved = False
                    # Nudge only on evidence of truncation: short results like 'OK' can be complete.
                    if (
                        _starved_call[0]
                        and isinstance(result, str)
                        and (not result.strip() or _is_window_notice(result))
                    ):
                        _starved_call[0] = False
                        _result_was_starved = True
                        logger.info(
                            "%s ran with a result budget below %d; telling the model the "
                            "window cannot carry the result",
                            decision.tool_name,
                            _MIN_USEFUL_RESULT_TOKENS,
                        )
                        result = _starved_result_message(decision.tool_name, result)
                    else:
                        _starved_call[0] = False

                    # No-progress guard keyed on the RESULT, so it never fires while results change.
                    if isinstance(result, str):
                        # Arguments are in the key unless the result is the window's own truncation notice.
                        _result_key = (
                            decision.tool_name,
                            hashlib.sha1(result.encode("utf-8", "replace")).hexdigest(),
                            None
                            if _result_was_starved or _is_window_notice(result)
                            else hashlib.sha1(
                                json.dumps(decision.arguments, sort_keys = True, default = str).encode(
                                    "utf-8", "replace"
                                )
                            ).hexdigest(),
                        )
                        if _result_key == _last_tool_result_key[0]:
                            _identical_result_runs[0] += 1
                        else:
                            _last_tool_result_key[0] = _result_key
                            _identical_result_runs[0] = 1
                        if _identical_result_runs[0] >= _MAX_IDENTICAL_TOOL_RESULTS:
                            logger.info(
                                "%s returned the same result %d times; saying so instead of "
                                "letting the turn spend itself repeating it",
                                decision.tool_name,
                                _identical_result_runs[0],
                            )
                            result = _repeated_result_message(
                                decision.tool_name, _identical_result_runs[0], result
                            )
                            _identical_result_runs[0] = 0
                            _last_tool_result_key[0] = None
                    completion = tool_controller.record_result(decision, result)
                    resolved_provisional_tool_call_ids.add(decision.tool_call_id)
                    # Reset so the post-tool nudge isn't swallowed as a repeat.
                    _last_reprompt_text = ""
                    _turn_executed_real_tool = True
                    _forced_choice_resolved = True
                    yield completion.tool_end_event()
                    conversation.append(completion.tool_message())
                    _completion_images = (
                        completion.mcp_images()
                        if mcp_images_mentioned_in(completion.result or "") and self.is_vision
                        else []
                    )
                    if _completion_images:
                        batch_mcp_images.append(_completion_images)
                    if _compact_after_execution and decision.tool_call_id:
                        # Compact now: this turn's own generation would otherwise be rejected.
                        _before_len = len(json.dumps(conversation, default = str))
                        conversation[:] = compact_executed_call_arguments(
                            conversation, decision.tool_call_id
                        )
                        logger.info(
                            "Compacted %s arguments after running it: %d -> %d chars",
                            decision.tool_name,
                            _before_len,
                            len(json.dumps(conversation, default = str)),
                        )
                        # Rebind to the live message after compaction. Scan backwards: ids restart at call_0.
                        for _msg in reversed(conversation):
                            if _msg.get("role") != "assistant":
                                continue
                            if any(
                                (_tc or {}).get("id") == decision.tool_call_id
                                for _tc in (_msg.get("tool_calls") or [])
                            ):
                                assistant_msg = _msg
                                break

                    if _forced_tool_call_pending:
                        _forced_tool_call_pending = False

                _over_cap_final = bool(_over_cap) and (
                    tool_controller.force_final_answer
                    or not tool_controller.active_tools()
                    or (_turn_executed_real_tool and _tool_iters_done + 1 >= max_tool_iterations)
                    # The loop also ends on the outer iteration range, not just the tool cap.
                    or iteration + 1 >= max_tool_iterations + _extra + _continuation_credits
                )
                _final_over_cap = _over_cap if _over_cap_final else []
                if _over_cap_final:
                    _over_cap = []
                if _over_cap:
                    deferred_noop_msgs.append(
                        tool_call_limit_nudge(
                            _over_cap,
                            _MAX_TOOL_CALLS_PER_TURN,
                            unavailable_tools = {
                                _limit_decision.tool_name
                                for _call in _over_cap
                                if (_limit_decision := tool_controller.prepare_call(_call)).action
                                in ("disabled", "render_html_repeat")
                            },
                        )
                    )
                # Fold feedback into a result only for the SAME tool: templates label it by tool name.
                _fold_target_matches = (
                    not _over_cap
                    and len(deferred_noop_tools) == 1
                    and bool(conversation)
                    and conversation[-1].get("role") == "tool"
                    and conversation[-1].get("name") in deferred_noop_tools
                )
                if deferred_noop_msgs and assistant_appended and _fold_target_matches:
                    if not _attach_internal_feedback_to_tool_result(
                        deferred_nudge_text(deferred_noop_msgs)
                    ):
                        append_deferred_nudges(conversation, deferred_noop_msgs)
                elif deferred_noop_msgs and assistant_appended:
                    append_deferred_nudges(conversation, deferred_noop_msgs)
                else:
                    if not assistant_appended and (
                        content_text or assistant_msg.get("reasoning_content") or _resumed_reasoning
                    ):
                        if assistant_msg.get("reasoning_content") or _resumed_reasoning:
                            assistant_msg["content"] = neutralize_control_markup(
                                _resumed_reasoning + reasoning_accum,
                                self.markup_profile,
                            )
                            _continued_partial = (
                                trailing_assistant_text(conversation)
                                if continue_final_message
                                else None
                            )
                            if _continued_partial and not _continued_partial.endswith("\n"):
                                assistant_msg["content"] = f"\n{assistant_msg['content']}"
                            if content_text:
                                assistant_msg["content"] += f"\n{content_text}"
                            assistant_msg.pop("reasoning_content", None)
                        append_assistant_turn(
                            conversation,
                            assistant_msg,
                            continue_final_message = _merge_into_partial,
                        )
                        if _resumed_reasoning:
                            conversation[-1].pop("reasoning_content", None)
                        assistant_appended = True
                    append_deferred_nudges(conversation, deferred_noop_msgs)
                if _final_over_cap:
                    _limit_text = tool_call_limit_nudge(
                        _final_over_cap, _MAX_TOOL_CALLS_PER_TURN, final = True
                    )["content"]
                    # Same rule as _fold_target_matches.
                    _limit_names = {
                        (_tc.get("function") or {}).get("name") for _tc in _final_over_cap
                    }
                    _limit_foldable = (
                        bool(conversation)
                        and conversation[-1].get("role") == "tool"
                        and _limit_names == {conversation[-1].get("name")}
                    )
                    if not (
                        _limit_foldable and _attach_internal_feedback_to_tool_result(_limit_text)
                    ):
                        if deferred_noop_msgs and conversation[-1].get("role") == "user":
                            conversation[-1] = {
                                **conversation[-1],
                                "content": f"{conversation[-1]['content']}\n\n{_limit_text}",
                            }
                        else:
                            conversation.append({"role": "user", "content": _limit_text})
                        _limit_notice_in_user_turn = True

                if batch_mcp_images and self.is_vision:
                    _batch_results = sum(
                        1
                        for m in conversation[batch_conversation_start:]
                        if isinstance(m, dict) and m.get("role") == "tool"
                    )
                    append_mcp_image_turn(
                        conversation,
                        batch_mcp_images,
                        per_result = True,
                        owned = loop_mcp_image_parts,
                        lead = MCP_DETACHED_IMAGE_TURN_TEXT
                        if _batch_results != 1
                        else MCP_IMAGE_TURN_TEXT,
                    )

                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "",
                            "provenance": provisional_tool_provenance(_pname),
                        }

                yield {"type": "status", "text": ""}
                if tool_controller.force_final_answer or not tool_controller.active_tools():
                    _append_budget_exhausted_nudge = False
                    break
                if _turn_executed_real_tool:
                    _tool_iters_done += 1
                    if _tool_iters_done >= max_tool_iterations:
                        break
                continue

            except _LlamaStreamCancelled:
                _held = _cancelled_hold_text()
                if _held:
                    yield {"type": "content", "text": _held}
                return
            except httpx.ConnectError:
                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "Error: lost connection to llama-server before the tool call completed.",
                            "provenance": provisional_tool_provenance(_pname),
                        }
                raise RuntimeError("Lost connection to llama-server")
            except Exception as e:
                if cancel_event is not None and cancel_event.is_set():
                    return
                for _pid, _pname in provisional_started_tool_calls.items():
                    if _pid not in resolved_provisional_tool_call_ids:
                        resolved_provisional_tool_call_ids.add(_pid)
                        yield {
                            "type": "tool_end",
                            "tool_name": _pname,
                            "tool_call_id": _pid,
                            "result": "Error: the tool call was interrupted before it completed.",
                            "provenance": provisional_tool_provenance(_pname),
                        }
                raise

        if max_tool_iterations > 0 and _append_budget_exhausted_nudge:
            if not _attach_internal_feedback_to_tool_result(BUDGET_EXHAUSTED_NUDGE):
                # Two user turns in a row break strict templates (Gemma).
                if _limit_notice_in_user_turn and conversation[-1].get("role") == "user":
                    conversation[-1] = {
                        **conversation[-1],
                        "content": f"{conversation[-1]['content']}\n\n{BUDGET_EXHAUSTED_NUDGE}",
                    }
                else:
                    conversation.append({"role": "user", "content": BUDGET_EXHAUSTED_NUDGE})

        yield {"type": "status", "text": ""}

        # Final streaming pass with the full conversation context.
        from core.inference.chat_template_helpers import neutralize_control_markup_in_messages

        _reasoning_kw = self._request_reasoning_kwargs(
            enable_thinking, reasoning_effort, preserve_thinking
        )
        _final_max_tokens = (
            max_tokens
            if max_tokens is not None
            else (self._effective_context_length or _DEFAULT_MAX_TOKENS_FLOOR)
        )
        _final_preflight_context_length = None
        _final_preflight_succeeded = False
        if context_overflow == "truncate_oldest" and self._effective_context_length:
            _final_preflight_context_length = self._effective_context_length
            try:
                _before_final_fit = conversation
                # Withheld: the final pass sends no tools, so no new epoch may start here.
                _final_can_reset = _can_reset_epoch(
                    thread_id, _backend_supports_tools(self), tools_withheld = True
                )
                _final_sticky, _final_sticky_is_checkpoint = (
                    (0, True)
                    if _sticky_boundary_applied
                    else _sticky_compaction_state(
                        thread_id,
                        _request_branch,
                        context_policy = context_policy,
                        can_reset = _final_can_reset,
                        compaction_headroom_ratio = compaction_headroom_ratio,
                    )
                )
                conversation, truncation = _fit_with_instruction_pins(
                    conversation,
                    context_length = self._effective_context_length,
                    max_tokens = _final_max_tokens,
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(
                            messages_without_unpriced_media(fitted), None, self.markup_profile
                        ),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    estimate_message = estimate_message_tokens_without_unpriced_media,
                    anchor_ids = _rolling_anchor_ids,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _final_can_reset,
                    reserve_tokens = _conversation_recall_reserve(thread_id),
                    sticky_dropped = _final_sticky,
                    sticky_is_checkpoint = _final_sticky_is_checkpoint,
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                _sticky_boundary_applied = True
                if truncation:
                    _recalled = _archive_and_recall(
                        conversation,
                        _before_final_fit,
                        branch_messages = _extend_live_branch(_before_final_fit),
                        thread_id = thread_id,
                        # Inline: no tools array, so a forged tool role breaks strict templates.
                        style = "inline",
                        force_recall = bool(truncation.get("checkpoint_started", True)),
                        recall_done = _conversation_recall_done or not truncation["fits"],
                        recall_budget_tokens = _retrieval_budget(
                            self._effective_context_length,
                            max_tokens,
                            truncation.get("prompt_tokens_after") or 0,
                        ),
                        count_tokens = lambda fitted: self.count_chat_tokens(
                            neutralize_control_markup_in_messages(
                                messages_without_unpriced_media(fitted),
                                None,
                                self.markup_profile,
                            ),
                            None,
                            None,
                            strict = True,
                            chat_template_kwargs = _reasoning_kw,
                        ),
                    )
                    conversation = _recalled["conversation"]
                    truncation = {**truncation, **_recalled["counts"]}
                    if _recalled["recalled"]:
                        _conversation_recall_done = True
                        for _message in _recalled["anchored"]:
                            _rolling_anchor_ids.add(id(_message))
                        for _ev in _recalled["events"]:
                            yield _ev
                if truncation and _records_boundary(truncation):
                    truncation = {
                        **truncation,
                        **_boundary_metadata(
                            conversation, _request_branch, compaction_headroom_ratio
                        ),
                    }
                # Report even when it does not fit: it carries the diagnosis for the client.
                if truncation:
                    yield {"type": "context_truncated", **truncation}
                _final_preflight_succeeded = True
            except Exception as exc:
                logger.warning("Could not preflight the rolling context window: %s", exc)

        # Re-cost here: this final pass is the run's largest request.
        if on_conversation_grew is not None:
            try:
                on_conversation_grew(conversation)
            except Exception:  # accounting must never break a run
                logger.debug("tool loop final recost failed", exc_info = True)

        stream_payload = {
            "messages": neutralize_control_markup_in_messages(
                conversation, None, self.markup_profile
            ),
            "stream": True,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
            "presence_penalty": presence_penalty,
            "frequency_penalty": frequency_penalty,
        }
        if logit_bias:
            stream_payload["logit_bias"] = logit_bias
        if _reasoning_kw is not None:
            stream_payload["chat_template_kwargs"] = _reasoning_kw
        if thinking_budget_tokens is not None:
            stream_payload["thinking_budget_tokens"] = thinking_budget_tokens
        stream_payload["max_tokens"] = _final_max_tokens
        if stop:
            stream_payload["stop"] = stop
        _apply_seeded_llama_request(stream_payload, seed)
        stream_payload["stream_options"] = {"include_usage": True}

        stream_payload["return_progress"] = True
        if _perf_callback_wants_timings(perf_callback):
            stream_payload["timings_per_token"] = True

        _final_respawn_truncations: list[dict] = []
        _refit_tail: list = []
        _refit_tail_merged = False

        def _record_refit_tail(committed: list, appended: list, merged: bool) -> None:
            """Track appended messages that a respawn refit must replay."""
            nonlocal _refit_tail, _refit_tail_merged
            _live = {id(_message) for _message in committed}
            _new = [_message for _message in appended if id(_message) in _live]
            if len(_new) != len(appended):
                _refit_tail = []
                _refit_tail_merged = False
                return
            if not merged:
                _refit_tail = _refit_tail + _new
            elif _refit_tail:
                _refit_tail = _refit_tail[:-1] + _new
            else:
                _refit_tail = _new
                _refit_tail_merged = True

        def _refit_final_after_respawn() -> None:
            nonlocal conversation
            _before_respawn_fit = conversation
            if (
                _final_preflight_context_length is None
                or not self._effective_context_length
                or (
                    _final_preflight_succeeded
                    and _final_preflight_context_length == self._effective_context_length
                )
            ):
                return
            if max_tokens is None:
                stream_payload["max_tokens"] = self._effective_context_length
            try:
                conversation, truncation = _fit_with_instruction_pins(
                    conversation,
                    context_length = self._effective_context_length,
                    max_tokens = max_tokens,
                    count_tokens = lambda fitted: self.count_chat_tokens(
                        neutralize_control_markup_in_messages(
                            messages_without_unpriced_media(fitted), None, self.markup_profile
                        ),
                        None,
                        None,
                        strict = True,
                        chat_template_kwargs = _reasoning_kw,
                        should_abort = lambda: bool(cancel_event and cancel_event.is_set()),
                    ),
                    estimate_message = estimate_message_tokens_without_unpriced_media,
                    anchor_ids = _rolling_anchor_ids,
                    keeps_boundary = _keeps_compaction_boundary(thread_id),
                    can_reset = _can_reset_epoch(
                        thread_id,
                        _backend_supports_tools(self),
                        tools_withheld = True,
                    ),
                    **_compaction_fit_kwargs(context_policy, compaction_headroom_ratio),
                )
                if truncation:
                    truncation.update(
                        _archive_and_recall(
                            conversation,
                            _before_respawn_fit,
                            thread_id = thread_id,
                            style = "inline",
                            recall_done = True,
                            branch_messages = _extend_live_branch(conversation),
                        )["counts"]
                    )
                from core.inference import context_refusal  # noqa: PLC0415

                context_refusal.record_fit(truncation)
                # Copy because neutralization may return `conversation` itself.
                _refit_messages = list(
                    neutralize_control_markup_in_messages(conversation, None, self.markup_profile)
                )
                if _refit_tail:
                    if _refit_tail_merged and trailing_assistant_text(_refit_messages) is not None:
                        _refit_messages[-1:] = _refit_tail
                    else:
                        _refit_messages.extend(_refit_tail)
                stream_payload["messages"] = _refit_messages
                if _refit_tail:
                    _refit_continue = bool(stream_payload.get("continue_final_message"))
                    if not _continuation_would_be_served(
                        stream_payload["messages"], _refit_continue
                    ):
                        _refit_protect = {id(_message) for _message in _refit_tail}
                        for _message in reversed(
                            _refit_messages[: len(_refit_messages) - len(_refit_tail)]
                        ):
                            _refit_protect.add(id(_message))
                            if _message.get("role") == "user":
                                break
                        _refit_evicted = _evict_until_it_fits(
                            stream_payload["messages"],
                            None,
                            stream_payload.get("chat_template_kwargs"),
                            _refit_continue,
                            _refit_protect,
                        )
                        if _refit_evicted is not None:
                            stream_payload["messages"] = _refit_evicted
                if truncation:
                    if _records_boundary(truncation):
                        truncation.update(
                            _boundary_metadata(
                                conversation, _request_branch, compaction_headroom_ratio
                            )
                        )
                    _final_respawn_truncations.append(truncation)
            except Exception as exc:
                logger.warning("Could not refit rolling context after respawn: %s", exc)
                raise

        cumulative = ""
        _last_emitted = ""
        in_thinking = False
        has_content_tokens = False
        reasoning_text = ""
        answer_text = ""
        _prov_entry = None
        _final_reasoning_started_at: Optional[float] = None
        _final_reasoning_summary_emitted = False
        _metadata_usage = None
        _metadata_timings = None
        _metadata_finish_reason = None
        _stream_done = False

        # Continuations for the final pass, which runs after the loop's own recovery.
        _final_length_continuations = 0
        _continue_final = False
        _final_replayed_chars = 0

        def _remaining_output_budget() -> "Optional[int]":
            """What is left of a cap the CALLER set, or None when they set none.

            `finish_reason: "length"` does not say which wall was hit. A caller asking for
            at most 100 completion tokens gets it at their own cap, and continuing twice
            more returned roughly 300 -- over the limit the API promised, for latency and
            tokens nobody asked for. Only the context wall deserves a continuation, and a
            caller who set a cap gets the remainder of it rather than a fresh one.

            None means no explicit cap: `max_tokens` unset, or set to the whole window,
            which is what the backend substitutes for "Max" and is indistinguishable from
            unset. There the length stop IS the context wall, which is the case this
            continuation exists for.
            """
            if max_tokens is None:
                return None
            window = self._effective_context_length or 0
            if window and max_tokens >= window:
                return None
            # Without usage, a `length` stop spent the whole allowance; never guess low.
            _this_attempt = (
                _backfill_usage_from_timings(_metadata_usage, _metadata_timings) or {}
            ).get("completion_tokens", 0) or int(stream_payload.get("max_tokens") or 0)
            return max(0, max_tokens - _accumulated_completion_tokens - _this_attempt)

        def _continuation_would_be_served(
            candidate_messages,
            continue_flag: bool,
            reasoning_kw = _UNSET,
        ) -> bool:
            """Whether the retry's own prompt still fits, now that the partial is in it.

            The first pass reached `finish_reason: length` by consuming the physical
            context, so appending everything it produced makes the next prompt roughly
            context-sized. Reopening the stream without asking gets it rejected before a
            single extra token arrives, which is worse than stopping: the user keeps the
            partial either way, and one of the two paths also shows an error.

            A count that cannot be taken is not a refusal. Failing open here restores the
            behaviour this continuation had before the check, which is the safe side.
            """
            if not self._effective_context_length:
                return True
            try:
                _tokens = self.count_chat_tokens(
                    messages_without_unpriced_media(candidate_messages),
                    None,
                    None,
                    strict = True,
                    chat_template_kwargs = (
                        stream_payload.get("chat_template_kwargs")
                        if reasoning_kw is _UNSET
                        else reasoning_kw
                    ),
                    continue_final_message = continue_flag,
                )
            except Exception:
                logger.debug("final continuation: prompt count failed", exc_info = True)
                return True
            # Not turn_is_servable: that reserves room for a tool-result notice.
            _floor = _reply_floor(self._effective_context_length)
            if _tokens + _floor <= self._effective_context_length:
                return True
            logger.info(
                "Final continuation would not be served (%d tokens of a %d-token "
                "window); keeping the partial answer instead",
                _tokens,
                self._effective_context_length,
            )
            return False

        # Per-attempt mark: emitted state is cumulative across continuations.
        _attempt_started_at = ""
        while True:
            try:
                with self._open_chat_stream_with_respawn_retry(
                    stream_payload,
                    cancel_event,
                    on_respawn = _refit_final_after_respawn,
                ) as (
                    response,
                    first_token_deadline,
                ):
                    for truncation in _final_respawn_truncations:
                        yield {"type": "context_truncated", **truncation}
                    buffer = ""
                    for raw_chunk in self._iter_text_cancellable(
                        response,
                        cancel_event,
                        first_token_deadline = first_token_deadline,
                    ):
                        buffer += raw_chunk
                        while "\n" in buffer:
                            line, buffer = buffer.split("\n", 1)
                            line = line.strip()

                            if not line:
                                continue
                            if line == "data: [DONE]":
                                if in_thinking:
                                    if (
                                        _final_reasoning_started_at is not None
                                        and not _final_reasoning_summary_emitted
                                    ):
                                        _final_reasoning_summary_emitted = True
                                        yield _reasoning_summary_event(_final_reasoning_started_at)
                                    if has_content_tokens:
                                        cumulative += "</think>"
                                        _prov_entry = None
                                        yield {
                                            "type": "content",
                                            "text": _strip_tool_markup(cumulative, final = True),
                                        }
                                    else:
                                        cumulative = _finalize_reasoning_only_cumulative(
                                            cumulative,
                                            reasoning_text,
                                            _metadata_finish_reason,
                                            promote_reasoning_only,
                                        )
                                        # Clear it, or the retry closes the block twice and shows a stray tag.
                                        in_thinking = False
                                        _prov_entry = None
                                        yield {"type": "content", "text": cumulative}
                                _stream_done = True
                                break
                            if not line.startswith("data: "):
                                continue

                            try:
                                chunk_data = json.loads(line[6:])

                                _report_live_llama_timings(perf_callback, chunk_data)
                                _chunk_timings = chunk_data.get("timings")
                                if _chunk_timings:
                                    _metadata_timings = _chunk_timings
                                _chunk_usage = chunk_data.get("usage")
                                if _chunk_usage:
                                    _metadata_usage = _chunk_usage
                                _stream_error = stream_error_from_chunk(chunk_data)
                                if _stream_error is not None:
                                    raise _stream_error
                                choices = chunk_data.get("choices", [])
                                if choices:
                                    delta = choices[0].get("delta", {})
                                    _fr = choices[0].get("finish_reason")
                                    if _fr:
                                        _metadata_finish_reason = _fr

                                    reasoning = delta.get("reasoning_content", "")
                                    if reasoning:
                                        if _final_reasoning_started_at is None:
                                            _final_reasoning_started_at = time.monotonic()
                                        reasoning_text += reasoning
                                        if not in_thinking:
                                            if reasoning_provenance is not None and not cumulative:
                                                reasoning_provenance["wrapped"] = (
                                                    reasoning_provenance.get("wrapped", 0) + 1
                                                )
                                                _prov_entry = {"len": 0}
                                                reasoning_provenance.setdefault("wraps", []).append(
                                                    _prov_entry
                                                )
                                            cumulative += "<think>"
                                            in_thinking = True
                                        cumulative += reasoning
                                        if _prov_entry is not None:
                                            _prov_entry["len"] += len(reasoning)
                                        yield {"type": "content", "text": cumulative}

                                    token = delta.get("content", "")
                                    if token:
                                        if (
                                            _final_reasoning_started_at is not None
                                            and not _final_reasoning_summary_emitted
                                        ):
                                            _final_reasoning_summary_emitted = True
                                            yield _reasoning_summary_event(
                                                _final_reasoning_started_at
                                            )
                                        has_content_tokens = True
                                        answer_text += token
                                        if in_thinking:
                                            cumulative += "</think>"
                                            in_thinking = False
                                            _prov_entry = None
                                        cumulative += token
                                        cleaned = (
                                            _final_answer_stripper.strip(cumulative)
                                            if auto_heal_tool_calls
                                            else cumulative
                                        )
                                        if len(cleaned) > len(_last_emitted):
                                            _last_emitted = cleaned
                                            yield {"type": "content", "text": cleaned}
                            except json.JSONDecodeError:
                                logger.debug(f"Skipping malformed SSE line: {line[:100]}")
                        if _stream_done:
                            break
                    # Cut mid-answer: resume via continuation unless repetition-dominated.
                    _shown_this_attempt = _last_emitted[len(_attempt_started_at) :]
                    if (
                        _metadata_finish_reason == "length"
                        and has_content_tokens
                        and _shown_this_attempt.strip()
                        and _final_length_continuations < _MAX_LENGTH_CONTINUATIONS
                        and not is_repetition_dominated(_last_emitted)
                    ):
                        from core.inference.chat_template_helpers import (  # noqa: PLC0415
                            append_assistant_turn as _append_assistant_turn,
                        )

                        _final_length_continuations += 1
                        logger.info(
                            "Final answer cut off at %d chars; continuing %d/%d",
                            len(_last_emitted),
                            _final_length_continuations,
                            _MAX_LENGTH_CONTINUATIONS,
                        )
                        # Candidate, committed only once another stream will run, so usage isn't double counted.
                        # Replay only what is new since the last replay.
                        _candidate_messages = list(stream_payload["messages"])
                        _merged_f = trailing_assistant_text(_candidate_messages) is not None
                        _append_assistant_turn(
                            _candidate_messages,
                            {
                                "role": "assistant",
                                "content": _last_emitted[_final_replayed_chars:],
                            },
                            continue_final_message = True,
                        )
                        # Neutralize the model's replayed text so delimiters aren't read as chat structure.
                        _candidate_messages = neutralize_control_markup_in_messages(
                            _candidate_messages, None, self.markup_profile
                        )
                        _continuation_tail = _candidate_messages[-1:]
                        _next_cap = _remaining_output_budget()
                        _served = _next_cap != 0 and _continuation_would_be_served(
                            _candidate_messages, True
                        )
                        if _next_cap != 0 and not _served:
                            _evicted_f = _evict_until_it_fits(
                                _candidate_messages,
                                None,
                                stream_payload.get("chat_template_kwargs"),
                                True,
                            )
                            if _evicted_f is not None and _continuation_would_be_served(
                                _evicted_f, True
                            ):
                                _candidate_messages = _evicted_f
                                _served = True
                        if _served:
                            stream_payload["messages"] = _candidate_messages
                            _record_refit_tail(_candidate_messages, _continuation_tail, _merged_f)
                            _final_replayed_chars = len(_last_emitted)
                            stream_payload["continue_final_message"] = True
                            stream_payload["add_generation_prompt"] = False
                            if _next_cap is not None:
                                stream_payload["max_tokens"] = _next_cap
                            _fu_f = (
                                _backfill_usage_from_timings(_metadata_usage, _metadata_timings)
                                or {}
                            )
                            _accumulated_completion_tokens += _fu_f.get("completion_tokens", 0)
                            _it_f = _metadata_timings or {}
                            _accumulated_predicted_ms += _it_f.get("predicted_ms", 0)
                            _accumulated_predicted_n += _it_f.get("predicted_n", 0)
                            _stream_done = False
                            _metadata_finish_reason = None
                            # Reset per attempt so the next one is not charged twice.
                            _metadata_usage = None
                            _metadata_timings = None
                            _attempt_started_at = _last_emitted
                            _continue_final = True
                            # No blank status: it resets the route cursor and the partial would be sent twice.
                            yield {
                                "type": "status",
                                "text": _CONTINUE_TRUNCATED_ANSWER_STATUS,
                            }
                        else:
                            _meta = _build_metadata_event(
                                _metadata_usage, _metadata_timings, _metadata_finish_reason
                            )
                            if _meta is not None:
                                yield _meta
                    elif (
                        _metadata_finish_reason == "length"
                        and not _shown_this_attempt.strip()
                        and reasoning_text.strip()
                    ):
                        # Reasoning-only stop after the loop broke; would render empty otherwise.
                        if _final_length_continuations < _MAX_LENGTH_CONTINUATIONS:
                            from core.inference.chat_template_helpers import (  # noqa: PLC0415
                                append_assistant_turn as _append_assistant_turn,
                            )

                            _final_length_continuations += 1
                            logger.info(
                                "Final pass ended inside its reasoning (%d chars); "
                                "continuing %d/%d with thinking off",
                                len(reasoning_text),
                                _final_length_continuations,
                                _MAX_LENGTH_CONTINUATIONS,
                            )
                            _candidate_r = list(stream_payload["messages"])
                            _merged_r = (
                                bool(stream_payload.get("continue_final_message"))
                                and trailing_assistant_text(_candidate_r) is not None
                            )
                            _append_assistant_turn(
                                _candidate_r,
                                {
                                    "role": "assistant",
                                    "content": _unfinished_thought_progress(reasoning_text),
                                },
                                continue_final_message = bool(
                                    stream_payload.get("continue_final_message")
                                ),
                            )
                            _candidate_r.append(
                                {"role": "user", "content": _continue_after_length_message()}
                            )
                            # Neutralize: the progress note quotes the model's reasoning.
                            _candidate_r = neutralize_control_markup_in_messages(
                                _candidate_r, None, self.markup_profile
                            )
                            # Admit with thinking-off kwargs, matching the request actually sent.
                            _off_kw = self._request_reasoning_kwargs(False, None, preserve_thinking)
                            _next_cap_r = _remaining_output_budget()
                            _recovery_tail = _candidate_r[-2:]
                            _recovery_protect = {id(_message) for _message in _recovery_tail}
                            for _message in reversed(_candidate_r[:-2]):
                                _recovery_protect.add(id(_message))
                                if _message.get("role") == "user":
                                    break
                            _served_r = _next_cap_r != 0 and _continuation_would_be_served(
                                _candidate_r, False, _off_kw
                            )
                            if _next_cap_r != 0 and not _served_r:
                                _evicted_r = _evict_until_it_fits(
                                    _candidate_r, None, _off_kw, False, _recovery_protect
                                )
                                if _evicted_r is not None and _continuation_would_be_served(
                                    _evicted_r, False, _off_kw
                                ):
                                    _candidate_r = _evicted_r
                                    _served_r = True
                            if _served_r:
                                stream_payload["messages"] = _candidate_r
                                _record_refit_tail(_candidate_r, _recovery_tail, _merged_r)
                                stream_payload.pop("continue_final_message", None)
                                stream_payload.pop("add_generation_prompt", None)
                                if _next_cap_r is not None:
                                    stream_payload["max_tokens"] = _next_cap_r
                                if _off_kw is not None:
                                    stream_payload["chat_template_kwargs"] = _off_kw
                                else:
                                    stream_payload.pop("chat_template_kwargs", None)
                                _fu_r = (
                                    _backfill_usage_from_timings(_metadata_usage, _metadata_timings)
                                    or {}
                                )
                                _accumulated_completion_tokens += _fu_r.get("completion_tokens", 0)
                                _it_r = _metadata_timings or {}
                                _accumulated_predicted_ms += _it_r.get("predicted_ms", 0)
                                _accumulated_predicted_n += _it_r.get("predicted_n", 0)
                                _stream_done = False
                                _metadata_finish_reason = None
                                # Reset per attempt so the next one is not charged twice.
                                _metadata_usage = None
                                _metadata_timings = None
                                _attempt_started_at = _last_emitted
                                _continue_final = True
                                # No blank status here: it would replay what was already streamed.
                                yield {
                                    "type": "status",
                                    "text": _CONTINUE_AFTER_LENGTH_STATUS,
                                }
                            else:
                                yield {"type": "status", "text": ""}
                                # Content events are cumulative: don't overwrite an answer already shown.
                                if not _last_emitted.strip():
                                    yield {
                                        "type": "content",
                                        # Name the right lever: output cap vs context window.
                                        "text": (
                                            _reasoning_cap_spent_message(max_tokens)
                                            if _next_cap_r == 0
                                            else _thinking_exhausted_message(
                                                self._effective_context_length
                                            )
                                        ),
                                    }
                                _meta = _build_metadata_event(
                                    _metadata_usage,
                                    _metadata_timings,
                                    _metadata_finish_reason,
                                )
                                if _meta is not None:
                                    yield _meta
                        else:
                            # Allowance spent with nothing shown: say so. Re-read the cap here.
                            _cap_left_g = _remaining_output_budget()
                            yield {"type": "status", "text": ""}
                            if not _last_emitted.strip():
                                yield {
                                    "type": "content",
                                    "text": (
                                        _reasoning_cap_spent_message(max_tokens)
                                        if _cap_left_g == 0
                                        else _thinking_exhausted_message(
                                            self._effective_context_length
                                        )
                                    ),
                                }
                            _meta = _build_metadata_event(
                                _metadata_usage, _metadata_timings, _metadata_finish_reason
                            )
                            if _meta is not None:
                                yield _meta
                    else:
                        _cut = _quote_cut_event(
                            reasoning_text,
                            answer_text,
                            _metadata_finish_reason,
                            promote_reasoning_only,
                        )
                        if _cut is not None:
                            yield _cut
                        _meta = _build_metadata_event(
                            _metadata_usage, _metadata_timings, _metadata_finish_reason
                        )
                        if _meta is not None:
                            yield _meta

                if _continue_final:
                    _continue_final = False
                    continue
                break

            except _LlamaStreamCancelled:
                # No flush: those buffers belong to the tool loop and would replay old text.
                return
            except httpx.ConnectError:
                raise RuntimeError("Lost connection to llama-server")
            except Exception as e:
                if cancel_event is not None and cancel_event.is_set():
                    return
                raise

    def count_chat_tokens(
        self,
        messages,
        system = None,
        tools = None,
        strict: bool = False,
        chat_template_kwargs = None,
        continue_final_message: bool = False,
        should_abort = None,
        prefer_native: bool = False,
    ) -> int:
        """Count prompt tokens for a chat request via llama-server.

        Non-strict callers keep the historical best-effort behavior and get 0 when a
        count cannot be determined. Strict callers (public count_tokens endpoints)
        raise instead: the text-only fallback is an approximation, not a count.

        ``chat_template_kwargs`` reaches /apply-template unchanged, so a caller can
        price a request rendered in a non-default reasoning mode.

        ``should_abort`` is polled between the two llama-server calls. Admission is the
        caller's job; this only stops a count that was admitted while idle from spending its
        second round trip once the answer stopped mattering. Raises when it fires.

        ``prefer_native`` tries /v1/chat/completions/input_tokens first (one round trip).
        """
        if not self.is_loaded:
            if strict:
                raise RuntimeError("llama-server is not loaded")
            return 0

        def _block_text(content) -> str:
            if isinstance(content, str):
                return content
            if isinstance(content, list):
                parts = []
                for block in content:
                    if isinstance(block, dict):
                        if isinstance(block.get("text"), str):
                            parts.append(block["text"])
                    elif isinstance(block, str):
                        parts.append(block)
                return "".join(parts)
            return ""

        system_text = ""
        if isinstance(system, str):
            system_text = system
        elif isinstance(system, list):
            system_text = _block_text(system)

        # Count the neutralized prompt, the one generation actually sends.
        from core.inference.chat_template_helpers import (
            neutralize_control_markup,
            neutralize_control_markup_in_messages,
            neutralize_tool_descriptions,
        )

        _profile = self.markup_profile
        messages = neutralize_control_markup_in_messages(messages, None, _profile)
        # Use the model's own profile so the count matches what generation sends.
        system_text = (
            neutralize_control_markup(system_text)
            if _profile is None
            else _profile.rewrite_control(system_text)
        )
        tools = neutralize_tool_descriptions(tools, None, _profile)

        try:
            with httpx.Client(
                timeout = 10,
                headers = self._auth_headers,
                trust_env = False,
                verify = _local_ssl_context(),
            ) as client:

                def _tokenize(text: str) -> int:
                    r = client.post(
                        f"{self.base_url}/tokenize",
                        json = {"content": text, "add_special": True},
                    )
                    if r.status_code != 200:
                        if strict:
                            raise RuntimeError("llama-server tokenizer failed")
                        return 0
                    tokens = r.json().get("tokens", [])
                    if not isinstance(tokens, list):
                        if strict:
                            raise RuntimeError("llama-server tokenizer returned invalid tokens")
                        return 0
                    return len(tokens)

                from core.inference.mcp_images import prepare_image_turn_boundaries

                template_messages = prepare_image_turn_boundaries(
                    list(messages) if messages else [],
                    getattr(self, "_chat_template_override", None)
                    or getattr(self, "_chat_template", None),
                )
                if system_text:
                    template_messages = [
                        {"role": "system", "content": system_text}
                    ] + template_messages

                def _render_count(render_messages) -> tuple[Optional[int], bool]:
                    """(count or None, refused). Only a 500 is a template refusal; 503 = loading or no slot."""
                    try:
                        # /apply-template renders tool schemas; omitting them undercounts.
                        template_body = {"messages": render_messages}
                        if tools:
                            template_body["tools"] = llama_grammar_tools(tools)
                        # Layered over load-time --chat-template-kwargs.
                        if chat_template_kwargs:
                            template_body["chat_template_kwargs"] = chat_template_kwargs
                        if continue_final_message:
                            template_body["continue_final_message"] = True
                            template_body["add_generation_prompt"] = False
                        if prefer_native:
                            if should_abort is not None and should_abort():
                                raise CountAborted()
                            try:
                                native = client.post(
                                    f"{self.base_url}/v1/chat/completions/input_tokens",
                                    json = template_body,
                                )
                                if native.status_code == 200:
                                    count = native.json().get("input_tokens")
                                    if type(count) is int and count > 0:
                                        return count, False
                            except Exception:
                                pass
                            if should_abort is not None and should_abort():
                                raise CountAborted()
                        resp = client.post(
                            f"{self.base_url}/apply-template",
                            json = template_body,
                        )
                        if resp.status_code != 200:
                            return None, resp.status_code == 500
                        prompt = resp.json().get("prompt", "")
                        if isinstance(prompt, str):
                            if should_abort is not None and should_abort():
                                raise CountAborted()
                            return _tokenize(prompt), False
                    except CountAborted:
                        # Not a template failure. Must precede the generic except.
                        raise
                    except Exception:
                        pass
                    return None, False

                # Qwen3.5+ templates raise on an empty render; retry behind an empty user turn.
                renders_empty = not template_messages or (
                    len(template_messages) == 1
                    and isinstance(template_messages[0], dict)
                    and template_messages[0].get("role") == "assistant"
                )
                with_user_turn = [{"role": "user", "content": ""}] + template_messages
                if renders_empty and self._empty_chat_render_refused:
                    count, _refused = _render_count(with_user_turn)
                else:
                    count, _refused = _render_count(template_messages)
                    if count is None and _refused and renders_empty:
                        if should_abort is not None and should_abort():
                            raise CountAborted()
                        count, _ = _render_count(with_user_turn)
                        if count is not None:
                            self._empty_chat_render_refused = True
                if count is not None:
                    return count

                # The text fallback undercounts (~30%), so strict callers error instead.
                if strict:
                    raise RuntimeError("llama-server could not render the chat template")

                # Fallback: plain text plus serialized tools.
                parts = []
                if system_text:
                    parts.append(system_text)
                for msg in messages or []:
                    if isinstance(msg, dict):
                        parts.append(_block_text(msg.get("content", "")))
                if tools:
                    try:
                        parts.append(json.dumps(tools, ensure_ascii = False))
                    except Exception:
                        pass
                return _tokenize("\n".join(p for p in parts if p))
        except Exception:
            if strict:
                raise
            return 0

    def detect_audio_type(self) -> Optional[str]:
        """Detect audio/TTS codec; swallows errors (use _strict to distinguish)."""
        try:
            return self._detect_audio_type_strict()
        except Exception as e:
            logger.debug(f"Audio type detection failed: {e}")
            return None

    def codec_failure(self) -> Optional[str]:
        """The ModelScope missing-repo sentence from this thread's last load_model codec init."""
        return getattr(self._codec_failure, "message", None)

    def _apply_detected_audio(
        self,
        detected: Optional[str],
        audio_codec_path: Optional[str] = None,
    ) -> bool:
        """Apply a probed audio codec under self._lock. Returns True to continue
        the load (codec inited OK, or nothing to init), False to abort (server
        unhealthy or codec init failed). Shared by the fast-path retry and the
        main load path."""
        if detected in ("snac", "bicodec", "dac"):
            with self._lock:
                if not self._healthy:
                    return False
                try:
                    self.init_audio_codec(detected, audio_codec_path)
                    self._is_audio = True
                    self._audio_type = detected
                except Exception as exc:
                    logger.warning("Failed to init audio codec '%s': %s", detected, exc)
                    self._audio_probed = False
                    self._codec_failure.message = modelscope_missing(exc)
                    return False
        elif detected:
            # Track the type but keep _is_audio False: GGUF TTS routing only fires for snac/bicodec/dac.
            with self._lock:
                if not self._healthy:
                    return False
                self._audio_type = detected
        from utils.models.model_config import is_audio_input_type

        self._has_audio_input = bool(is_audio_input_type(self._audio_type)) or bool(
            self._mmproj_has_audio
        )
        return True

    def _detect_audio_type_strict(self) -> Optional[str]:
        """Codec name on match, None on non-audio, raises on transport/JSON errors."""
        if not self.is_loaded:
            return None
        with httpx.Client(timeout = 10, headers = self._auth_headers, trust_env = False) as client:

            def _detok(tid: int) -> str:
                # Non-200 means marker not in vocab; transport/JSON errors still raise.
                r = client.post(f"{self.base_url}/detokenize", json = {"tokens": [tid]})
                if r.status_code != 200:
                    return ""
                return r.json().get("content", "")

            def _tok(text: str) -> list[int]:
                r = client.post(
                    f"{self.base_url}/tokenize",
                    json = {"content": text, "add_special": False},
                )
                if r.status_code != 200:
                    return []
                return r.json().get("tokens", [])

            if "<custom_token_" in _detok(128258) and "<custom_token_" in _detok(128259):
                return "snac"
            if len(_tok("<|AUDIO|>")) == 1 and len(_tok("<|audio_eos|>")) == 1:
                return "csm"
            if len(_tok("<|startoftranscript|>")) == 1:
                return "whisper"
            # Gemma 3n: <audio_soft_token>; Gemma 4: <|audio|> (not csm's <|AUDIO|>).
            if len(_tok("<audio_soft_token>")) == 1 or len(_tok("<|audio|>")) == 1:
                return "audio_vlm"
            if len(_tok("<|bicodec_semantic_0|>")) == 1 and len(_tok("<|bicodec_global_0|>")) == 1:
                return "bicodec"
            if len(_tok("<|c1_0|>")) == 1 and len(_tok("<|c2_0|>")) == 1:
                return "dac"
        return None

    # (template, stop_tokens, needs_token_ids); matches InferenceBackend._generate_*.
    _TTS_PROMPTS = {
        "snac": (
            "<custom_token_3>{text}<|eot_id|><custom_token_4>",
            ["<custom_token_2>"],
            True,
        ),
        "bicodec": (
            "<|task_tts|><|start_content|>{text}<|end_content|><|start_global_token|>",
            ["<|im_end|>", "</s>"],
            False,
        ),
        "dac": (
            build_dac_tts_prompt("{text}"),
            ["<|im_end|>", "<|audio_end|>"],
            False,
        ),
    }

    _codec_mgr = None

    @staticmethod
    def _unload_audio_codec() -> None:
        if LlamaCppBackend._codec_mgr is None:
            return
        LlamaCppBackend._codec_mgr.unload()
        LlamaCppBackend._codec_mgr = None
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    def init_audio_codec(
        self,
        audio_type: str,
        audio_codec_path: Optional[str] = None,
    ) -> None:
        """Load the audio codec at model load time (mirrors the non-GGUF path)."""
        import torch
        from core.inference.audio_codecs import AudioCodecManager

        if LlamaCppBackend._codec_mgr is None:
            LlamaCppBackend._codec_mgr = AudioCodecManager()

        # CPU for a zero-offload server: CUDA would hold VRAM the load claims not to hold.
        device = "cuda" if torch.cuda.is_available() and not self.holds_no_vram else "cpu"
        model_repo_path = audio_codec_path

        if audio_type == "bicodec" and model_repo_path is None:
            from core.inference.audio_codecs import resolve_bicodec_repo_path
            from utils.utils import hf_env_offline
            model_repo_path = resolve_bicodec_repo_path(local_files_only = hf_env_offline())

        # The codec holds memory the load-time fit never priced: VRAM on CUDA, and on a
        # unified-memory host the very pool the fit sized even when it lands on the CPU.
        # Cleared first, as the model is already listed while the codec allocates.
        self._vram_fit_context_length = None
        LlamaCppBackend._codec_mgr.load_codec(audio_type, device, model_repo_path = model_repo_path)
        logger.info(f"Loaded audio codec for GGUF TTS: {audio_type}")

    def generate_audio_response(
        self,
        text: str,
        audio_type: str,
        temperature: float = 0.6,
        top_p: float = 0.95,
        top_k: int = 50,
        min_p: float = 0.0,
        max_new_tokens: int = 2048,
        repetition_penalty: float = 1.1,
        cancel_event: Optional[threading.Event] = None,
        stats_holder: Optional[dict] = None,
    ) -> tuple:
        """
        Generate TTS audio via llama-server /completion + codec decode.
        Returns (wav_bytes, sample_rate).

        ``cancel_event`` lets a Stop or a forced model swap end the request: the
        decode is one blocking POST, so a watcher closes the client out from under
        it rather than polling. Raises RuntimeError once cancelled.
        """
        if audio_type not in self._TTS_PROMPTS:
            raise RuntimeError(f"GGUF TTS does not support '{audio_type}' codec.")

        tpl, stop, need_ids = self._TTS_PROMPTS[audio_type]
        # Codec delimiters are the only structure to break in a raw prompt.
        from core.inference.chat_template_helpers import neutralize_tts_prompt_text

        payload: dict = {
            "prompt": tpl.format(text = neutralize_tts_prompt_text(text, audio_type)),
            "stream": False,
            "n_predict": max_new_tokens,
            "temperature": temperature,
            "top_p": top_p,
            "top_k": top_k if top_k >= 0 else 0,
            "min_p": min_p,
            "repeat_penalty": repetition_penalty,
        }
        if stop:
            payload["stop"] = stop
        if need_ids:
            payload["n_probs"] = 1

        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("Audio generation cancelled")

        # Scale timeout with the request from this backend's 300s floor.
        # Imported here to keep the module import acyclic.
        from core.inference.orchestrator import _audio_generation_timeout

        read_timeout = _audio_generation_timeout(max_new_tokens, base = _GGUF_AUDIO_READ_TIMEOUT)
        with httpx.Client(
            timeout = httpx.Timeout(read_timeout, connect = 10),
            headers = self._auth_headers,
            trust_env = False,
            verify = _local_ssl_context(),
        ) as client:
            finished = threading.Event()
            watcher: Optional[threading.Thread] = None
            if cancel_event is not None:

                def _close_when_cancelled() -> None:
                    while not finished.wait(0.05):
                        if cancel_event.is_set():
                            # Closing mid-request is the only way to unblock the post.
                            with contextlib.suppress(Exception):
                                client.close()
                            return

                watcher = threading.Thread(target = _close_when_cancelled, daemon = True)
                watcher.start()
            try:
                resp = client.post(f"{self.base_url}/completion", json = payload)
            except httpx.RequestError:
                if cancel_event is not None and cancel_event.is_set():
                    raise RuntimeError("Audio generation cancelled") from None
                raise
            finally:
                finished.set()
                if watcher is not None:
                    watcher.join(timeout = 0.5)
            if resp.status_code != 200:
                raise RuntimeError(f"llama-server returned {resp.status_code}: {resp.text}")

        # Codec decode can't be interrupted, so check cancel first.
        if cancel_event is not None and cancel_event.is_set():
            raise RuntimeError("Audio generation cancelled")

        data = resp.json()
        if stats_holder is not None:
            stats_holder["stats"] = {"truncated": data.get("stop_type") == "limit"}
        token_ids = (
            [p["id"] for p in data.get("completion_probabilities", []) if "id" in p]
            if need_ids
            else None
        )

        import torch

        device = "cuda" if torch.cuda.is_available() else "cpu"
        return LlamaCppBackend._codec_mgr.decode(
            audio_type, device, token_ids = token_ids, text = data.get("content", "")
        )
